// Content for Stand Up (node g27, ages 12–15, Chapter 4) — NEW v2 build to GDD 27 (mechanic-embodying), the
// teen bystander-to-upstander node (Thread B · Safety, Consent & Boundaries) — the gender thread's CALL TO
// ACTION on gender-based violence & harassment. "From bystander to upstander — safely." 84 researched,
// India-grounded scenarios across the GBV-&-rights → spot-harassment → safety-first → the-5-Ds → after-&-
// support → be-the-upstander arc, each encoded as one of the shared v2 play actions (branch / reflect /
// strike-rewrite / role-play / sort / spot / match) — no binary "tap the right card". Lead mechanics: branch
// (the five-moves chooser ×22 — the same 5 Ds engine as Speak Up g19), role-play (the words ×11), spot
// (catch the harassment ×10). Teaches: what GBV/harassment is and your rights, spotting it, the FIVE SAFE
// MOVES (the 5 Ds — Direct, Distract, Delegate, Delay, Document), and how to support afterwards.
// SAFETY-FIRST, NON-GRAPHIC: NEVER confront danger alone ("can I help safely?"; distract/get-help/de-escalate,
// don't chase); the TARGET IS NEVER TO BLAME (freezing is normal; "it wasn't your fault"; "I believe you");
// survivor-centred support (believe, comfort, their-call-to-report, protect dignity); real routes — a trusted
// adult, Women Helpline 181, ERSS 112, Childline 1098. Builds on g19 (Speak Up); prereq g26. Rendered by the
// shared engine (components/games/v2-engine.tsx). gameId "stand-up". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — What GBV is, and your rights —
  {"id":"st-001","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"Eve-teasing is just harmless fun or a compliment.\"","myth":{"un":"Street 'eve-teasing' is harmless fun or a compliment.","re":"It's harassment, it makes people feel unsafe and it's a rights violation.","why":"Unwanted comments and following are not compliments."},"relearn":"'Eve-teasing' is harassment, not a compliment or harmless fun.","persona":"Riya","source":"GBV / India"},
  {"id":"st-002","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"If someone's harassed, they must have invited it by how they dressed or acted.\"","myth":{"un":"People get harassed because of how they dress or act.","re":"Harassment is always the harasser's choice; nothing 'invites' it.","why":"The target is never to blame."},"relearn":"Harassment is never the target's fault, whatever they wore or did.","persona":"any","source":"no victim-blaming"},
  {"id":"st-003","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"Only girls and women face harassment.\"","myth":{"un":"Only girls and women get harassed.","re":"Anyone can face harassment; it's wrong whoever the target is.","why":"GBV harms people of every gender."},"relearn":"Harassment can target anyone, and it's always wrong.","persona":"Veer","source":"GBV / inclusive"},
  {"id":"st-004","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"Harassment is normal, you just have to put up with it.\"","myth":{"un":"Harassment is normal and you just have to tolerate it.","re":"No one has to accept harassment; everyone has the right to be safe.","why":"'Normal' doesn't make it acceptable."},"relearn":"No one has to put up with harassment; safety is a right.","persona":"Riya","source":"rights"},
  {"id":"st-005","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"What counts as harassment is totally subjective, so nothing is.\"","myth":{"un":"Harassment is so subjective that nothing really counts.","re":"Unwanted, unwelcome sexual or gendered behaviour is harassment, that's clear.","why":"Impact on the target is what defines it."},"relearn":"Unwanted, unwelcome sexual or gendered behaviour is harassment.","persona":"any","source":"definition"},
  {"id":"st-006","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"Boys can't be expected to control themselves, it's nature.\"","myth":{"un":"Boys can't help harassing; it's just nature.","re":"Everyone can control their behaviour; harassment is a choice.","why":"This 'excuse' insults boys and excuses harm."},"relearn":"Harassment is a choice; 'boys can't help it' is a false excuse.","persona":"Veer","source":"accountability"},
  {"id":"st-007","cat":"gbv-and-rights","type":"sort","persona":"any","source":"rights","relearn":"Everyone has the right to safety, respect and to refuse unwanted touch.","hook":"Sort: a right everyone has, or not?","items":[{"id":"a","text":"To feel safe in public"},{"id":"b","text":"To be respected"},{"id":"c","text":"To harass others"},{"id":"d","text":"To say no to unwanted touch"},{"id":"e","text":"To ask for help when unsafe"},{"id":"f","text":"To touch anyone you like"}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"no","label":"Not a right","valence":"neg"}],"key":{"a":"right","b":"right","c":"no","d":"right","e":"right","f":"no"}},
  {"id":"st-008","cat":"gbv-and-rights","type":"sort","persona":"any","source":"definition","relearn":"Unwanted, persistent or following behaviour is harassment; a one-off kind word isn't.","hook":"Sort: harassment, or not?","items":[{"id":"a","text":"Unwanted staring and comments"},{"id":"b","text":"A genuine, respectful compliment once"},{"id":"c","text":"Following someone who's uncomfortable"},{"id":"d","text":"Saying hello to a friend"},{"id":"e","text":"Repeated creepy messages after a no"},{"id":"f","text":"A welcome, agreed high-five"}],"bins":[{"id":"harassment","label":"Harassment","valence":"neg"},{"id":"ok","label":"Okay","valence":"pos"}],"key":{"a":"harassment","b":"ok","c":"harassment","d":"ok","e":"harassment","f":"ok"}},
  {"id":"st-009","cat":"gbv-and-rights","type":"sort","persona":"any","source":"forms of GBV","relearn":"Groping, unwanted sexual messages and sexual rumours are all harassment.","hook":"Sort: a form of GBV/harassment, or something else?","items":[{"id":"a","text":"Groping on a bus"},{"id":"b","text":"Sending unwanted sexual messages"},{"id":"c","text":"A friendly team huddle"},{"id":"d","text":"Spreading sexual rumours about someone"},{"id":"e","text":"Threatening to share private photos"},{"id":"f","text":"Two friends sharing earphones"}],"bins":[{"id":"gbv","label":"Harassment/GBV","valence":"neg"},{"id":"no","label":"Not","valence":"pos"}],"key":{"a":"gbv","b":"gbv","c":"no","d":"gbv","e":"gbv","f":"no"}},
  {"id":"st-010","cat":"gbv-and-rights","type":"match","persona":"any","source":"rights / help","relearn":"Rights are backed by consent, laws and helplines.","hook":"Match the right to what protects it.","pairs":[{"left":"Right to be safe","right":"Laws against harassment"},{"left":"Right to say no","right":"Consent"},{"left":"Right to help","right":"Helplines like 181"},{"left":"Right to be believed","right":"A trusted adult who listens"},{"left":"Right to move freely","right":"Public space for everyone"}]},
  {"id":"st-011","cat":"gbv-and-rights","type":"match","persona":"any","source":"rights","relearn":"Each harassment myth has a clear, rights-based answer.","hook":"Match the myth to the truth that beats it.","pairs":[{"left":"\"It's a compliment\"","right":"It's harassment"},{"left":"\"They invited it\"","right":"Never the target's fault"},{"left":"\"Just put up with it\"","right":"Safety is a right"},{"left":"\"Boys can't help it\"","right":"Harassment is a choice"},{"left":"\"Only girls face it\"","right":"Anyone can be a target"}]},
  {"id":"st-012","cat":"gbv-and-rights","type":"reflect","hook":"Lensy: everyone deserves to move through the world feeling safe. Agree?","prompt":"What do you think?","options":["Completely","Yes","It's a basic right"],"affirm":"Safety and respect are everyone's right, no exceptions.","relearn":"Everyone has the right to feel safe and respected.","persona":"any","source":"rights"},
  {"id":"st-013","cat":"gbv-and-rights","type":"reflect","hook":"Lensy: knowing harassment is never the target's fault, who does that free?","prompt":"What do you think?","options":["The people harmed","Everyone","Us, to help"],"affirm":"Dropping victim-blame frees survivors and frees us to help.","relearn":"Harassment is the harasser's fault; that truth helps everyone act.","persona":"any","source":"no victim-blaming"},
  {"id":"st-014","cat":"gbv-and-rights","type":"strike-rewrite","hook":"\"Reporting harassment just causes trouble; better to stay quiet.\"","myth":{"un":"Reporting harassment only causes trouble.","re":"Reporting is your right and can stop harm; help exists.","why":"Silence protects harassers, not you."},"relearn":"Reporting harassment is your right and can stop the harm.","persona":"any","source":"rights / help"},
  // — Spot the harassment —
  {"id":"st-015","cat":"spot-harassment","type":"spot","persona":"Riya","source":"public harassment (India)","relearn":"Repeated unwanted contact and following on transport is harassment.","hook":"On the bus. Spot the two red flags.","scene":[{"id":"a","text":"A man keeps 'accidentally' pressing against a girl who moves away","trick":true},{"id":"b","text":"The bus is crowded","trick":false},{"id":"c","text":"He follows her when she shifts seats","trick":true},{"id":"d","text":"The conductor calls out the next stop","trick":false},{"id":"e","text":"Two students chat about their timetable","trick":false}],"why":"Repeated unwanted contact and following are harassment, not 'the crowd'."},
  {"id":"st-016","cat":"spot-harassment","type":"spot","persona":"any","source":"street harassment (India)","relearn":"Street comments, whistling and following are harassment.","hook":"On the street. Spot the two red flags.","scene":[{"id":"a","text":"A group makes comments and whistles at someone passing","trick":true},{"id":"b","text":"It's a busy market","trick":false},{"id":"c","text":"They start following and filming her","trick":true},{"id":"d","text":"A vendor arranges fruit on his cart","trick":false},{"id":"e","text":"Two friends look for an auto","trick":false}],"why":"Comments, whistling and following are 'eve-teasing', which is harassment."},
  {"id":"st-017","cat":"spot-harassment","type":"spot","persona":"any","source":"peer harassment","relearn":"Cornering or blocking someone who wants to leave is harassment.","hook":"In the corridor. Spot the two red flags.","scene":[{"id":"a","text":"A boy corners a girl who's clearly trying to leave","trick":true},{"id":"b","text":"The bell rings","trick":false},{"id":"c","text":"He blocks her path and won't let her pass","trick":true},{"id":"d","text":"Lockers line the wall","trick":false},{"id":"e","text":"Students head to their next class","trick":false}],"why":"Cornering and blocking someone who wants to leave is harassment."},
  {"id":"st-018","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV (links g12)","relearn":"Unwanted sexual messages and image threats online are harassment.","hook":"Online. Spot the two red flags.","scene":[{"id":"a","text":"Someone sends repeated unwanted sexual messages","trick":true},{"id":"b","text":"It's a school group chat","trick":false},{"id":"c","text":"They threaten to share private images","trick":true},{"id":"d","text":"A classmate posts the homework","trick":false},{"id":"e","text":"Two members plan a study call","trick":false}],"why":"Unwanted sexual messages and threats to share images are serious harassment."},
  {"id":"st-019","cat":"spot-harassment","type":"spot","persona":"any","source":"peer / consent","relearn":"Unwanted touch excused as 'just fun' is still harassment.","hook":"At a gathering. Spot the two red flags hiding as 'fun'.","scene":[{"id":"a","text":"Someone keeps touching a friend who keeps removing their hand","trick":true},{"id":"b","text":"Music is playing","trick":false},{"id":"c","text":"\"Relax, it's just a bit of fun\"","trick":true},{"id":"d","text":"Snacks are laid out on a table","trick":false},{"id":"e","text":"Two friends take a group photo","trick":false}],"why":"Touch after a clear 'no', excused as 'fun', is still harassment."},
  {"id":"st-020","cat":"spot-harassment","type":"spot","persona":"any","source":"definition","relearn":"Mutual, welcome interaction isn't harassment; unwanted, persistent behaviour is.","hook":"Two of these are harassment. Spot those two red flags.","scene":[{"id":"a","text":"Two friends happily joking around","trick":false},{"id":"b","text":"Persisting after someone says stop","trick":true},{"id":"c","text":"Comments about a stranger's body","trick":true},{"id":"d","text":"Waving hello to a classmate","trick":false},{"id":"e","text":"A high-five after a match","trick":false}],"why":"Mutual joking is fine; persisting past 'stop' and body comments are harassment."},
  {"id":"st-021","cat":"spot-harassment","type":"spot","persona":"Veer","source":"self-accountability","relearn":"Reading harassment includes honestly checking your own behaviour.","hook":"Check yourself: spot the two red flags in your own behaviour.","scene":[{"id":"a","text":"Complimenting a friend who enjoys it","trick":false},{"id":"b","text":"Commenting on a stranger's body 'as a joke'","trick":true},{"id":"c","text":"Not stopping when someone looks uncomfortable","trick":true},{"id":"d","text":"Asking once and accepting a no","trick":false},{"id":"e","text":"Thanking a friend for their help","trick":false}],"why":"Being an upstander includes checking your own behaviour honestly."},
  {"id":"st-022","cat":"spot-harassment","type":"spot","persona":"any","source":"reading the scene","relearn":"Body language can signal someone being harassed needs help.","hook":"Spot the two body-language red flags that someone needs help.","scene":[{"id":"a","text":"A person looks tense and keeps backing away","trick":true},{"id":"b","text":"It's an ordinary evening","trick":false},{"id":"c","text":"They glance around for help","trick":true},{"id":"d","text":"They are reading a notice on the wall","trick":false},{"id":"e","text":"They are chatting easily with a friend","trick":false}],"why":"Tension, backing away and looking for help can signal someone in trouble."},
  {"id":"st-023","cat":"spot-harassment","type":"sort","persona":"any","source":"definition","relearn":"Unwanted, repeated or sexualising behaviour is harassment; ordinary friendliness isn't.","hook":"Sort: harassment, or a normal interaction?","items":[{"id":"a","text":"Repeated unwanted DMs after 'no'"},{"id":"b","text":"A friend asking to study together"},{"id":"c","text":"Catcalling a passer-by"},{"id":"d","text":"Saying 'good game' after a match"},{"id":"e","text":"Touching after a hand is moved away"},{"id":"f","text":"Wishing a classmate happy birthday"}],"bins":[{"id":"harassment","label":"Harassment","valence":"neg"},{"id":"normal","label":"Normal","valence":"pos"}],"key":{"a":"harassment","b":"normal","c":"harassment","d":"normal","e":"harassment","f":"normal"}},
  {"id":"st-024","cat":"spot-harassment","type":"sort","persona":"any","source":"awareness","relearn":"Harassment can happen anywhere, not just in 'bad' places.","hook":"Sort: where harassment can happen?","items":[{"id":"a","text":"On the street / bus"},{"id":"b","text":"At school"},{"id":"c","text":"Online"},{"id":"d","text":"Only in 'bad' places"},{"id":"e","text":"At a family function"},{"id":"f","text":"Only after dark"}],"bins":[{"id":"yes","label":"It can happen here","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"yes","b":"yes","c":"yes","d":"myth","e":"yes","f":"myth"}},
  {"id":"st-025","cat":"spot-harassment","type":"reflect","hook":"Lensy: once you can name harassment clearly, you can act on it. See that?","prompt":"What do you think?","options":["Yes","Naming it helps","I can spot it now"],"affirm":"Naming harassment is the first step to standing up to it.","relearn":"Clearly naming harassment is the first step to acting.","persona":"any","source":"awareness"},
  {"id":"st-026","cat":"spot-harassment","type":"reflect","hook":"Lensy: have you seen something like this and weren't sure what it was?","prompt":"Be honest.","options":["Yes","Maybe","Now I'd know"],"affirm":"Now you can name it, and naming it is where standing up begins.","relearn":"Recognising harassment you've witnessed helps you respond next time.","persona":"any","source":"awareness"},
  // — Safety first —
  {"id":"st-027","cat":"safety-first","type":"branch","hook":"You see harassment, but the harasser looks aggressive and you're alone.","options":[{"text":"Don't confront directly; distract or get help","consequence":"You help without risking yourself.","outcome":"safe","best":true},{"text":"Charge in and confront them","consequence":"For danger, distract or get help, never confront alone."}],"debrief":"Your safety comes first; for danger, use distract or delegate, not direct.","relearn":"When it's dangerous, distract or get help, don't confront alone.","persona":"any","source":"safety-first (verified)"},
  {"id":"st-028","cat":"safety-first","type":"branch","hook":"Before acting, what's your first question?","options":[{"text":"\"Can I help safely here?\"","consequence":"You choose a safe move that fits.","outcome":"assessed","best":true},{"text":"\"How do I look brave?\"","consequence":"Start with 'can I help safely?', not 'how do I look'."}],"debrief":"Always start by assessing whether you can help safely.","relearn":"Ask 'can I help safely?' before you act.","persona":"any","source":"safety-first"},
  {"id":"st-029","cat":"safety-first","type":"branch","hook":"It's risky to act alone right now.","options":[{"text":"Get others, a conductor, adult, or call a helpline","consequence":"Numbers and authority make it safer for everyone.","outcome":"delegate","best":true},{"text":"Handle it solo to seem tough","consequence":"Don't act alone in danger; bring others in."}],"debrief":"Delegating, getting others, is often the safest, strongest move.","relearn":"In risky moments, get others rather than acting alone.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-030","cat":"safety-first","type":"branch","hook":"You stepped in and it's escalating dangerously.","options":[{"text":"Step back and call for help / 112","consequence":"You de-escalate and bring real help.","outcome":"safe","best":true},{"text":"Keep pushing the confrontation","consequence":"If it escalates, step back and call for help."}],"debrief":"If a situation turns dangerous, disengage and call for help.","relearn":"If it escalates, step back and call for help (112).","persona":"Counsellor","source":"safety-first / ERSS"},
  {"id":"st-031","cat":"safety-first","type":"branch","hook":"You want to help but freeze, unsure if it's 'your place'.","options":[{"text":"Pick the smallest safe action, even just standing near or filming safely","consequence":"A small safe act still helps.","outcome":"upstander","best":true},{"text":"Decide it's not your business","consequence":"Even a small safe action, presence, distraction, helps."}],"debrief":"You don't have to be a hero; any small safe action counts.","relearn":"Any small, safe action is better than doing nothing.","persona":"any","source":"safety-first"},
  {"id":"st-032","cat":"safety-first","type":"branch","hook":"A friend wants to chase down a harasser who's fled.","options":[{"text":"Don't chase; focus on the person harmed and report it","consequence":"You stay safe and support the target.","outcome":"safe","best":true},{"text":"Chase the harasser","consequence":"Don't chase; support the target and report instead."}],"debrief":"Chasing risks safety; supporting the target and reporting is better.","relearn":"Don't chase a harasser; support the target and report.","persona":"Veer","source":"safety-first"},
  {"id":"st-033","cat":"safety-first","type":"sort","hook":"Sort: a safe way to help, or a risky one?","items":[{"id":"a","text":"Distracting the harasser"},{"id":"b","text":"Physically fighting them"},{"id":"c","text":"Getting others / calling help"},{"id":"d","text":"Threatening them back"},{"id":"e","text":"Standing near so the target isn't alone"},{"id":"f","text":"Chasing them down to confront"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Distraction, getting help and presence are safe; fighting, threats and chasing are risky.","persona":"any","source":"safety-first"},
  {"id":"st-034","cat":"safety-first","type":"sort","hook":"Sort: prioritises safety, or ignores it?","items":[{"id":"a","text":"Checking for danger first"},{"id":"b","text":"Acting on impulse in a risky scene"},{"id":"c","text":"Calling for backup"},{"id":"d","text":"Going in alone against a group"},{"id":"e","text":"Moving to where there are people"},{"id":"f","text":"Cornering the harasser yourself"}],"bins":[{"id":"safe","label":"Safety-first","valence":"pos"},{"id":"no","label":"Ignores safety","valence":"neg"}],"key":{"a":"safe","b":"no","c":"safe","d":"no","e":"safe","f":"no"},"relearn":"Safety-first means assessing danger, getting backup and moving to people, not impulse or solo risk.","persona":"any","source":"safety-first"},
  {"id":"st-035","cat":"safety-first","type":"reflect","hook":"Lensy: 'your safety comes first' isn't selfish, it's how you help without becoming a second victim. Agree?","prompt":"What do you think?","options":["Yes","Makes sense","Safe helps more"],"affirm":"Staying safe yourself is what lets you actually help.","relearn":"Keeping yourself safe is what makes helping possible.","persona":"any","source":"safety-first"},
  {"id":"st-036","cat":"safety-first","type":"reflect","hook":"Lensy: knowing you have safe options, do you feel more able to act?","prompt":"What do you think?","options":["Yes","Less helpless","I can do something"],"affirm":"Safe options mean you're never stuck choosing 'hero or nothing'.","relearn":"Safe options free you from 'be a hero or do nothing'.","persona":"any","source":"empowerment"},
  {"id":"st-037","cat":"safety-first","type":"strike-rewrite","hook":"\"To help, you have to physically confront the harasser.\"","myth":{"un":"Helping means confronting the harasser head-on.","re":"The safest, most effective help is often distraction or getting others.","why":"Direct confrontation can be dangerous and isn't required."},"relearn":"You don't have to confront a harasser; safe moves work better.","persona":"any","source":"safety-first / 5 Ds"},
  // — The five safe moves (the 5 Ds) —
  {"id":"st-038","cat":"five-ds","type":"branch","hook":"DISTRACT. A person is being harassed; it's not safe to confront the harasser.","options":[{"text":"Interrupt: ask the target the time, or pretend you know them","consequence":"The harasser is thrown off; the target can leave.","outcome":"distract","best":true},{"text":"Do nothing","consequence":"A casual interruption (Distract) safely breaks it up."}],"debrief":"The Distract move derails harassment without a confrontation.","relearn":"Distract: interrupt casually so the target can get away.","persona":"any","source":"5 Ds / Distract (verified)"},
  {"id":"st-039","cat":"five-ds","type":"branch","hook":"DELEGATE. The situation needs more than you alone.","options":[{"text":"Get a conductor, teacher, adult, or call a helpline","consequence":"Numbers and authority step in.","outcome":"delegate","best":true},{"text":"Try to manage it all yourself","consequence":"Delegate, bring in others or authority."}],"debrief":"The Delegate move brings in people who can help safely.","relearn":"Delegate: get others or authority to help.","persona":"any","source":"5 Ds / Delegate"},
  {"id":"st-040","cat":"five-ds","type":"branch","hook":"DOCUMENT. It's safe, and a record could help the person later.","options":[{"text":"Film/note safely, then give it to the target to use as they wish","consequence":"There's evidence, and the target stays in control.","outcome":"document","best":true},{"text":"Post it publicly for laughs","consequence":"Document for the target's use, never for public mockery."}],"debrief":"The Document move records safely, for the target, not for posting.","relearn":"Document only if safe, and give it to the target, never post it.","persona":"any","source":"5 Ds / Document"},
  {"id":"st-041","cat":"five-ds","type":"branch","hook":"DELAY. The moment has passed, but the person looked shaken.","options":[{"text":"Check in after: 'are you okay? that wasn't okay'","consequence":"They feel supported and less alone.","outcome":"delay","best":true},{"text":"Move on as if nothing happened","consequence":"Checking in afterward (Delay) really helps."}],"debrief":"The Delay move supports the person after the moment.","relearn":"Delay: check in afterwards, 'are you okay?'.","persona":"Riya","source":"5 Ds / Delay"},
  {"id":"st-042","cat":"five-ds","type":"branch","hook":"DIRECT. It's clearly safe, and a calm word could stop it.","options":[{"text":"Calmly say 'that's not okay, leave them alone'","consequence":"Naming it can stop the behaviour.","outcome":"direct","best":true},{"text":"Stay silent though it's safe to speak","consequence":"When it's safe, a calm Direct word can work."}],"debrief":"The Direct move, only when safe, names the harassment plainly.","relearn":"Direct: when safe, calmly name that it's not okay.","persona":"Veer","source":"5 Ds / Direct"},
  {"id":"st-043","cat":"five-ds","type":"branch","hook":"Which D fits: a dangerous harasser, target needs to get away now?","options":[{"text":"Distract (and Delegate), not Direct","consequence":"You help safely without confrontation.","outcome":"distract","best":true},{"text":"Direct confrontation","consequence":"For danger, Distract and Delegate are safer than Direct."}],"debrief":"Match the move to safety; for danger, Distract or Delegate.","relearn":"For dangerous harassers, choose Distract or Delegate over Direct.","persona":"any","source":"5 Ds / matching"},
  {"id":"st-044","cat":"five-ds","type":"branch","hook":"Which D fits: harassment over, person is upset and alone?","options":[{"text":"Delay, check in and support them","consequence":"They feel seen and cared for.","outcome":"delay","best":true},{"text":"Nothing, it's done","consequence":"Afterwards, Delay (check in) is exactly the move."}],"debrief":"After the moment, Delay supports the person.","relearn":"After harassment, use Delay to support the person.","persona":"any","source":"5 Ds"},
  {"id":"st-045","cat":"five-ds","type":"branch","hook":"Which D fits: a big crowd, you can't act alone safely?","options":[{"text":"Delegate, rally others or alert authority","consequence":"Shared action makes it safe and strong.","outcome":"delegate","best":true},{"text":"Push in by yourself","consequence":"In a crowd, Delegate, get others to act with you."}],"debrief":"When alone-action is unsafe, Delegate to others.","relearn":"When you can't act alone safely, Delegate.","persona":"any","source":"5 Ds"},
  {"id":"st-046","cat":"five-ds","type":"role-play","hook":"You use the Distract move on a bus.","setup":"Interrupt naturally. Say:","yourLine":[{"text":"\"Hey! There you are, come sit with me, I've been looking for you.\"","best":true},{"text":"Say nothing"}],"relearn":"A friendly 'come sit with me' is a perfect Distract.","persona":"Riya","source":"5 Ds / Distract voice"},
  {"id":"st-047","cat":"five-ds","type":"role-play","hook":"You use the Delegate move.","setup":"Rally help. Say:","yourLine":[{"text":"\"Excuse me, this person needs help, can you assist?\"","best":true},{"text":"Hope someone else notices"}],"relearn":"Asking specific people for help gets a real response.","persona":"any","source":"5 Ds / Delegate voice"},
  {"id":"st-048","cat":"five-ds","type":"role-play","hook":"You use the Direct move (it's safe).","setup":"Be calm and clear. Say:","yourLine":[{"text":"\"That's not okay. Leave them alone.\"","best":true},{"text":"\"...\" (freeze)"}],"relearn":"A calm, clear 'that's not okay' is a strong Direct move.","persona":"Veer","source":"5 Ds / Direct voice"},
  {"id":"st-049","cat":"five-ds","type":"match","hook":"Match the D to what it does.","pairs":[{"left":"Distract","right":"Break it up indirectly"},{"left":"Delegate","right":"Get others/authority"},{"left":"Document","right":"Record safely, for the target"},{"left":"Delay","right":"Support after"},{"left":"Direct","right":"Calmly name it, when safe"}],"relearn":"Each D is a distinct, safe way to help.","persona":"any","source":"5 Ds"},
  {"id":"st-050","cat":"five-ds","type":"match","hook":"Match the situation to the best D.","pairs":[{"left":"Dangerous harasser","right":"Distract / Delegate"},{"left":"Safe to speak","right":"Direct"},{"left":"After the event","right":"Delay"},{"left":"Safe to record","right":"Document"},{"left":"Need adult help","right":"Fetch a teacher"}],"relearn":"Choose the D that fits the safety of the moment.","persona":"any","source":"5 Ds"},
  {"id":"st-051","cat":"five-ds","type":"sort","hook":"Sort: a real D move, or not one of the five?","items":[{"id":"a","text":"Distract"},{"id":"b","text":"Delegate"},{"id":"c","text":"Dominate"},{"id":"d","text":"Delay"},{"id":"e","text":"Document"},{"id":"f","text":"Direct"}],"bins":[{"id":"real","label":"A real D","valence":"pos"},{"id":"no","label":"Not a D","valence":"neg"}],"key":{"a":"real","b":"real","c":"no","d":"real","e":"real","f":"real"},"relearn":"The five Ds are Distract, Delegate, Document, Delay, Direct, not 'dominate'.","persona":"any","source":"5 Ds"},
  {"id":"st-052","cat":"five-ds","type":"sort","hook":"Sort: helps safely, or escalates?","items":[{"id":"a","text":"Pretending to know the target"},{"id":"b","text":"Shoving the harasser"},{"id":"c","text":"Alerting a guard"},{"id":"d","text":"Yelling threats"},{"id":"e","text":"Pulling the bus bell for the driver"},{"id":"f","text":"Blocking his path to fight"}],"bins":[{"id":"safe","label":"Helps safely","valence":"pos"},{"id":"escalates","label":"Escalates","valence":"neg"}],"key":{"a":"safe","b":"escalates","c":"safe","d":"escalates","e":"safe","f":"escalates"},"relearn":"Distraction and alerting help safely; shoving and threats escalate.","persona":"any","source":"5 Ds / safety"},
  {"id":"st-053","cat":"five-ds","type":"reflect","hook":"Lensy: with five moves, there's always at least one safe way to help. Reassuring?","prompt":"What do you think?","options":["Yes","Always an option","I can pick one"],"affirm":"Five Ds means you're never stuck with 'nothing'.","relearn":"With five Ds, there's always a safe way to help.","persona":"any","source":"5 Ds"},
  // — After & support —
  {"id":"st-054","cat":"after-support","type":"role-play","hook":"Right after, the person who was harassed looks shaken.","setup":"Support them. Say:","yourLine":[{"text":"\"Are you okay? That wasn't okay, and it wasn't your fault.\"","best":true},{"text":"\"Why didn't you say something?\""}],"relearn":"Support afterwards: 'are you okay? it wasn't your fault'.","persona":"Riya","source":"after-support (verified)"},
  {"id":"st-055","cat":"after-support","type":"role-play","hook":"They're scared to walk home alone after it.","setup":"Offer real help. Say:","yourLine":[{"text":"\"I'll walk with you, or we can call someone.\"","best":true},{"text":"\"You'll be fine, bye.\""}],"relearn":"Offering to accompany someone is concrete, caring support.","persona":"any","source":"after-support"},
  {"id":"st-056","cat":"after-support","type":"role-play","hook":"They're unsure whether to report it.","setup":"Respect their choice and inform. Say:","yourLine":[{"text":"\"It's your call, and I'll help you report it if you want, 181 or 112 can help.\"","best":true},{"text":"\"You have to report it right now.\""}],"relearn":"Offer help to report, on their terms, and name 181/112.","persona":"Counsellor","source":"after-support / helplines"},
  {"id":"st-057","cat":"after-support","type":"role-play","hook":"A friend confides they were harassed and feels ashamed.","setup":"Reassure them. Say:","yourLine":[{"text":"\"This is not your fault. I believe you, and I'm here.\"","best":true},{"text":"\"What were you doing there?\""}],"relearn":"Tell a survivor: it's not your fault, I believe you, I'm here.","persona":"any","source":"believe survivors"},
  {"id":"st-058","cat":"after-support","type":"role-play","hook":"Others start gossiping about the person who was harassed.","setup":"Protect them. Say:","yourLine":[{"text":"\"Let's not gossip, they need support, not rumours.\"","best":true},{"text":"Join the gossip"}],"relearn":"Protect a survivor's dignity; shut down the gossip.","persona":"any","source":"after-support / dignity"},
  {"id":"st-059","cat":"after-support","type":"branch","hook":"A friend was harassed and doesn't know where to turn.","options":[{"text":"Help them reach a trusted adult or call 181 / 112 / 1098","consequence":"They get real support and options.","outcome":"caring","best":true},{"text":"Tell them to just forget it","consequence":"Help them reach a trusted adult or a helpline."}],"debrief":"Knowing the helplines turns 'I don't know' into real help.","relearn":"Route a friend to a trusted adult or 181/112/1098.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"st-060","cat":"after-support","type":"branch","hook":"Something serious happened and your friend swears you to secrecy.","options":[{"text":"For safety, gently insist on telling a trusted adult","consequence":"They get protection, even if upset now.","outcome":"protective","best":true},{"text":"Keep the dangerous secret","consequence":"Serious harm needs a trusted adult; safety over secrecy."}],"debrief":"Some things are too serious to keep secret; safety comes first.","relearn":"For serious harm, tell a trusted adult, even if asked to keep it secret.","persona":"any","source":"safeguarding"},
  {"id":"st-061","cat":"after-support","type":"strike-rewrite","hook":"\"If they didn't fight back, it wasn't really that bad.\"","myth":{"un":"If someone didn't fight back, it wasn't serious.","re":"Freezing is a normal response; it doesn't lessen the harm or their right to support.","why":"People freeze; that's not consent or 'fine'."},"relearn":"Freezing is normal; not fighting back doesn't make harm 'okay'.","persona":"any","source":"trauma-informed"},
  {"id":"st-062","cat":"after-support","type":"strike-rewrite","hook":"\"Supporting the person means hunting down the harasser.\"","myth":{"un":"Real support means going after the harasser.","re":"The best support centres the person, believe, comfort, help them choose next steps.","why":"Revenge isn't support and isn't safe."},"relearn":"Support centres the person harmed, not revenge on the harasser.","persona":"any","source":"survivor-centred"},
  {"id":"st-063","cat":"after-support","type":"strike-rewrite","hook":"\"Bringing it up again just upsets them; better to never mention it.\"","myth":{"un":"You should never mention it again.","re":"A gentle check-in shows you care; let them lead how much to talk.","why":"Being there beats pretending it didn't happen."},"relearn":"A gentle check-in helps; let the person lead the conversation.","persona":"any","source":"after-support"},
  {"id":"st-064","cat":"after-support","type":"reflect","hook":"Lensy: 'I believe you' can be the most powerful thing you say. Feel that?","prompt":"What do you think?","options":["Yes","Belief matters","I'll say it"],"affirm":"Being believed helps a survivor more than almost anything.","relearn":"'I believe you' is powerful support for someone harmed.","persona":"any","source":"believe survivors"},
  {"id":"st-065","cat":"after-support","type":"match","persona":"Counsellor","source":"helplines (verified)","relearn":"India has 181 (women), 112 (emergency), 1098 (children), plus a trusted adult and a calm listener.","hook":"Match the need to the helpline (India).","pairs":[{"left":"A woman in distress","right":"Women Helpline 181"},{"left":"An emergency now","right":"Emergency 112"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Someone who'll step in","right":"A trusted adult"},{"left":"Someone to just listen","right":"A calm friend"}]},
  {"id":"st-066","cat":"after-support","type":"reflect","hook":"Lensy: 112 for emergencies, 181 for women, 1098 for a child, which would you save in your phone today?","prompt":"Pick what fits you.","options":["112 emergency","181 women's helpline","1098 child helpline","All three"],"affirm":"Saving the right number now means you can reach real help in seconds later.","relearn":"112 is emergency, 181 is the women's line, 1098 is the child line.","persona":"any","source":"helplines"},
  // — Be the upstander —
  {"id":"st-067","cat":"be-the-upstander","type":"branch","hook":"Capstone: on a bus, a man is harassing a girl who looks scared. You're alone.","options":[{"text":"Distract, sit by her, then alert the conductor","consequence":"You help safely and bring in authority.","outcome":"upstander","best":true},{"text":"Look away","consequence":"Distract plus alerting the conductor helps safely."}],"debrief":"Distract + Delegate is the safe upstander combo in public.","relearn":"On transport, distract and alert staff, the safe upstander move.","persona":"Riya","source":"consolidation"},
  {"id":"st-068","cat":"be-the-upstander","type":"branch","hook":"In a corridor, friends are cornering and harassing a junior.","options":[{"text":"Break it up and, if needed, get a teacher","consequence":"You stop it and the junior is safe.","outcome":"upstander","best":true},{"text":"Laugh along with your friends","consequence":"Even with friends, break it up and get a teacher."}],"debrief":"Standing up sometimes means stopping your own friends.","relearn":"You can stand up even when the harassers are your friends.","persona":"Veer","source":"peer / courage"},
  {"id":"st-069","cat":"be-the-upstander","type":"branch","hook":"Online, a group is sexually harassing a classmate in a chat.","options":[{"text":"Don't pile on; report it and check on the classmate","consequence":"You cut the pile-on and support them.","outcome":"upstander","best":true},{"text":"Stay in the chat and watch","consequence":"Report online harassment and support the target."}],"debrief":"Online upstanding: report, don't pile on, support the target.","relearn":"For online harassment: report it and support the person.","persona":"any","source":"online GBV"},
  {"id":"st-070","cat":"be-the-upstander","type":"branch","hook":"You're a boy and your mates expect you to join 'harmless' harassment.","options":[{"text":"Refuse and shift the vibe; be the ally","consequence":"You break the group's harmful norm.","outcome":"ally","best":true},{"text":"Join in to belong","consequence":"Being an ally means refusing to join the harassment."}],"debrief":"Boys have huge power to stop harassment by refusing to join.","relearn":"As an ally, refuse to join harassment and shift the group.","persona":"Veer","source":"ally / norms"},
  {"id":"st-071","cat":"be-the-upstander","type":"branch","hook":"You froze last time and regret it. It's happening again.","options":[{"text":"Use one safe move this time, even a small one","consequence":"You act, and it gets easier.","outcome":"growth","best":true},{"text":"Freeze again and feel worse","consequence":"Freezing once is okay; try one safe move now."}],"debrief":"Freezing once is human; you can choose a safe move next time.","relearn":"After freezing once, you can choose a safe action next time.","persona":"any","source":"growth / courage"},
  {"id":"st-072","cat":"be-the-upstander","type":"branch","hook":"Acting might make you unpopular with the harasser's friends.","options":[{"text":"Help anyway, using a safe move","consequence":"You do the right thing; the right people respect it.","outcome":"brave","best":true},{"text":"Stay popular and silent","consequence":"Someone's safety outweighs a harasser's friends' approval."}],"debrief":"Doing right can cost a little popularity; it's worth it.","relearn":"Help even if it risks the harasser's friends' approval.","persona":"any","source":"courage"},
  {"id":"st-073","cat":"be-the-upstander","type":"role-play","hook":"You want to set the tone so your group never harasses.","setup":"Lead it. Say:","yourLine":[{"text":"\"We don't do that, it's not funny and it's not okay.\"","best":true},{"text":"Stay quiet and let it slide"}],"relearn":"You can set a no-harassment tone in your group.","persona":"Veer","source":"ally / leadership"},
  {"id":"st-074","cat":"be-the-upstander","type":"role-play","hook":"A younger student asks you how to handle harassment they're facing.","setup":"Guide them. Say:","yourLine":[{"text":"\"It's not your fault, tell a trusted adult, and you can call 1098.\"","best":true},{"text":"\"Just ignore it.\""}],"relearn":"Guide a younger student: not your fault, tell an adult, call 1098.","persona":"Counsellor","source":"mentoring / helplines"},
  {"id":"st-075","cat":"be-the-upstander","type":"role-play","hook":"You're rallying a friend to help you intervene safely.","setup":"Team up. Say:","yourLine":[{"text":"\"Come with me, let's check they're okay, together.\"","best":true},{"text":"Go in alone"}],"relearn":"Teaming up makes intervening safer and easier.","persona":"any","source":"delegate / teamwork"},
  {"id":"st-076","cat":"be-the-upstander","type":"spot","hook":"Spot the upstander in this scene.","scene":[{"id":"a","text":"One person quietly alerts a guard","trick":true},{"id":"b","text":"Most people film for laughs","trick":false},{"id":"c","text":"Another sits with the target","trick":true},{"id":"d","text":"The corridor is busy at lunchtime","trick":false},{"id":"e","text":"Two students walk past without looking","trick":false}],"why":"The upstanders alert help and support the target, not film for laughs.","relearn":"Upstanders get help and support the target; they don't film for fun.","persona":"any","source":"spotting"},
  {"id":"st-077","cat":"be-the-upstander","type":"spot","hook":"Spot your safest first move here.","scene":[{"id":"a","text":"You could quietly alert the nearby guard","trick":true},{"id":"b","text":"The harasser is much bigger","trick":false},{"id":"c","text":"You could grab the harasser","trick":false},{"id":"d","text":"You could move the target toward staff and others","trick":true},{"id":"e","text":"You could stand alone shouting at him","trick":false}],"why":"With a bigger harasser, quietly alerting the guard or moving toward staff is the safe first move.","relearn":"When outmatched, alert authority rather than confront.","persona":"any","source":"safety-first"},
  {"id":"st-078","cat":"be-the-upstander","type":"reflect","hook":"Lensy: one upstander can change a whole scene, and inspire others. Believe it?","prompt":"What do you think?","options":["Yes","One person matters","I can be that one"],"affirm":"One person acting safely often unfreezes everyone else.","relearn":"One safe upstander can change a scene and free others to help.","persona":"any","source":"agency"},
  {"id":"st-079","cat":"be-the-upstander","type":"reflect","hook":"Lensy: what kind of person do you want to be when you see harassment?","prompt":"Pick one.","options":["One who acts safely","One who supports","One who refuses to join","All of these"],"affirm":"That's the upstander the world needs, safe, supportive, and not silent.","relearn":"You can choose to be a safe, supportive, non-silent upstander.","persona":"any","source":"identity"},
  {"id":"st-080","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"It's not my problem if it's not happening to me.\"","myth":{"un":"Harassment isn't my problem unless it's happening to me.","re":"In a community, everyone's safety is everyone's business.","why":"Bystanders who act make everyone safer."},"relearn":"Others' safety is your business too; upstanders make everyone safer.","persona":"any","source":"allyship"},
  {"id":"st-081","cat":"be-the-upstander","type":"sort","hook":"Sort: an upstander action, or a bystander non-action?","items":[{"id":"a","text":"Alerting a guard"},{"id":"b","text":"Filming for laughs"},{"id":"c","text":"Checking the person is okay"},{"id":"d","text":"Walking away unbothered"},{"id":"e","text":"Sitting with the target until help comes"},{"id":"f","text":"Laughing along with the harasser"}],"bins":[{"id":"up","label":"Upstander","valence":"pos"},{"id":"by","label":"Bystander","valence":"neg"}],"key":{"a":"up","b":"by","c":"up","d":"by","e":"up","f":"by"},"relearn":"Upstanders get help and support; bystanders film or walk away.","persona":"any","source":"upstander vs bystander"},
  {"id":"st-082","cat":"be-the-upstander","type":"reflect","hook":"Lensy: biggest take-away from Stand Up?","prompt":"Pick your motto.","options":["Safety first, always","Five safe ways to help","Never the target's fault","Be the upstander"],"affirm":"Help safely, support the person, and never be silent, that's standing up.","relearn":"Stand up safely, support the person, and never stay silent.","persona":"any","source":"consolidation"},
  {"id":"st-083","cat":"be-the-upstander","type":"reflect","hook":"Lensy: knowing the safe moves and the helplines, ready to stand up?","prompt":"What do you think?","options":["Ready","Yes","I know what to do"],"affirm":"You've got the moves, the limits and the helplines, you're ready.","relearn":"With safe moves and helplines, you're ready to stand up.","persona":"any","source":"consolidation"},
  {"id":"st-084","cat":"gbv-and-rights","type":"reflect","hook":"Lensy: a world where bystanders act is a world where harassment shrinks. Worth building?","prompt":"What do you think?","options":["Yes","Worth it","Let's build it"],"affirm":"Every safe upstander shrinks harassment's space, that's the change.","relearn":"When bystanders act safely, harassment has less room to thrive.","persona":"any","source":"vision"},
  {"id":"st-900","cat":"after-support","type":"role-play","persona":"any","source":"believe survivors","relearn":"Lead with belief: 'I believe you' steadies someone who was harassed.","hook":"A classmate finally tells you what happened on the bus.","setup":"She's watching your face to see if you doubt her. Say:","yourLine":[{"text":"\"I believe you. Thank you for telling me.\"","best":true},{"text":"\"Are you sure that's really what happened?\""}]},
  {"id":"st-901","cat":"after-support","type":"role-play","persona":"Riya","source":"after-support / freezing is normal","relearn":"Freezing is normal; it never means it was their fault.","hook":"He says he just froze and didn't shout or run.","setup":"He sounds ashamed of freezing. Say:","yourLine":[{"text":"\"Freezing is normal. It wasn't your fault at all.\"","best":true},{"text":"\"Why didn't you just push him off?\""}]},
  {"id":"st-902","cat":"after-support","type":"role-play","persona":"any","source":"let them lead","relearn":"Let the person lead how much they want to talk.","hook":"A friend goes quiet after telling you a little.","setup":"You want to help without pushing. Say:","yourLine":[{"text":"\"We can talk as much or as little as you want.\"","best":true},{"text":"\"Tell me every single detail right now.\""}]},
  {"id":"st-903","cat":"after-support","type":"role-play","persona":"Counsellor","source":"after-support / helplines","relearn":"Offer to report on their terms; name 181 and 112.","hook":"She asks what her options are after being followed.","setup":"You lay out help without deciding for her. Say:","yourLine":[{"text":"\"It's your call. If you want, we can call 181 or 112 together.\"","best":true},{"text":"\"You must file a complaint today, no excuses.\""}]},
  {"id":"st-904","cat":"after-support","type":"role-play","persona":"any","source":"accompany","relearn":"Offering to go with someone is concrete support.","hook":"He's nervous about telling a teacher alone.","setup":"You can make it less scary. Say:","yourLine":[{"text":"\"I'll come with you to the teacher if you want.\"","best":true},{"text":"\"Just go in by yourself, it's fine.\""}]},
  {"id":"st-905","cat":"after-support","type":"role-play","persona":"any","source":"dignity / shut down gossip","relearn":"Shut down gossip to protect a survivor's dignity.","hook":"In the canteen, people start whispering her name and laughing.","setup":"You can change the room's tone. Say:","yourLine":[{"text":"\"Stop, she's been through enough. Drop it.\"","best":true},{"text":"\"So what actually happened, tell me everything!\""}]},
  {"id":"st-906","cat":"after-support","type":"role-play","persona":"Veer","source":"ally / accountability","relearn":"As an ally, name that none of it was her fault.","hook":"Your friends keep hinting she 'asked for it' by her clothes.","setup":"You step in for her. Say:","yourLine":[{"text":"\"What she wore is irrelevant. None of this is on her.\"","best":true},{"text":"\"Yeah, maybe she shouldn't have worn that.\""}]},
  {"id":"st-907","cat":"after-support","type":"role-play","persona":"any","source":"check-in / delay","relearn":"A gentle check-in the next day shows you still care.","hook":"It's the day after; she's back in class, very quiet.","setup":"You check in without a crowd around. Say:","yourLine":[{"text":"\"Hey, just checking in. How are you doing today?\"","best":true},{"text":"\"You're over it now, right? Good.\""}]},
  {"id":"st-908","cat":"after-support","type":"role-play","persona":"any","source":"survivor-centred","relearn":"Centre what they need, not revenge on the harasser.","hook":"He's furious and wants you to help him fight the guy.","setup":"You keep it safe and centred on him. Say:","yourLine":[{"text":"\"I get the anger. Right now let's get you safe and supported.\"","best":true},{"text":"\"Let's go find him and teach him a lesson.\""}]},
  {"id":"st-909","cat":"after-support","type":"role-play","persona":"Counsellor","source":"safeguarding / trusted adult","relearn":"For serious harm, gently insist on a trusted adult.","hook":"She tells you something serious but begs you to tell no one.","setup":"You honour her and her safety. Say:","yourLine":[{"text":"\"I'm with you. This is serious, so let's tell one trusted adult.\"","best":true},{"text":"\"Okay, I'll keep it totally secret forever.\""}]},
  {"id":"st-910","cat":"after-support","type":"role-play","persona":"any","source":"believe survivors","relearn":"Don't make someone prove it; belief comes first.","hook":"He worries no one will believe a boy was harassed.","setup":"You make belief unconditional. Say:","yourLine":[{"text":"\"I believe you. This happens to boys too, and it's wrong.\"","best":true},{"text":"\"Boys don't really get harassed though.\""}]},
  {"id":"st-911","cat":"after-support","type":"role-play","persona":"Riya","source":"after-support / not your fault","relearn":"Reassure: it wasn't your fault, full stop.","hook":"She keeps replaying what she 'should' have done differently.","setup":"You take the blame off her. Say:","yourLine":[{"text":"\"You didn't cause this. The only one at fault is him.\"","best":true},{"text":"\"Yeah, you could've handled it better.\""}]},
  {"id":"st-912","cat":"after-support","type":"role-play","persona":"any","source":"after-support / online","relearn":"Believe and help save proof on their terms after online harm.","hook":"A friend got threatening messages and wants to delete everything.","setup":"You support her choice and options. Say:","yourLine":[{"text":"\"I believe you. We can screenshot for proof first, your call.\"","best":true},{"text":"\"Just block him and forget it ever happened.\""}]},
  {"id":"st-913","cat":"after-support","type":"role-play","persona":"any","source":"dignity / no pressure","relearn":"Don't pressure someone to perform being 'fine'.","hook":"Adults keep telling her to smile and move on already.","setup":"You give her room to not be okay. Say:","yourLine":[{"text":"\"You don't have to be fine for anyone. Take your time.\"","best":true},{"text":"\"Come on, just smile, it's not a big deal.\""}]},
  {"id":"st-914","cat":"after-support","type":"role-play","persona":"Counsellor","source":"helplines / women","relearn":"Name Women Helpline 181 as a real route for her.","hook":"An older girl asks where a woman can turn for help.","setup":"You give her a real, named route. Say:","yourLine":[{"text":"\"Women Helpline 181 is there for exactly this, any time.\"","best":true},{"text":"\"Honestly, no one really helps with this stuff.\""}]},
  {"id":"st-915","cat":"after-support","type":"role-play","persona":"any","source":"after-support / younger student","relearn":"Guide a younger child: not your fault, tell an adult, call 1098.","hook":"A small junior tells you an older student scared her.","setup":"You steady her and point to help. Say:","yourLine":[{"text":"\"It's not your fault. Tell a trusted adult, or call Childline 1098.\"","best":true},{"text":"\"You're too little to understand, ignore it.\""}]},
  {"id":"st-916","cat":"after-support","type":"role-play","persona":"any","source":"after-support / siblings","relearn":"Believe family too; harassment by a relative still counts.","hook":"Your cousin says a relative makes her deeply uncomfortable.","setup":"You don't dismiss it because it's family. Say:","yourLine":[{"text":"\"I believe you. It still counts, even if he's family.\"","best":true},{"text":"\"He's family, you must be imagining it.\""}]},
  {"id":"st-917","cat":"after-support","type":"role-play","persona":"Veer","source":"ally / refuse to join","relearn":"Refuse to laugh; name the harm to your own group.","hook":"After it happened, your mates are still making jokes about her.","setup":"You stop being part of it. Say:","yourLine":[{"text":"\"This isn't funny. She was hurt. I'm not laughing.\"","best":true},{"text":"\"Haha, yeah, good one.\""}]},
  {"id":"st-918","cat":"after-support","type":"role-play","persona":"any","source":"after-support / believe + act","relearn":"Believing AND helping report beats believing silently.","hook":"She's told you, and now asks if you'll actually back her up.","setup":"You commit to standing with her. Say:","yourLine":[{"text":"\"I believe you, and I'll back you up if you report it.\"","best":true},{"text":"\"I believe you, but leave me out of it.\""}]},
  {"id":"st-919","cat":"after-support","type":"role-play","persona":"Counsellor","source":"trauma-informed","relearn":"Ask what they need rather than taking over.","hook":"You're not sure what would actually help her right now.","setup":"You let her define help. Say:","yourLine":[{"text":"\"What would help most right now, talking, or just sitting?\"","best":true},{"text":"\"I know exactly what you need, do as I say.\""}]},
  {"id":"st-920","cat":"after-support","type":"role-play","persona":"any","source":"after-support / no blame for not reporting","relearn":"Never blame someone for not reporting yet.","hook":"She says she's not ready to report what happened.","setup":"You respect her pace. Say:","yourLine":[{"text":"\"That's okay. The option stays open whenever you're ready.\"","best":true},{"text":"\"If you don't report, it's basically your fault if it repeats.\""}]},
  {"id":"st-921","cat":"after-support","type":"branch","persona":"Counsellor","source":"helplines (verified)","relearn":"Route a friend to a trusted adult or 181/112/1098.","hook":"A friend was harassed and has no idea where to turn next.","options":[{"text":"Help her reach a trusted adult or call 181 / 112 / 1098","consequence":"She gets real, named options and support.","outcome":"caring","best":true},{"text":"Tell her to just deal with it herself","consequence":"She's left alone; point her to a trusted adult or a helpline."}],"debrief":"Knowing the helplines turns 'I don't know' into real help."},
  {"id":"st-922","cat":"after-support","type":"branch","persona":"any","source":"safeguarding","relearn":"Serious harm is too big to keep secret; tell a trusted adult.","hook":"He shares something serious and makes you swear total secrecy.","options":[{"text":"Gently insist on telling one trusted adult, for his safety","consequence":"He gets real protection, even if upset for now.","outcome":"protective","best":true},{"text":"Promise to keep the dangerous secret","consequence":"He stays at risk; serious harm needs a trusted adult."}],"debrief":"Some things are too serious to keep secret; safety comes first."},
  {"id":"st-923","cat":"after-support","type":"branch","persona":"any","source":"dignity / gossip","relearn":"Shut down gossip; protect the person's dignity.","hook":"A video clip and rumours about her are spreading in the group chat.","options":[{"text":"Refuse to share, ask others to delete it, and report it","consequence":"The spread slows and her dignity is protected.","outcome":"protective","best":true},{"text":"Forward it 'just so people know'","consequence":"You deepen the harm; don't spread it, help shut it down."}],"debrief":"Don't pass on clips or rumours; protecting dignity is support."},
  {"id":"st-924","cat":"after-support","type":"branch","persona":"Riya","source":"believe survivors","relearn":"Believe first; doubting a survivor deepens the harm.","hook":"A classmate tells you what happened and braces for disbelief.","options":[{"text":"Tell her you believe her and ask how you can help","consequence":"She feels safe and less alone.","outcome":"caring","best":true},{"text":"Quiz her on whether she's exaggerating","consequence":"She shuts down; lead with belief, not interrogation."}],"debrief":"Being believed helps a survivor more than almost anything."},
  {"id":"st-925","cat":"after-support","type":"branch","persona":"any","source":"survivor-centred","relearn":"Support centres the person harmed, not revenge.","hook":"He wants you to help him corner the harasser after school.","options":[{"text":"Steer it to safety: get him support and report it","consequence":"He's safe and supported; no one gets hurt.","outcome":"safe","best":true},{"text":"Agree to help confront the harasser","consequence":"It risks more harm; support him, don't seek revenge."}],"debrief":"Revenge isn't support and isn't safe; centre the person harmed."},
  {"id":"st-926","cat":"after-support","type":"branch","persona":"Counsellor","source":"helplines / accompany","relearn":"Offer to call a helpline together, on their terms.","hook":"She wants help but is too shaken to call anyone alone.","options":[{"text":"Offer to sit with her and call 181 together if she wants","consequence":"She isn't alone; the call feels possible.","outcome":"caring","best":true},{"text":"Hand her the number and walk off","consequence":"She freezes again; offer to make the call with her."}],"debrief":"Doing it together makes reaching help far easier."},
  {"id":"st-927","cat":"after-support","type":"branch","persona":"any","source":"after-support / check-in","relearn":"A gentle check-in beats pretending nothing happened.","hook":"A week on, you're unsure whether to bring it up with her again.","options":[{"text":"Quietly ask how she's doing and let her lead","consequence":"She knows you still care, on her terms.","outcome":"caring","best":true},{"text":"Never mention it, to be 'safe'","consequence":"She feels forgotten; a gentle check-in shows you care."}],"debrief":"Being there beats pretending it didn't happen; let her lead."},
  {"id":"st-928","cat":"after-support","type":"branch","persona":"any","source":"after-support / not your fault","relearn":"Take blame off the survivor, even gently-meant advice can sting.","hook":"After he tells you, your first instinct is to give safety 'tips'.","options":[{"text":"Reassure him it wasn't his fault before anything else","consequence":"He feels supported, not lectured.","outcome":"caring","best":true},{"text":"Start listing what he should've done","consequence":"It sounds like blame; reassure first, advise only if asked."}],"debrief":"Lead with 'it wasn't your fault', not a list of fixes."},
  {"id":"st-929","cat":"after-support","type":"strike-rewrite","persona":"any","source":"trauma-informed","relearn":"Freezing is normal; it never makes the harm less serious.","hook":"\"She didn't scream or run, so it can't have been that bad.\"","myth":{"un":"If she didn't scream or run, it wasn't serious.","re":"Freezing is a normal response to fear; the harm and her right to support stand.","why":"The body often freezes; that isn't consent or 'fine'."}},
  {"id":"st-930","cat":"after-support","type":"strike-rewrite","persona":"any","source":"survivor-centred","relearn":"Support centres the person harmed, not punishing the harasser.","hook":"\"Real support means going and sorting out the harasser yourself.\"","myth":{"un":"Supporting her means going after the harasser.","re":"The best support centres her: believe, comfort, help her choose next steps.","why":"Revenge isn't support and puts more people at risk."}},
  {"id":"st-931","cat":"after-support","type":"strike-rewrite","persona":"any","source":"after-support / their choice to report","relearn":"Support someone's own choice about reporting; don't force it.","hook":"\"A real friend would make her go report it right now.\"","myth":{"un":"You should force them to report immediately.","re":"Offer to help and share options, but let them decide if and when to report.","why":"Pushing past their consent repeats the harm of having control taken away."}},
  {"id":"st-932","cat":"after-support","type":"strike-rewrite","persona":"any","source":"believe survivors","relearn":"Belief comes first; survivors rarely lie about this.","hook":"\"People probably make these stories up for attention.\"","myth":{"un":"People usually make harassment up for attention.","re":"False reports are rare; believing someone is the safest, kindest start.","why":"Doubt drives survivors into silence."}},
  {"id":"st-933","cat":"after-support","type":"strike-rewrite","persona":"Veer","source":"GBV / inclusive","relearn":"Boys can be harassed too and deserve the same support.","hook":"\"Boys can't really be harassed, so he's overreacting.\"","myth":{"un":"Boys can't really be harassed.","re":"Anyone can be harassed; a boy harmed deserves belief and support too.","why":"Pretending it can't happen leaves boys with nowhere to turn."}},
  {"id":"st-934","cat":"after-support","type":"strike-rewrite","persona":"any","source":"no victim-blaming","relearn":"Not reporting is never the survivor's fault.","hook":"\"If she didn't report it, anything that happens next is on her.\"","myth":{"un":"Not reporting makes future harm her fault.","re":"Reporting is her choice; only the harasser is ever responsible for harm.","why":"Blaming her for staying silent adds to the harm."}},
  {"id":"st-935","cat":"after-support","type":"strike-rewrite","persona":"any","source":"safeguarding","relearn":"Serious harm is too big to keep secret; tell a trusted adult.","hook":"\"A good friend always keeps every secret, no matter what.\"","myth":{"un":"A real friend keeps every secret, no matter what.","re":"For serious harm, a true friend helps you tell one trusted adult.","why":"Some secrets are too dangerous to carry alone."}},
  {"id":"st-936","cat":"after-support","type":"strike-rewrite","persona":"any","source":"dignity / gossip","relearn":"Passing on the story isn't 'support', it's more harm.","hook":"\"Telling everyone what happened to her is just spreading awareness.\"","myth":{"un":"Telling everyone her story spreads awareness.","re":"Sharing her story without consent harms her; let her control what's told.","why":"Her dignity and choice come before any 'awareness'."}},
  {"id":"st-937","cat":"after-support","type":"strike-rewrite","persona":"any","source":"after-support / time","relearn":"There's no deadline on being affected; healing isn't a clock.","hook":"\"It was weeks ago, she should be totally over it by now.\"","myth":{"un":"After a few weeks she should be over it.","re":"People heal at their own pace; there's no deadline on being affected.","why":"Rushing someone to 'move on' isn't support."}},
  {"id":"st-938","cat":"after-support","type":"strike-rewrite","persona":"Counsellor","source":"helplines (verified)","relearn":"Helplines like 181 give real, free help, not just 'trouble'.","hook":"\"Calling a helpline just makes a fuss and never actually helps.\"","myth":{"un":"Helplines just make a fuss and never help.","re":"Women Helpline 181 offers real, free, confidential help and options.","why":"Naming a real route turns good intentions into support."}},
  {"id":"st-939","cat":"after-support","type":"strike-rewrite","persona":"any","source":"after-support / men can support","relearn":"Anyone can be a supportive listener, not just girls.","hook":"\"Comforting someone after harassment is a girl's job, not a boy's.\"","myth":{"un":"Comforting a survivor is only a girl's job.","re":"Anyone can listen and support; it's about care, not gender.","why":"Survivors need allies of every gender."}},
  {"id":"st-940","cat":"after-support","type":"strike-rewrite","persona":"any","source":"after-support / small acts","relearn":"Small acts, sitting with someone, believing them, are real support.","hook":"\"Unless you can fix it completely, there's no point helping at all.\"","myth":{"un":"If you can't fix everything, helping is pointless.","re":"Small acts, sitting with her, believing her, are real, meaningful support.","why":"You don't have to fix it to matter."}},
  {"id":"st-941","cat":"after-support","type":"reflect","persona":"any","source":"it's not your fault","relearn":"'It's not your fault' lifts the shame off someone who was harmed.","hook":"Lensy: 'None of this was your fault' can lift a weight off someone. Feel that?","prompt":"What do you think?","options":["Yes","Shame isn't theirs","I'll say it"],"affirm":"Naming that the blame sits with the harasser frees them from carrying it."},
  {"id":"st-942","cat":"after-support","type":"reflect","persona":"any","source":"asking what they need","relearn":"Ask 'what do you need?' instead of taking over someone's situation.","hook":"Lensy: 'What do you need from me right now?' beats deciding for them. Agree?","prompt":"What do you think?","options":["Yes","I'll ask first","Their call"],"affirm":"Asking what they need keeps them in control of their own recovery."},
  {"id":"st-943","cat":"after-support","type":"reflect","persona":"any","source":"after-support / freezing","relearn":"Freezing is normal and never the survivor's fault.","hook":"Lensy: if someone froze instead of fighting, does that change whose fault it is?","prompt":"What do you think?","options":["No, it's never theirs","Freezing is normal","Still the harasser's"],"affirm":"Freezing is a normal response; the fault is always the harasser's."},
  {"id":"st-944","cat":"after-support","type":"reflect","persona":"any","source":"let them lead","relearn":"Letting someone set the pace is itself support.","hook":"Lensy: would you let a friend decide how much to share, even if you're curious?","prompt":"What do you think?","options":["Yes","Their pace","I'd let them lead"],"affirm":"Letting someone lead the conversation is real support."},
  {"id":"st-945","cat":"after-support","type":"reflect","persona":"Riya","source":"after-support / not your fault","relearn":"Saying 'it wasn't your fault' can lift a real weight.","hook":"Lensy: imagine hearing 'none of this was your fault'. How might that land?","prompt":"What do you think?","options":["Like relief","It would help","A weight off"],"affirm":"Hearing 'it wasn't your fault' can lift a heavy weight."},
  {"id":"st-946","cat":"after-support","type":"reflect","persona":"any","source":"dignity","relearn":"Refusing to gossip is a way of standing with someone.","hook":"Lensy: not passing on a rumour, does that feel like doing something, or nothing?","prompt":"What do you think?","options":["Doing something","It protects them","Quiet support"],"affirm":"Refusing to spread it is a quiet, real way to stand with someone."},
  {"id":"st-947","cat":"after-support","type":"reflect","persona":"any","source":"after-support / accompany","relearn":"Going with someone makes a hard step feel possible.","hook":"Lensy: would just being beside a friend while they ask for help matter?","prompt":"What do you think?","options":["A lot","Yes","I'd go with them"],"affirm":"Simply being beside someone can make a hard step feel possible."},
  {"id":"st-948","cat":"after-support","type":"reflect","persona":"Veer","source":"ally","relearn":"You can choose support over a laugh, even with your group.","hook":"Lensy: if your own friends laughed, could you choose to support her instead?","prompt":"What do you think?","options":["Yes","I'd choose her","Support over a laugh"],"affirm":"Choosing care over a laugh, even with your own crew, is upstanding."},
  {"id":"st-949","cat":"after-support","type":"match","persona":"Counsellor","source":"helplines (verified)","relearn":"India: 181 women, 112 emergency, 1098 children, plus a trusted adult and a calm listener.","hook":"Match each need to where it leads.","pairs":[{"left":"A woman in distress","right":"Women Helpline 181"},{"left":"An emergency right now","right":"Emergency 112"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Someone at school","right":"A trusted teacher"},{"left":"Just needs to be heard","right":"A calm listener"}]},
  {"id":"st-950","cat":"after-support","type":"match","persona":"any","source":"after-support / supportive words","relearn":"Match each fear to a supportive thing you can say.","hook":"Match what they feel to what helps to hear.","pairs":[{"left":"\"It was my fault\"","right":"\"None of this is on you\""},{"left":"\"No one will believe me\"","right":"\"I believe you\""},{"left":"\"I froze, I'm weak\"","right":"\"Freezing is normal\""},{"left":"\"I'm so alone\"","right":"\"I'm right here with you\""},{"left":"\"What do I even do\"","right":"\"We can figure it out together\""}]},
  {"id":"st-951","cat":"after-support","type":"match","persona":"any","source":"after-support / five Ds (delay)","relearn":"Match each supportive move to what it does after.","hook":"Match the after-action to its purpose.","pairs":[{"left":"Check in next day","right":"Shows you still care"},{"left":"Believe them","right":"Lifts the shame"},{"left":"Offer to report together","right":"Makes help possible"},{"left":"Shut down gossip","right":"Protects dignity"},{"left":"Tell a trusted adult","right":"Handles serious harm"}]},
  {"id":"st-952","cat":"after-support","type":"match","persona":"any","source":"after-support / what not to say","relearn":"Match each unhelpful line to the kinder one that replaces it.","hook":"Swap each harmful line for a kinder one.","pairs":[{"left":"\"Why were you there?\"","right":"\"I'm so glad you told me\""},{"left":"\"Just forget it\"","right":"\"Take all the time you need\""},{"left":"\"You're overreacting\"","right":"\"Your feelings make sense\""},{"left":"\"What were you wearing?\"","right":"\"This wasn't your fault\""},{"left":"\"Why didn't you fight?\"","right":"\"Freezing is normal\""}]},
  {"id":"st-953","cat":"after-support","type":"match","persona":"Counsellor","source":"helplines (verified)","relearn":"Match each situation to the right helpline route in India.","hook":"Match the situation to who to call.","pairs":[{"left":"Threats over chat right now","right":"Emergency 112"},{"left":"A woman needs counsel","right":"Women Helpline 181"},{"left":"A younger child harmed","right":"Childline 1098"},{"left":"Unsure, just need advice","right":"A school counsellor"},{"left":"Wants a friend along","right":"You, beside them"}]},
  {"id":"st-954","cat":"after-support","type":"match","persona":"any","source":"after-support / who does what","relearn":"Match each role to how it supports a survivor.","hook":"Match each helper to their part.","pairs":[{"left":"Trusted adult","right":"Steps in to protect"},{"left":"Friend","right":"Believes and stays close"},{"left":"Counsellor","right":"Guides next steps"},{"left":"Women Helpline 181","right":"Free, confidential help"},{"left":"Childline 1098","right":"Help for under-18s"}]},
  {"id":"st-955","cat":"after-support","type":"match","persona":"any","source":"after-support / first move","relearn":"Match the moment to the kindest first response.","hook":"Match each moment to your first move.","pairs":[{"left":"They just told you","right":"Believe them"},{"left":"They're blaming themselves","right":"Take the blame off"},{"left":"They feel alone","right":"Stay with them"},{"left":"They want to report","right":"Offer to go along"},{"left":"It's serious harm","right":"Reach a trusted adult"}]},
  {"id":"st-956","cat":"after-support","type":"spot","persona":"any","source":"after-support / what not to say","relearn":"Belief and 'not your fault' help; blame and disbelief hurt.","hook":"A friend just told you. Spot the two replies that blame or doubt her.","scene":[{"id":"a","text":"\"I believe you, thank you for telling me.\"","trick":false},{"id":"b","text":"\"Are you sure you're not exaggerating?\"","trick":true},{"id":"c","text":"\"None of this was your fault.\"","trick":false},{"id":"d","text":"\"Well, why were you even there?\"","trick":true},{"id":"e","text":"\"I'm right here with you.\"","trick":false}],"why":"Doubting her or asking 'why were you there' blames her; belief and 'not your fault' support."},
  {"id":"st-957","cat":"after-support","type":"spot","persona":"any","source":"dignity / gossip","relearn":"Protecting dignity supports; gossiping and sharing clips harms.","hook":"It's spreading in the group chat. Spot the two moves that harm her dignity.","scene":[{"id":"a","text":"Ask others to delete the clip","trick":false},{"id":"b","text":"Forward the clip 'so people know'","trick":true},{"id":"c","text":"Refuse to repeat the rumour","trick":false},{"id":"d","text":"Add the juicy details you heard","trick":true},{"id":"e","text":"Report the post","trick":false}],"why":"Forwarding the clip and adding details spread the harm; deleting, refusing and reporting protect her."},
  {"id":"st-958","cat":"after-support","type":"spot","persona":"any","source":"survivor-centred","relearn":"Centre and protect the person; revenge and exposure don't.","hook":"He's hurt and angry. Spot the two responses that aren't safe support.","scene":[{"id":"a","text":"Ask what he needs right now","trick":false},{"id":"b","text":"Offer to help him report it","trick":false},{"id":"c","text":"Plan to corner the harasser after school","trick":true},{"id":"d","text":"Remind him it wasn't his fault","trick":false},{"id":"e","text":"Post the harasser's name to 'expose' him","trick":true}],"why":"Cornering or exposing the harasser is risky revenge; support centres him, not retaliation."},
  {"id":"st-959","cat":"after-support","type":"spot","persona":"Counsellor","source":"helplines (verified)","relearn":"181, 112 and a trusted adult are real routes; 'handle it alone' isn't.","hook":"She asks where to turn. Spot the two answers that send her the wrong way.","scene":[{"id":"a","text":"\"Women Helpline 181 can help.\"","trick":false},{"id":"b","text":"\"Just handle it on your own.\"","trick":true},{"id":"c","text":"\"For emergencies, 112.\"","trick":false},{"id":"d","text":"\"Telling anyone only causes trouble.\"","trick":true},{"id":"e","text":"\"A trusted teacher can step in.\"","trick":false}],"why":"'Handle it alone' and 'telling causes trouble' send her away from help; the other three are real routes."},
  {"id":"st-960","cat":"after-support","type":"spot","persona":"any","source":"after-support / freezing","relearn":"Freezing is normal and never the survivor's fault.","hook":"He says he froze. Spot the two replies that wrongly put it on him.","scene":[{"id":"a","text":"\"Freezing is a normal reaction.\"","trick":false},{"id":"b","text":"\"Why didn't you just hit him?\"","trick":true},{"id":"c","text":"\"None of this is your fault.\"","trick":false},{"id":"d","text":"\"You should've fought back.\"","trick":true},{"id":"e","text":"\"I'm glad you're telling me.\"","trick":false}],"why":"'Hit him' and 'fought back' blame him for freezing; freezing is normal and the fault is the harasser's."},
  {"id":"st-961","cat":"after-support","type":"spot","persona":"any","source":"let them lead","relearn":"Let them set the pace; pushing and dismissing don't help.","hook":"She's quiet after sharing a little. Spot the two pushy or dismissive moves.","scene":[{"id":"a","text":"\"We can talk as little as you want.\"","trick":false},{"id":"b","text":"\"Tell me every detail now.\"","trick":true},{"id":"c","text":"\"I'm here whenever you're ready.\"","trick":false},{"id":"d","text":"\"You're being dramatic, move on.\"","trick":true},{"id":"e","text":"\"Take your time.\"","trick":false}],"why":"Demanding every detail and calling her dramatic ignore her pace; letting her lead is the support."},
  {"id":"st-962","cat":"after-support","type":"spot","persona":"any","source":"safeguarding","relearn":"Serious harm needs a trusted adult; secret-keeping leaves them at risk.","hook":"Something serious happened. Spot the two responses that leave her unsafe.","scene":[{"id":"a","text":"Help her tell one trusted adult","trick":false},{"id":"b","text":"Keep the serious secret forever","trick":true},{"id":"c","text":"Offer to call 1098 with her","trick":false},{"id":"d","text":"Tell her to just pretend it didn't happen","trick":true},{"id":"e","text":"Stay with her while she decides","trick":false}],"why":"Keeping the secret or pretending it didn't happen leaves her at risk; serious harm needs help."},
  {"id":"st-963","cat":"after-support","type":"spot","persona":"Veer","source":"ally / accountability","relearn":"Allies support and refuse to join; mocking and blaming aren't allyship.","hook":"After it happened, your friends react. Spot the two responses that aren't allyship.","scene":[{"id":"a","text":"\"This isn't funny, she was hurt.\"","trick":false},{"id":"b","text":"\"Maybe she asked for it.\"","trick":true},{"id":"c","text":"\"Let's check she's okay.\"","trick":false},{"id":"d","text":"\"Let's make a meme of it.\"","trick":true},{"id":"e","text":"\"I'll back her if she reports.\"","trick":false}],"why":"'She asked for it' and making a meme blame and mock her; allies refuse to join and support her."},
  {"id":"st-964","cat":"after-support","type":"sort","persona":"any","source":"after-support / support vs harm","relearn":"Belief, presence and reassurance support; blame and gossip harm.","hook":"Sort each response: real support, or harm?","items":[{"id":"a","text":"\"I believe you.\""},{"id":"b","text":"\"It wasn't your fault.\""},{"id":"c","text":"\"Why were you there?\""},{"id":"d","text":"\"I'm here with you.\""},{"id":"e","text":"Spreading the story around"},{"id":"f","text":"\"You're exaggerating.\""}],"bins":[{"id":"support","label":"Real support","valence":"pos"},{"id":"harm","label":"Hurts them","valence":"neg"}],"key":{"a":"support","b":"support","c":"harm","d":"support","e":"harm","f":"harm"}},
  {"id":"st-965","cat":"after-support","type":"sort","persona":"Counsellor","source":"helplines (verified)","relearn":"181 women, 112 emergency, 1098 children; others aren't help routes.","hook":"Sort: a real India help route, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"Emergency 112"},{"id":"c","text":"Childline 1098"},{"id":"d","text":"\"Just keep it secret.\""},{"id":"e","text":"A trusted adult"},{"id":"f","text":"Posting it online for revenge"}],"bins":[{"id":"route","label":"Real help route","valence":"pos"},{"id":"not","label":"Not a help route","valence":"neg"}],"key":{"a":"route","b":"route","c":"route","d":"not","e":"route","f":"not"}},
  {"id":"st-966","cat":"after-support","type":"sort","persona":"any","source":"survivor-centred","relearn":"Centre the survivor's needs; revenge isn't support.","hook":"Sort each goal: centres the survivor, or seeks revenge?","items":[{"id":"a","text":"Make sure she feels believed"},{"id":"b","text":"Help her choose her next step"},{"id":"c","text":"Go beat up the harasser"},{"id":"d","text":"Ask what she needs"},{"id":"e","text":"Publicly shame the harasser"},{"id":"f","text":"Sit with her quietly"}],"bins":[{"id":"centre","label":"Centres her","valence":"pos"},{"id":"revenge","label":"Seeks revenge","valence":"neg"}],"key":{"a":"centre","b":"centre","c":"revenge","d":"centre","e":"revenge","f":"centre"}},
  {"id":"st-967","cat":"after-support","type":"sort","persona":"any","source":"after-support / words","relearn":"Lead with belief and reassurance; never with blame or pressure.","hook":"Sort each line: kind to say, or unkind?","items":[{"id":"a","text":"\"Take your time.\""},{"id":"b","text":"\"None of this is on you.\""},{"id":"c","text":"\"Just get over it.\""},{"id":"d","text":"\"Thank you for trusting me.\""},{"id":"e","text":"\"What did you expect?\""},{"id":"f","text":"\"You're not alone in this.\""}],"bins":[{"id":"kind","label":"Kind to say","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"kind","c":"unkind","d":"kind","e":"unkind","f":"kind"}},
  {"id":"st-968","cat":"after-support","type":"sort","persona":"any","source":"safeguarding","relearn":"Serious harm needs a trusted adult; some 'secrets' are too dangerous to keep.","hook":"Sort: keep this to yourself, or tell a trusted adult?","items":[{"id":"a","text":"A serious assault was described"},{"id":"b","text":"Ongoing threats to share images"},{"id":"c","text":"A small joke she's already laughed off"},{"id":"d","text":"She's being followed home"},{"id":"e","text":"A one-off greeting she liked"},{"id":"f","text":"A harasser who keeps escalating"}],"bins":[{"id":"tell","label":"Tell a trusted adult","valence":"tell"},{"id":"hers","label":"Hers to handle","valence":"neutral"}],"key":{"a":"tell","b":"tell","c":"hers","d":"tell","e":"hers","f":"tell"}},
  {"id":"st-969","cat":"after-support","type":"sort","persona":"any","source":"after-support / do vs avoid","relearn":"Believing and checking in help; pressuring and gossiping don't.","hook":"Sort each move: do this, or avoid it?","items":[{"id":"a","text":"Quietly check in the next day"},{"id":"b","text":"Believe what she tells you"},{"id":"c","text":"Force her to report right now"},{"id":"d","text":"Offer to go with her for help"},{"id":"e","text":"Tell others her business"},{"id":"f","text":"Demand every single detail"}],"bins":[{"id":"do","label":"Do this","valence":"pos"},{"id":"avoid","label":"Avoid this","valence":"neg"}],"key":{"a":"do","b":"do","c":"avoid","d":"do","e":"avoid","f":"avoid"}},
  {"id":"st-970","cat":"after-support","type":"sort","persona":"any","source":"after-support / feelings are valid","relearn":"All a survivor's feelings are valid; none need 'fixing' or judging.","hook":"Sort: a feeling a survivor is allowed to have, or a blaming judgement?","items":[{"id":"a","text":"Feeling scared"},{"id":"b","text":"Feeling angry"},{"id":"c","text":"\"She brought it on herself\""},{"id":"d","text":"Feeling numb or frozen"},{"id":"e","text":"\"He's just being dramatic\""},{"id":"f","text":"Needing time"}],"bins":[{"id":"valid","label":"Valid feeling","valence":"pos"},{"id":"blame","label":"Blaming judgement","valence":"neg"}],"key":{"a":"valid","b":"valid","c":"blame","d":"valid","e":"blame","f":"valid"}},
  {"id":"st-971","cat":"after-support","type":"sort","persona":"any","source":"after-support / online","relearn":"After online harm: believe, save proof, report; don't blame or forward it on.","hook":"A friend got threatening messages. Sort each move: helps her, or makes it worse?","items":[{"id":"a","text":"Believe her and stay calm"},{"id":"b","text":"Help screenshot proof, her call"},{"id":"c","text":"Forward the messages to others"},{"id":"d","text":"Report the account with her"},{"id":"e","text":"Say she shouldn't have replied"},{"id":"f","text":"Offer to tell a trusted adult"}],"bins":[{"id":"helps","label":"Helps her","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"worse","d":"helps","e":"worse","f":"helps"}},
  {"id":"st-990","cat":"be-the-upstander","type":"branch","hook":"At a crowded mela, a man keeps brushing against a girl in the queue.","options":[{"text":"Ask her \"didi, is this your phone?\" so she can step out","consequence":"You break his cover and give her a safe exit.","outcome":"upstander","best":true},{"text":"Stare at the man so he stops","consequence":"Staring can provoke him; a casual distraction is safer."}],"debrief":"A casual distraction gives the target an exit, no confrontation.","relearn":"A casual question can give a harassed person a safe way out.","persona":"any","source":"distract / public"},
  {"id":"st-992","cat":"be-the-upstander","type":"branch","hook":"A senior keeps 'accidentally' touching a junior during a fest rehearsal.","options":[{"text":"Pull the junior into your group task, never alone with him","consequence":"You remove the chance to harass, no confrontation.","outcome":"upstander","best":true},{"text":"Joke about it to lighten the mood","consequence":"Joking normalises it; quietly shielding the junior helps."}],"debrief":"Keeping the target from being isolated is a real safe move.","relearn":"You can shield someone by keeping them out of a harasser's reach.","persona":"Riya","source":"distract / structure"},
  {"id":"st-993","cat":"be-the-upstander","type":"branch","hook":"Your cricket group cheers a boy yelling crude comments at girls passing by.","options":[{"text":"Say \"not cool, let's just play\" and start the next over","consequence":"You refuse to join and reset the group's tone.","outcome":"ally","best":true},{"text":"Stay silent so you're not the odd one out","consequence":"Silence reads as agreement; one line resets the group."}],"debrief":"Refusing to join and redirecting the group is the ally's move.","relearn":"You can reset a group by refusing to join and switching activity.","persona":"Veer","source":"ally / norms"},
  {"id":"st-994","cat":"be-the-upstander","type":"branch","hook":"A boy in your class is being mocked and groped 'as a joke' in the changing room.","options":[{"text":"Step in: \"leave him, that's not a joke,\" and walk out with him","consequence":"You name it and give him an exit, calmly.","outcome":"upstander","best":true},{"text":"Laugh so they don't turn on you","consequence":"Laughing fuels it; naming it and leaving together helps."}],"debrief":"Harassment of boys is real; naming it and leaving together is safe.","relearn":"Boys can be harassed too; name it calmly and leave together.","persona":"Veer","source":"ally / who"},
  {"id":"st-995","cat":"be-the-upstander","type":"branch","hook":"On a WhatsApp class group, boys start sharing a girl's edited photo.","options":[{"text":"Don't forward; report the message and tell her privately","consequence":"You stop the spread and let her decide next steps.","outcome":"upstander","best":true},{"text":"Forward it to warn other friends","consequence":"Forwarding spreads the harm; report and tell her instead."}],"debrief":"Online: don't forward, report it, and let the target lead.","relearn":"For an image-based attack: don't forward, report, and inform the target.","persona":"any","source":"online GBV"},
  {"id":"st-996","cat":"be-the-upstander","type":"branch","hook":"You filmed a man harassing a woman on the platform. He's gone now.","options":[{"text":"Offer the clip to her so she can report it","consequence":"Document stays in her hands, on her terms.","outcome":"upstander","best":true},{"text":"Post it online to expose him","consequence":"Posting it exposes her too; give it to her instead."}],"debrief":"Document is only-if-safe and given to the target, never posted.","relearn":"Footage you take belongs to the target, not the internet.","persona":"any","source":"document"},
  {"id":"st-997","cat":"be-the-upstander","type":"branch","hook":"A man follows your friend off the bus, staying close. You're both nervous.","options":[{"text":"Walk to the nearest shop with her and call a trusted adult","consequence":"You reach safety and bring in help, no clash.","outcome":"upstander","best":true},{"text":"Turn and challenge the man on the street","consequence":"Challenging him alone is risky; reach a safe place first."}],"debrief":"Reach a safe place and call for help, don't confront a follower.","relearn":"If followed, head to a safe place together and get help.","persona":"any","source":"safety-first"},
  {"id":"st-998","cat":"be-the-upstander","type":"branch","hook":"At a wedding, an uncle keeps pulling a teen cousin onto his lap as she squirms.","options":[{"text":"Call her over: \"come help me with the sweets\" and stay with her","consequence":"You extract her without a public scene.","outcome":"upstander","best":true},{"text":"Announce loudly what he's doing to shame him","consequence":"A public scene can target her; quietly extract her."}],"debrief":"Even with relatives, a quiet extraction protects the child.","relearn":"You can rescue a child from an adult by giving a reason to go.","persona":"any","source":"distract / family"},
  {"id":"st-999","cat":"be-the-upstander","type":"branch","hook":"Your friend froze when a man flashed her near the park. She's shaking.","options":[{"text":"Sit with her, say \"it wasn't your fault,\" and offer to call 1098","consequence":"You centre her and route to real help.","outcome":"upstander","best":true},{"text":"Run to find and chase the man","consequence":"Chasing leaves her alone; stay and support her first."}],"debrief":"After harm, centre the person: believe, reassure, route to 1098.","relearn":"After harm, stay, reassure, and offer to call 1098.","persona":"Riya","source":"after-support / helpline"},
  {"id":"st-1001","cat":"be-the-upstander","type":"branch","hook":"In a packed metro, a man presses against a woman who can't move away.","options":[{"text":"Say \"there's space here, please\" and step between them","consequence":"You break contact using space, not a fight.","outcome":"upstander","best":true},{"text":"Grab the man's collar","consequence":"Grabbing him can turn violent; use space to break contact."}],"debrief":"Putting your body in the gap, calmly, breaks contact without a fight.","relearn":"You can break unwanted contact by calmly creating space.","persona":"any","source":"direct-safe / transport"},
  {"id":"st-1003","cat":"be-the-upstander","type":"branch","hook":"You're scared to act: the harasser is the local 'big' boy everyone fears.","options":[{"text":"Quietly alert a guard or shopkeeper instead of facing him","consequence":"You help by delegating, staying out of his reach.","outcome":"upstander","best":true},{"text":"Confront him to prove you're not scared","consequence":"Proving a point isn't worth the danger; delegate."}],"debrief":"Power on his side just means you delegate, not do nothing.","relearn":"When a harasser is powerful, get an adult rather than confront.","persona":"any","source":"delegate / fear"},
  {"id":"st-1004","cat":"be-the-upstander","type":"branch","hook":"Your younger sister says a tuition boy keeps messaging her things she hates.","options":[{"text":"Believe her, save the messages, and help her tell your parents","consequence":"You believe her and bring in adults with proof.","outcome":"upstander","best":true},{"text":"Tell her to just block him and forget it","consequence":"Blocking alone hides it; believe her and tell adults."}],"debrief":"Believe a sibling, keep evidence, and loop in trusted adults.","relearn":"Believe a sibling, save proof, and tell a trusted adult.","persona":"any","source":"after-support / family"},
  {"id":"st-1008","cat":"be-the-upstander","type":"role-play","hook":"You and a friend reach a girl a man was harassing; she's shaken.","setup":"Reassure her. Say:","yourLine":[{"text":"\"You're safe now, it wasn't your fault. Want to sit with us?\"","best":true},{"text":"\"Why didn't you say something to him?\""}],"relearn":"After harm, reassure: you're safe, it wasn't your fault.","persona":"Riya","source":"after-support"},
  {"id":"st-1009","cat":"be-the-upstander","type":"role-play","hook":"Your friend is about to forward a leaked photo of a classmate 'as a warning'.","setup":"Stop them. Say:","yourLine":[{"text":"\"Don't send it, that spreads the harm. Let's report it instead.\"","best":true},{"text":"\"Send it to me first, then decide.\""}],"relearn":"Stop the spread of leaked images; report instead of forwarding.","persona":"any","source":"online GBV"},
  {"id":"st-1011","cat":"be-the-upstander","type":"role-play","hook":"Your friends are cheering a boy who keeps grabbing a girl's dupatta.","setup":"Call it out. Say:","yourLine":[{"text":"\"That's not funny, leave her alone, yaar.\"","best":true},{"text":"Laugh and look the other way"}],"relearn":"Name harassment as not-funny, even among your own friends.","persona":"Veer","source":"ally / norms"},
  {"id":"st-1012","cat":"be-the-upstander","type":"role-play","hook":"A junior tells you a coaching-class teacher makes her uncomfortable.","setup":"Guide her. Say:","yourLine":[{"text":"\"I believe you. It's not your fault. Let's tell a trusted adult together.\"","best":true},{"text":"\"Maybe you're imagining it.\""}],"relearn":"Believe a junior and help her tell a trusted adult.","persona":"Counsellor","source":"mentoring"},
  {"id":"st-1014","cat":"be-the-upstander","type":"role-play","hook":"A classmate is spreading a sexual rumour about another girl.","setup":"Shut it down. Say:","yourLine":[{"text":"\"Stop, that rumour can wreck her. I'm not passing it on.\"","best":true},{"text":"\"Really? Tell me everything.\""}],"relearn":"Shut down sexual rumours instead of passing them along.","persona":"any","source":"after-support / dignity"},
  {"id":"st-1015","cat":"be-the-upstander","type":"role-play","hook":"You froze last time and want to commit to acting now.","setup":"Tell your friend your plan. Say:","yourLine":[{"text":"\"Next time I'll at least distract or get help. I won't just freeze.\"","best":true},{"text":"\"There's nothing I can really do anyway.\""}],"relearn":"After freezing once, commit to one safe move next time.","persona":"any","source":"growth / courage"},
  {"id":"st-1016","cat":"be-the-upstander","type":"role-play","hook":"A boy in your friend group says girls 'enjoy the attention' of catcalls.","setup":"Push back. Say:","yourLine":[{"text":"\"They don't, that's harassment. We can be the guys who don't do that.\"","best":true},{"text":"Shrug and let the comment stand"}],"relearn":"Push back on the myth that targets enjoy catcalls.","persona":"Veer","source":"ally / myth"},
  {"id":"st-1017","cat":"be-the-upstander","type":"spot","hook":"Spot the two bystanders making it worse on this bus.","scene":[{"id":"a","text":"A woman asks the girl to swap seats","trick":false},{"id":"b","text":"Two boys film the harassment and laugh","trick":true},{"id":"c","text":"A passenger quietly tells the conductor","trick":false},{"id":"d","text":"Someone shouts that she invited it","trick":true},{"id":"e","text":"A rider offers the girl a way out","trick":false}],"why":"Filming for laughs and blaming the girl harm her instead of helping.","relearn":"Upstanders give an exit and alert staff; they don't film or blame.","persona":"any","source":"spotting"},
  {"id":"st-1018","cat":"be-the-upstander","type":"spot","hook":"Spot the two red flags: which moves would make YOU unsafe?","scene":[{"id":"a","text":"Quietly alert the guard nearby","trick":false},{"id":"b","text":"Grab and shove the much bigger harasser","trick":true},{"id":"c","text":"Ask a friend to come help","trick":false},{"id":"d","text":"Chase the harasser down the lane alone","trick":true},{"id":"e","text":"Stand near the target so she's not alone","trick":false}],"why":"Shoving a bigger man and chasing alone can make you a second victim.","relearn":"Don't shove or chase a harasser; delegate and add presence.","persona":"any","source":"safety-first"},
  {"id":"st-1019","cat":"be-the-upstander","type":"spot","hook":"Spot the two red flags: which 'help' actually harms the target?","scene":[{"id":"a","text":"Sit with her and say it wasn't her fault","trick":false},{"id":"b","text":"Post the harasser's video to 'expose' him","trick":true},{"id":"c","text":"Offer to call 1098 with her","trick":false},{"id":"d","text":"Tell everyone the gossip about what happened","trick":true},{"id":"e","text":"Ask what support she'd like","trick":false}],"why":"Posting the video and spreading gossip expose the target and strip her dignity.","relearn":"Don't post videos or spread gossip; support the target's dignity.","persona":"any","source":"after-support / dignity"},
  {"id":"st-1020","cat":"be-the-upstander","type":"spot","hook":"Spot the two red flags: which excuses for NOT helping are myths?","scene":[{"id":"a","text":"\"I can ask a guard, that's safe\"","trick":false},{"id":"b","text":"\"It's not my problem, it's not me\"","trick":true},{"id":"c","text":"\"A small safe move still counts\"","trick":false},{"id":"d","text":"\"Boys can't help it, it's nature\"","trick":true},{"id":"e","text":"\"I can check she's okay afterwards\"","trick":false}],"why":"\"Not my problem\" and \"boys can't help it\" are myths that excuse harassment.","relearn":"Everyone's safety is everyone's business; harassment is a choice.","persona":"any","source":"myth-busting"},
  {"id":"st-1021","cat":"be-the-upstander","type":"spot","hook":"Spot the two red flags: which 'ally' moves are really still joining in?","scene":[{"id":"a","text":"Saying \"not cool\" and changing the topic","trick":false},{"id":"b","text":"Laughing quietly at the crude joke","trick":true},{"id":"c","text":"Refusing to share the girl's photo","trick":false},{"id":"d","text":"Forwarding it 'just to friends'","trick":true},{"id":"e","text":"Walking the target to her class","trick":false}],"why":"Quiet laughing and forwarding the photo still join and spread the harm.","relearn":"Quietly laughing or forwarding still counts as joining in.","persona":"Veer","source":"ally / spotting"},
  {"id":"st-1022","cat":"be-the-upstander","type":"spot","hook":"Spot the two red flags: which moves put YOU in danger?","scene":[{"id":"a","text":"Call a trusted adult over","trick":false},{"id":"b","text":"Threaten to beat up the harasser","trick":true},{"id":"c","text":"Create a casual distraction for an exit","trick":false},{"id":"d","text":"Block the harasser's path with your body","trick":true},{"id":"e","text":"Move the target toward a crowded shop","trick":false}],"why":"Threatening and blocking his path can turn violent against you.","relearn":"Don't threaten or block a harasser; distract, move, and delegate.","persona":"any","source":"safety-first"},
  {"id":"st-1023","cat":"be-the-upstander","type":"reflect","hook":"Lensy: when you picture standing up safely, who do you want beside you?","prompt":"Pick one.","options":["A friend I trust","A teacher or adult","A guard or staff","Anyone willing to help"],"affirm":"Whoever you pick, bringing one person makes standing up safer and easier.","relearn":"Bringing one trusted person makes standing up safer.","persona":"any","source":"teamwork"},
  {"id":"st-1024","cat":"be-the-upstander","type":"reflect","hook":"Lensy: which of the five Ds feels most like 'you'?","prompt":"Pick your go-to D.","options":["Distract","Delegate","Document","Delay","Direct"],"affirm":"Any D you'd actually use is a real upstander move, there's no wrong pick.","relearn":"Any of the five Ds you'd really use is a valid safe move.","persona":"any","source":"five-ds"},
  {"id":"st-1025","cat":"be-the-upstander","type":"reflect","hook":"Lensy: what's the kindest thing to say to someone right after they've been harassed?","prompt":"Pick the words.","options":["\"It wasn't your fault\"","\"I believe you\"","\"I'm here with you\"","\"What do you need?\""],"affirm":"Each one centres them and helps; there's no wrong way to show you care.","relearn":"Believe them, reassure them, and ask what they need.","persona":"any","source":"after-support"},
  {"id":"st-1026","cat":"be-the-upstander","type":"reflect","hook":"Lensy: a part of you froze once. How do you want to treat that part?","prompt":"What do you think?","options":["With kindness","It was human","I can try again"],"affirm":"Freezing is normal, and being gentle with yourself is how courage grows.","relearn":"Freezing is human; be kind to yourself and try again.","persona":"any","source":"growth / self-compassion"},
  {"id":"st-1027","cat":"be-the-upstander","type":"reflect","hook":"Lensy: if a younger kid copied how you respond to harassment, what would you want them to learn?","prompt":"Pick one.","options":["Help safely","Never blame the target","Get an adult","Don't stay silent"],"affirm":"Whatever you pick, you'd be teaching them to be a safe upstander.","relearn":"Younger kids learn the upstander habit by watching you.","persona":"any","source":"role-model"},
  {"id":"st-1028","cat":"be-the-upstander","type":"reflect","hook":"Lensy: being an ally sometimes costs you something. What feels worth it?","prompt":"What do you think?","options":["Someone's safety","Being able to respect myself","Doing the right thing"],"affirm":"Those are exactly the things real allies decide are worth a little discomfort.","relearn":"Allies decide someone's safety is worth a little discomfort.","persona":"any","source":"courage"},
  {"id":"st-1029","cat":"be-the-upstander","type":"reflect","hook":"Lensy: boys can be powerful allies. What power do you have to stop harassment?","prompt":"Pick one.","options":["Refusing to join","Calling it out","Changing the group's vibe","Backing up the target"],"affirm":"Every one of those is real power, and using it shifts the whole group.","relearn":"Boys hold real power to stop harassment by refusing to join.","persona":"Veer","source":"ally / agency"},
  {"id":"st-1030","cat":"be-the-upstander","type":"reflect","hook":"Lensy: what makes the SAFE move braver than the showy one?","prompt":"What do you think?","options":["It actually helps","It keeps you both safe","It takes real self-control"],"affirm":"Exactly, the bravest move is the one that helps without a second victim.","relearn":"The bravest move is the safe one that helps without new harm.","persona":"any","source":"safety-first / courage"},
  {"id":"st-1031","cat":"be-the-upstander","type":"reflect","hook":"Lensy: you can't be everywhere. What's enough for one upstander to do?","prompt":"Pick one.","options":["One safe move","Get the right help","Support the person","Whatever I safely can"],"affirm":"That's plenty, one safe action is enough, and it often unfreezes others.","relearn":"One safe action is enough; it can unfreeze everyone else.","persona":"any","source":"agency"},
  {"id":"st-1032","cat":"be-the-upstander","type":"reflect","hook":"Lensy: what would you tell a friend who says 'why should I get involved?'","prompt":"Pick your answer.","options":["It could be you next time","Their safety is ours too","Because I'd want help"],"affirm":"Any of those is a true reason; everyone's safety really is everyone's business.","relearn":"Everyone's safety is everyone's business, including yours.","persona":"any","source":"allyship"},
  {"id":"st-1033","cat":"be-the-upstander","type":"reflect","hook":"Lensy: knowing the safe moves and 181 / 112 / 1098, how do you feel about stepping up?","prompt":"What do you think?","options":["Ready","More confident","I know what to do"],"affirm":"You've got the moves, the limits, and the helplines, you're ready.","relearn":"With safe moves and the helplines, you're ready to stand up.","persona":"any","source":"consolidation"},
  {"id":"st-1034","cat":"be-the-upstander","type":"reflect","hook":"Lensy: picture the bystander you used to be and the upstander you're becoming. Which feels like home?","prompt":"Pick one.","options":["The upstander","The one who acts safely","The one who doesn't stay silent"],"affirm":"That's the person this whole game is for, safe, supportive, and never silent.","relearn":"You can choose to be a safe, supportive, never-silent upstander.","persona":"any","source":"identity"},
  {"id":"st-1035","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"If I help, I'll just end up getting hurt too.\"","myth":{"un":"Helping always means putting myself in danger.","re":"Safe moves like distracting or getting help let you help without risk.","why":"Upstanders are taught to help without becoming a second victim."},"relearn":"You can help safely; helping doesn't have to mean getting hurt.","persona":"any","source":"safety-first"},
  {"id":"st-1036","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"I'm just one person, what difference can I make?\"","myth":{"un":"One person can't change a harassment scene.","re":"One safe upstander often unfreezes everyone else and shifts the whole scene.","why":"Others are usually waiting for someone to act first."},"relearn":"One safe upstander can change a scene and free others to act.","persona":"any","source":"agency"},
  {"id":"st-1037","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"If they're my friends, I have to laugh along.\"","myth":{"un":"You can't stand up when the harassers are your own friends.","re":"You can refuse to join your friends and reset the group's tone.","why":"Standing up sometimes means stopping the people closest to you."},"relearn":"You can stand up even when the harassers are your own friends.","persona":"Veer","source":"ally / norms"},
  {"id":"st-1038","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"Real help means confronting the harasser face to face.\"","myth":{"un":"Being an upstander means bravely confronting the harasser.","re":"Distracting, getting help, or supporting the target are the real upstander moves.","why":"For risky harassers, confronting can make you a second victim."},"relearn":"Upstanding is distracting and delegating, not confronting danger.","persona":"any","source":"five-ds"},
  {"id":"st-1039","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"Posting the video online is how you expose him.\"","myth":{"un":"Posting the harassment video exposes the harasser and helps.","re":"Posting it re-exposes the target; give any footage to her instead.","why":"Document is only-if-safe and belongs to the target, never the internet."},"relearn":"Don't post footage; give it to the target on her terms.","persona":"any","source":"document"},
  {"id":"st-1040","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"If she froze and didn't fight back, it wasn't that bad.\"","myth":{"un":"Not fighting back means the harassment wasn't serious.","re":"Freezing is a normal response and never makes the harm less real.","why":"The body freezes to protect itself; it's not consent or fault."},"relearn":"Freezing is normal and never reduces the harm done.","persona":"any","source":"after-support"},
  {"id":"st-1041","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"A boy can't really be harassed, so why step in?\"","myth":{"un":"Boys can't be harassed, so there's nothing to step in for.","re":"Anyone can face harassment, and it's wrong whoever the target is.","why":"Harassment is about unwanted behaviour, not the target's gender."},"relearn":"Anyone can be harassed; step in whoever the target is.","persona":"Veer","source":"who / ally"},
  {"id":"st-1042","cat":"be-the-upstander","type":"sort","hook":"Sort each move: a SAFE upstander move, or a RISKY one that could backfire?","items":[{"id":"a","text":"Casually distract so the target can leave"},{"id":"b","text":"Quietly alert a guard or staff"},{"id":"c","text":"Check the person is okay afterwards"},{"id":"d","text":"Shove the harasser away"},{"id":"e","text":"Chase the harasser down the street"},{"id":"f","text":"Threaten to beat him up"}],"bins":[{"id":"safe","label":"Safe move","valence":"pos"},{"id":"risky","label":"Risky move","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"safe","d":"risky","e":"risky","f":"risky"},"relearn":"Distract, delegate, and support are safe; shoving and chasing backfire.","persona":"any","source":"safety-first"},
  {"id":"st-1043","cat":"be-the-upstander","type":"sort","hook":"Sort each action: an upstander helping, or a bystander making it worse?","items":[{"id":"a","text":"Sitting with the target"},{"id":"b","text":"Alerting the conductor"},{"id":"c","text":"Filming for laughs"},{"id":"d","text":"Forwarding the leaked photo"},{"id":"e","text":"Offering to call for help"},{"id":"f","text":"Spreading the gossip"}],"bins":[{"id":"up","label":"Upstander","valence":"pos"},{"id":"by","label":"Makes it worse","valence":"neg"}],"key":{"a":"up","b":"up","c":"by","d":"by","e":"up","f":"by"},"relearn":"Upstanders support and get help; the rest film, forward, and gossip.","persona":"any","source":"upstander vs bystander"},
  {"id":"st-1044","cat":"be-the-upstander","type":"sort","hook":"Sort each line: an ally speaking up, or joining the harassment?","items":[{"id":"a","text":"\"Not cool, leave her alone\""},{"id":"b","text":"\"That's harassment, I'm not in\""},{"id":"c","text":"\"Haha rate her out of ten\""},{"id":"d","text":"\"Send me that photo\""},{"id":"e","text":"\"Stop, that's not a joke\""},{"id":"f","text":"\"Go on, whistle at her\""}],"bins":[{"id":"ally","label":"Ally","valence":"tell"},{"id":"join","label":"Joining in","valence":"neg"}],"key":{"a":"ally","b":"ally","c":"join","d":"join","e":"ally","f":"join"},"relearn":"Allies refuse and name it; joining means rating, sharing, or egging on.","persona":"Veer","source":"ally / norms"},
  {"id":"st-1045","cat":"be-the-upstander","type":"sort","hook":"Sort each move into the right D of the five Ds.","items":[{"id":"a","text":"\"There you are! Come sit with me\""},{"id":"b","text":"Asking the guard to step in"},{"id":"c","text":"Saving the clip for the target"},{"id":"d","text":"\"Are you okay?\" afterwards"},{"id":"e","text":"\"That's not okay\" when it's safe"},{"id":"f","text":"\"Uncle, please help this girl\""}],"bins":[{"id":"distract","label":"Distract","valence":"neutral"},{"id":"delegate","label":"Delegate","valence":"neutral"},{"id":"docdelay","label":"Document/Delay","valence":"neutral"},{"id":"direct","label":"Direct","valence":"neutral"}],"key":{"a":"distract","b":"delegate","c":"docdelay","d":"docdelay","e":"direct","f":"delegate"},"relearn":"Each move maps to a D: Distract, Delegate, Document, Delay, or Direct.","persona":"any","source":"five-ds"},
  {"id":"st-1046","cat":"be-the-upstander","type":"sort","hook":"Sort each statement: a true upstander fact, or a myth that excuses silence?","items":[{"id":"a","text":"Everyone's safety is everyone's business"},{"id":"b","text":"One person can change a scene"},{"id":"c","text":"\"It's not my problem\""},{"id":"d","text":"\"Boys can't help it\""},{"id":"e","text":"A small safe move counts"},{"id":"f","text":"\"She enjoyed the attention\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"myth","e":"true","f":"myth"},"relearn":"Upstander truths beat the myths that excuse staying silent.","persona":"any","source":"myth-busting"},
  {"id":"st-1047","cat":"be-the-upstander","type":"sort","hook":"Sort each response after harm: centres the survivor, or centres revenge?","items":[{"id":"a","text":"\"I believe you, I'm here\""},{"id":"b","text":"Asking what support she wants"},{"id":"c","text":"\"Let's go beat him up\""},{"id":"d","text":"Offering to call 1098 with her"},{"id":"e","text":"\"I'll expose him online\""},{"id":"f","text":"Chasing the harasser for payback"}],"bins":[{"id":"survivor","label":"Centres survivor","valence":"pos"},{"id":"revenge","label":"Centres revenge","valence":"neg"}],"key":{"a":"survivor","b":"survivor","c":"revenge","d":"survivor","e":"revenge","f":"revenge"},"relearn":"Support centres the survivor's needs, not revenge on the harasser.","persona":"any","source":"after-support"},
  {"id":"st-1048","cat":"be-the-upstander","type":"sort","hook":"Sort each move: safe to do alone, or only with backup/an adult?","items":[{"id":"a","text":"Casually distracting the harasser"},{"id":"b","text":"Checking on the target afterwards"},{"id":"c","text":"Facing two boys cornering someone"},{"id":"d","text":"Following a harasser into a lane"},{"id":"e","text":"Asking a friend to come over"},{"id":"f","text":"Handling a drunk, aggressive man"}],"bins":[{"id":"alone","label":"Safe alone","valence":"pos"},{"id":"backup","label":"Needs backup","valence":"uhoh"}],"key":{"a":"alone","b":"alone","c":"backup","d":"backup","e":"alone","f":"backup"},"relearn":"Small calm moves are fine alone; risky scenes need backup or an adult.","persona":"any","source":"safety-first"},
  {"id":"st-1049","cat":"be-the-upstander","type":"match","hook":"Match each situation to the safe move that fits.","pairs":[{"left":"Man pressing close on a bus","right":"Distract so she can swap seats"},{"left":"Two boys cornering a junior","right":"Grab a friend, step in together"},{"left":"Harasser much bigger than you","right":"Quietly alert a guard"},{"left":"Friend shaken after harm","right":"Sit with her: it wasn't your fault"},{"left":"Leaked photo in a chat","right":"Report it and tell the target"}],"relearn":"Each scene has a safe move: distract, delegate, support, or report.","persona":"any","source":"five-ds / matching"},
  {"id":"st-1050","cat":"be-the-upstander","type":"match","hook":"Match each of the five Ds to what it actually means.","pairs":[{"left":"Distract","right":"Interrupt casually so the target can get away"},{"left":"Delegate","right":"Get others or authority to help"},{"left":"Document","right":"If safe, record and give it to the target"},{"left":"Delay","right":"Check in afterwards: are you okay?"},{"left":"Direct","right":"When safe, calmly name that it's not okay"}],"relearn":"The five Ds: Distract, Delegate, Document, Delay, Direct.","persona":"any","source":"five-ds"},
  {"id":"st-1051","cat":"be-the-upstander","type":"match","hook":"Match each myth to the truth that flips it.","pairs":[{"left":"\"It's not my problem\"","right":"Everyone's safety is everyone's business"},{"left":"\"I'm only one person\"","right":"One safe upstander can shift a scene"},{"left":"\"I must laugh with friends\"","right":"You can refuse and reset the group"},{"left":"\"Helping means fighting\"","right":"Distract or get help, not confront"},{"left":"\"She didn't fight, so it's fine\"","right":"Freezing is normal; it's not okay"}],"relearn":"Each upstander myth has a truth that flips it.","persona":"any","source":"myth-busting"},
  {"id":"st-1052","cat":"be-the-upstander","type":"match","hook":"Match each person you can reach to how they help you stand up safely.","pairs":[{"left":"A trusted friend","right":"Backup so you're not alone"},{"left":"A guard or conductor","right":"Authority to step in on the spot"},{"left":"A trusted adult","right":"Help for serious harm"},{"left":"Childline 1098","right":"Support for anyone under 18"},{"left":"Women Helpline 181","right":"Help for a woman in distress"}],"relearn":"Friends, staff, adults, 1098 and 181 all help you stand up safely.","persona":"any","source":"delegate / helplines"},
  {"id":"st-1053","cat":"be-the-upstander","type":"match","hook":"Match each upstander move to what it protects.","pairs":[{"left":"Giving footage only to the target","right":"Her dignity and her choice"},{"left":"Shutting down a sexual rumour","right":"Her reputation"},{"left":"Distracting instead of confronting","right":"Your own safety"},{"left":"Saying it wasn't your fault","right":"Her sense of self-blame"},{"left":"Asking a specific person for help","right":"A real, quick response"}],"relearn":"Safe upstander moves protect the target's dignity and your safety.","persona":"any","source":"after-support / safety"},
  {"id":"st-1054","cat":"be-the-upstander","type":"match","hook":"Match each thing a survivor might need to the upstander response.","pairs":[{"left":"To be believed","right":"\"I believe you\""},{"left":"To not feel at fault","right":"\"It wasn't your fault\""},{"left":"To not be alone","right":"\"I'm here, want to sit with me?\""},{"left":"To reach real help","right":"\"We can call 1098 together\""},{"left":"To lead her own next step","right":"\"What would help you right now?\""}],"relearn":"Survivors need to be believed, not blamed, not alone, and to lead.","persona":"any","source":"after-support"},
  {"id":"st-1055","cat":"be-the-upstander","type":"match","hook":"Match each setting to the safe upstander move that fits it.","pairs":[{"left":"On a moving auto","right":"Ask the driver to stop and get down"},{"left":"In a school corridor","right":"Break it up and get a teacher"},{"left":"In an online class group","right":"Report it and check on the target"},{"left":"At a crowded mela","right":"Casual distraction for an exit"},{"left":"After it's over","right":"Gentle check-in: are you okay?"}],"relearn":"Every setting, from autos to online, has a fitting safe move.","persona":"any","source":"settings / five-ds"},
  {"id":"st-1057","cat":"be-the-upstander","type":"branch","hook":"A man exposes himself to kids near the tuition centre. No parents around.","options":[{"text":"Get the children inside and tell the staff and a trusted adult","consequence":"You get the kids to safety and route it to adults.","outcome":"upstander","best":true},{"text":"Try to catch and hold the man yourself","consequence":"Grabbing him is dangerous; get the kids safe, tell adults."}],"debrief":"Get the kids safe first, then tell staff and trusted adults.","relearn":"Get children to safety, then tell staff and an adult.","persona":"any","source":"safety-first / children"},
  {"id":"st-1059","cat":"be-the-upstander","type":"branch","hook":"A girl messages you that a man keeps DMing her threats. She's terrified.","options":[{"text":"Tell her not to reply, screenshot it, help her tell an adult","consequence":"You preserve proof and bring in help, on her terms.","outcome":"upstander","best":true},{"text":"DM the man yourself to threaten him back","consequence":"Threatening back can escalate; keep proof, tell an adult."}],"debrief":"Online threats: don't reply, keep proof, tell an adult.","relearn":"Online threats: keep proof and help her tell an adult.","persona":"any","source":"online GBV / after-support"},
  {"id":"st-1065","cat":"be-the-upstander","type":"role-play","hook":"Your teammate brags about secretly filming up a girl's skirt.","setup":"Refuse to be part of it. Say:","yourLine":[{"text":"\"Delete that now. That's a crime, not a joke, and I'm telling.\"","best":true},{"text":"\"Show me, then delete it.\""}],"relearn":"Refuse to view secret films; insist they're deleted and reported.","persona":"Veer","source":"ally / document misuse"},
  {"id":"st-1070","cat":"be-the-upstander","type":"branch","hook":"A girl asks you to keep secret that a relative is harassing her at home.","options":[{"text":"Promise to stay by her but gently help her tell a trusted adult","consequence":"You honour her while routing serious harm to help.","outcome":"upstander","best":true},{"text":"Keep it totally secret because she asked","consequence":"Serious harm needs an adult; help her tell someone."}],"debrief":"For serious harm, support the target to reach a trusted adult.","relearn":"For serious harm, gently help her tell a trusted adult.","persona":"Counsellor","source":"after-support / serious"},
  {"id":"st-1071","cat":"be-the-upstander","type":"branch","hook":"On the train, a man keeps photographing a sleeping woman without consent.","options":[{"text":"Wake her gently, tell her, and ask staff to handle it","consequence":"You inform her and bring in railway staff, safely.","outcome":"upstander","best":true},{"text":"Snatch his phone to delete the photos","consequence":"Snatching can turn violent; inform her and get staff."}],"debrief":"Photographing without consent is harassment; inform her and delegate.","relearn":"Non-consensual photos are harassment; inform her and tell staff.","persona":"any","source":"spot / delegate"},
  {"id":"st-1072","cat":"be-the-upstander","type":"branch","hook":"Boys dare you to 'just touch her and run' to prove you're cool.","options":[{"text":"Refuse loudly: \"no, that's assault,\" and walk away","consequence":"You reject the dare and name it for what it is.","outcome":"ally","best":true},{"text":"Do it quickly so they stop bugging you","consequence":"A dare doesn't make it okay; it's assault, refuse it."}],"debrief":"No dare makes unwanted touch okay; refusing is the ally's move.","relearn":"No dare excuses unwanted touch; refuse and name it as assault.","persona":"Veer","source":"ally / peer pressure"},
  {"id":"st-1073","cat":"be-the-upstander","type":"branch","hook":"A new girl is too scared to walk past a group that harasses her daily.","options":[{"text":"Offer to walk that stretch with her and loop in a teacher","consequence":"You give her safety in numbers and adult backup.","outcome":"upstander","best":true},{"text":"Tell her to just take a longer route forever","consequence":"She shouldn't have to; walk with her and tell a teacher."}],"debrief":"Recurring harassment needs presence plus an adult, not flight.","relearn":"For daily harassment, offer company and loop in an adult.","persona":"Riya","source":"safety-first / recurring"},
  {"id":"st-1075","cat":"be-the-upstander","type":"role-play","hook":"A friend says she's scared to report because no one will believe her.","setup":"Reassure and back her. Say:","yourLine":[{"text":"\"I believe you, and I'll come with you to tell someone.\"","best":true},{"text":"\"Maybe it's not worth the trouble.\""}],"relearn":"Believe her and offer to go with her to report.","persona":"Counsellor","source":"after-support / reporting"},
  {"id":"st-1076","cat":"be-the-upstander","type":"spot","hook":"Spot the two bystanders making it worse; tap the moves that DON'T help.","scene":[{"id":"a","text":"One person quietly alerts a guard","trick":false},{"id":"b","text":"Two people film it for laughs","trick":true},{"id":"c","text":"Another sits with the target","trick":false},{"id":"d","text":"A group eggs the harasser on","trick":true},{"id":"e","text":"Someone offers the target a way out","trick":false}],"why":"Filming for laughs and egging him on fuel the harm instead of helping.","relearn":"Upstanders alert help and support the target; they don't film or egg on.","persona":"any","source":"spotting"},
  {"id":"st-1077","cat":"be-the-upstander","type":"spot","hook":"The harasser is much bigger than you. Spot the two UNSAFE moves to avoid.","scene":[{"id":"a","text":"Quietly alert the guard nearby","trick":false},{"id":"b","text":"Grab the harasser to pull him off","trick":true},{"id":"c","text":"Ask a friend to come help","trick":false},{"id":"d","text":"Square up and challenge him","trick":true},{"id":"e","text":"Move the target toward people","trick":false}],"why":"Grabbing and challenging a bigger harasser are unsafe and can make you a victim.","relearn":"When outmatched, alert authority rather than grab or confront.","persona":"any","source":"safety-first"},
  {"id":"st-1078","cat":"be-the-upstander","type":"sort","hook":"Sort: an upstander action, or a bystander non-action?","items":[{"id":"a","text":"Alerting a guard"},{"id":"b","text":"Filming for laughs"},{"id":"c","text":"Checking the person is okay"},{"id":"d","text":"Walking away unbothered"},{"id":"e","text":"Offering the target an exit"},{"id":"f","text":"Egging the harasser on"}],"bins":[{"id":"up","label":"Upstander","valence":"pos"},{"id":"by","label":"Bystander","valence":"neg"}],"key":{"a":"up","b":"by","c":"up","d":"by","e":"up","f":"by"},"relearn":"Upstanders get help and support; bystanders film or walk away.","persona":"any","source":"upstander vs bystander"},
  {"id":"st-1080","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Distract","relearn":"Distract: interrupt casually so the target can get away.","hook":"A man keeps leaning into a girl on a crowded local train. Confronting him feels unsafe.","options":[{"text":"Ask her loudly: 'Aren't you getting off at the next stop with me?'","consequence":"She moves toward you and away from him.","outcome":"distract","best":true},{"text":"Shout at the man to back off","consequence":"A casual distraction frees her without confronting him."}],"debrief":"Distract lets the target slip away without a face-off."},
  {"id":"st-1081","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Delegate","relearn":"Delegate: get others or authority to help.","hook":"On a city bus a man won't stop hassling a passenger. The conductor is right there.","options":[{"text":"Tell the conductor: 'That passenger is being troubled, please move them or stop him.'","consequence":"Authority steps in with you behind them.","outcome":"delegate","best":true},{"text":"Try to handle the man one-on-one","consequence":"Bringing in the conductor is safer than acting alone."}],"debrief":"Delegate puts authority between you and the danger."},
  {"id":"st-1082","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Document","relearn":"Document only if safe, and give it to the target, never post it.","hook":"A boy films a girl without consent at the bus stand. It's safe for you to record him.","options":[{"text":"Quietly record him, then offer the clip to her to use as she wants","consequence":"She has proof and stays in control.","outcome":"document","best":true},{"text":"Post your clip to shame him","consequence":"Document is for the target's use, never posting."}],"debrief":"Document keeps evidence and control with the person harmed."},
  {"id":"st-1083","cat":"five-ds","type":"branch","persona":"Riya","source":"5 Ds / Delay","relearn":"Delay: check in afterwards, 'are you okay?'.","hook":"A classmate got catcalled crossing the road. The men have gone; she looks shaken.","options":[{"text":"Walk up: 'Hey, that wasn't okay — are you alright?'","consequence":"She feels less alone and more believed.","outcome":"delay","best":true},{"text":"Pretend you didn't see it","consequence":"A gentle check-in afterwards (Delay) really helps."}],"debrief":"Delay supports the person once the moment has passed."},
  {"id":"st-1084","cat":"five-ds","type":"branch","persona":"Veer","source":"5 Ds / Direct","relearn":"Direct: when safe, calmly name that it's not okay.","hook":"In a bright, busy classroom a friend keeps making 'jokes' at a girl's expense.","options":[{"text":"Calmly: 'Yaar, that's not funny — leave her alone.'","consequence":"Naming it makes the room shift.","outcome":"direct","best":true},{"text":"Laugh along so you fit in","consequence":"When it's clearly safe, a calm Direct word can stop it."}],"debrief":"Direct names harassment plainly — only when the scene is safe."},
  {"id":"st-1085","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / matching","relearn":"For dangerous harassers, choose Distract or Delegate over Direct.","hook":"A drunk man is groping people in an auto queue. Which D fits a dangerous harasser?","options":[{"text":"Distract the target out of the queue and get a guard (Delegate)","consequence":"You help without becoming a target.","outcome":"distract","best":true},{"text":"Walk up and confront the drunk man","consequence":"For danger, Distract and Delegate beat Direct."}],"debrief":"Match the move to the danger: never Direct with a dangerous harasser."},
  {"id":"st-1086","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / matching","relearn":"When you can't act alone safely, Delegate.","hook":"A festival crowd is huge and pushy; a girl is being cornered. You can't reach her safely.","options":[{"text":"Find police or volunteers and point them straight to her","consequence":"Trained people reach her fast.","outcome":"delegate","best":true},{"text":"Squeeze through the crowd to grab her yourself","consequence":"In a crush, Delegate to people who can reach her safely."}],"debrief":"When alone-action is unsafe, Delegate is the move."},
  {"id":"st-1087","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Distract","relearn":"Distract: interrupt casually so the target can get away.","hook":"A man follows a girl down the lane making comments. You're nearby with your cycle.","options":[{"text":"Call out: 'There you are! I've been waiting, let's go' and walk with her","consequence":"She has company and he peels off.","outcome":"distract","best":true},{"text":"Block the man's path on your cycle","consequence":"A friendly distraction is safer than blocking him."}],"debrief":"Distract gives the target an exit without a clash."},
  {"id":"st-1088","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Delegate","relearn":"Delegate: get others or authority to help.","hook":"In a college corridor a senior won't let a junior pass. A teacher is nearby.","options":[{"text":"Go get the teacher: 'A senior is blocking someone who wants to leave.'","consequence":"An adult with authority steps in.","outcome":"delegate","best":true},{"text":"Push past the senior yourself","consequence":"Bringing the teacher in is safer than forcing it."}],"debrief":"Delegate hands a corridor block to someone with authority."},
  {"id":"st-1089","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Document","relearn":"Document only if safe, and give it to the target, never post it.","hook":"A man flashes obscene gestures at a girl from across a safe, busy market.","options":[{"text":"Note the time and stall, photograph him from a distance, give it to her","consequence":"She has a record to report if she chooses.","outcome":"document","best":true},{"text":"Chase him through the market","consequence":"Document from safety; don't chase a harasser."}],"debrief":"Document gathers proof for the target — never a chase."},
  {"id":"st-1090","cat":"five-ds","type":"branch","persona":"Riya","source":"5 Ds / Delay","relearn":"Delay: check in afterwards, 'are you okay?'.","hook":"A girl in your tuition class went quiet after a boy whispered something to her.","options":[{"text":"After class, gently: 'You went quiet — are you okay? I'm here.'","consequence":"She knows someone noticed and cares.","outcome":"delay","best":true},{"text":"Assume it's none of your business","consequence":"A quiet check-in afterwards (Delay) helps a lot."}],"debrief":"Delay lets you support someone after a hard moment."},
  {"id":"st-1091","cat":"five-ds","type":"branch","persona":"Veer","source":"5 Ds / Direct","relearn":"Direct: when safe, calmly name that it's not okay.","hook":"In the open canteen your friends rate girls as they pass. It's safe to speak.","options":[{"text":"Calmly: 'Stop rating people — it's not a game, it's harassment.'","consequence":"The 'fun' loses its cover.","outcome":"direct","best":true},{"text":"Join in so they don't tease you","consequence":"When it's safe, a calm Direct word breaks the pattern."}],"debrief":"Direct works best when you name it from inside the group, safely."},
  {"id":"st-1092","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds","relearn":"There is always a D that fits the moment's safety.","hook":"You freeze when a man corners a girl at the lift. Which D can you still do safely?","options":[{"text":"Press the alarm and call out for the watchman (Delegate)","consequence":"Help arrives without you confronting him.","outcome":"delegate","best":true},{"text":"Decide nothing can be done","consequence":"Even frozen, Delegate is a safe move you can take."}],"debrief":"There's always at least one safe D — here, Delegate."},
  {"id":"st-1093","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Distract","relearn":"Distract: interrupt casually so the target can get away.","hook":"A shopkeeper makes a customer uncomfortable with personal questions. You're next in line.","options":[{"text":"Step up: 'Sorry, can you help me first? I'm in a real hurry'","consequence":"The customer uses the gap to leave.","outcome":"distract","best":true},{"text":"Tell the shopkeeper off in front of everyone","consequence":"A simple distraction frees the customer without a scene."}],"debrief":"Distract interrupts the pressure so the target can exit."},
  {"id":"st-1094","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Delegate","relearn":"Delegate: get others or authority to help.","hook":"A girl is being trailed by two men near the station. A police booth is just ahead.","options":[{"text":"Walk her toward the police booth and tell the officer what's happening","consequence":"Officers handle the men; she's safe.","outcome":"delegate","best":true},{"text":"Turn around to argue with the two men","consequence":"Heading to the police is safer than confronting two men."}],"debrief":"Delegate routes danger to people trained to handle it."},
  {"id":"st-1095","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Document","relearn":"Document only if safe, and give it to the target, never post it.","hook":"From a safe distance you see a man repeatedly brushing against women on an escalator.","options":[{"text":"Record discreetly and hand it to a guard or the woman to report","consequence":"There's proof, used on her terms.","outcome":"document","best":true},{"text":"Live-stream it to your followers","consequence":"Document for reporting, never for a livestream or clout."}],"debrief":"Document is only-if-safe and for the target, not an audience."},
  {"id":"st-1096","cat":"five-ds","type":"branch","persona":"Riya","source":"5 Ds / Delay","relearn":"Delay: check in afterwards, 'are you okay?'.","hook":"A girl got groped in a crowded temple queue; it's over and she's standing alone, frozen.","options":[{"text":"Stand beside her: 'That was not your fault. Are you okay?'","consequence":"She hears it wasn't her fault.","outcome":"delay","best":true},{"text":"Whisper about it to others nearby","consequence":"Check in kindly (Delay); don't fuel gossip."}],"debrief":"Delay centres the person — comfort, not chatter."},
  {"id":"st-1097","cat":"five-ds","type":"branch","persona":"Veer","source":"5 Ds / Direct","relearn":"Direct: when safe, calmly name that it's not okay.","hook":"A cousin keeps sending a girl unwanted 'good morning' flirts; you're all in a safe room.","options":[{"text":"Say it plainly: 'She asked you to stop — so stop messaging her.'","consequence":"He can't pretend it's harmless.","outcome":"direct","best":true},{"text":"Tell her to just block him and move on","consequence":"When safe, naming it to him (Direct) puts it on him, not her."}],"debrief":"Direct holds the harasser accountable, not the target."},
  {"id":"st-1098","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds","relearn":"There is always a D that fits the moment's safety.","hook":"A man gropes a girl on a moving bus, then sits glaring. It's not safe to confront him.","options":[{"text":"Pull the bell, tell the driver to stop, and help her off (Distract + Delegate)","consequence":"She's off the bus and safe.","outcome":"distract","best":true},{"text":"Stand over him and demand an apology","consequence":"Getting her off safely beats demanding an apology."}],"debrief":"Combine Ds — distract him, delegate to the driver, get her out."},
  {"id":"st-1099","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / matching","relearn":"For dangerous harassers, choose Distract or Delegate over Direct.","hook":"A man with a knife is threatening a vendor's daughter. Which D is right?","options":[{"text":"Back off and call emergency 112 immediately (Delegate)","consequence":"Trained responders take over.","outcome":"delegate","best":true},{"text":"Step in to disarm him","consequence":"Never confront a weapon — Delegate to 112."}],"debrief":"With real danger, Delegate to 112 — your safety comes first."},
  {"id":"st-1100","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / matching","relearn":"After harassment, use Delay to support the person.","hook":"It's all over; the harasser left; a boy who was groped looks shaken. Which D now?","options":[{"text":"Use Delay — sit with him: 'Are you okay? That wasn't okay.'","consequence":"He feels supported, not judged.","outcome":"delay","best":true},{"text":"Tell him boys can't be harassed","consequence":"Anyone can be harassed; Delay supports him afterwards."}],"debrief":"Delay is the after-the-moment D, for any target."},
  {"id":"st-1101","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Distract","relearn":"Distract: interrupt casually so the target can get away.","hook":"A trainer at the gym keeps 'correcting' a girl's posture with unwanted touching.","options":[{"text":"Walk over: 'Can you spot me? I need help right now' to pull him away","consequence":"She gets space from him.","outcome":"distract","best":true},{"text":"Accuse the trainer loudly mid-floor","consequence":"A casual pull-away is safer than a public accusation."}],"debrief":"Distract creates space without a confrontation."},
  {"id":"st-1102","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds / Delegate","relearn":"Delegate: get others or authority to help.","hook":"In the library a man keeps moving seats to sit too close to a student.","options":[{"text":"Tell the librarian: 'Please move him or her — he keeps following her seat.'","consequence":"Staff handle the seating.","outcome":"delegate","best":true},{"text":"Argue with him to back off","consequence":"Asking the librarian is safer than arguing."}],"debrief":"Delegate uses the staff who run the space."},
  {"id":"st-1103","cat":"five-ds","type":"branch","persona":"Riya","source":"5 Ds / Delay","relearn":"Delay: check in afterwards, 'are you okay?'.","hook":"A girl got obscene comments walking home; later she's at the chai stall, shaken.","options":[{"text":"Sit with her: 'I saw — that wasn't okay, and not your fault. You alright?'","consequence":"She feels believed and less alone.","outcome":"delay","best":true},{"text":"Tell her to take a different route next time","consequence":"Don't put it on her route — check in and support (Delay)."}],"debrief":"Delay supports without a hint of blame."},
  {"id":"st-1104","cat":"five-ds","type":"branch","persona":"Veer","source":"5 Ds / Direct","relearn":"Direct: when safe, calmly name that it's not okay.","hook":"Your group chat is sharing a girl's photo with crude captions. You can speak up safely.","options":[{"text":"Type it clearly: 'Delete this. Sharing her photo like this is harassment.'","consequence":"Some go quiet; one deletes it.","outcome":"direct","best":true},{"text":"Stay silent so you're not the buzzkill","consequence":"When it's safe, a clear Direct line can shift the whole chat."}],"debrief":"Direct online means naming it plainly and refusing to join."},
  {"id":"st-1105","cat":"five-ds","type":"branch","persona":"any","source":"5 Ds","relearn":"There is always a D that fits the moment's safety.","hook":"A man exposes himself to commuters from a doorway. It is not safe to approach.","options":[{"text":"Move people away and call emergency 112 (Distract + Delegate)","consequence":"Commuters are clear; help is coming.","outcome":"distract","best":true},{"text":"Walk up to confront him alone","consequence":"Don't approach — distract others away and Delegate to 112."}],"debrief":"Pick the D that keeps you safe; here, distract and delegate."},
  {"id":"st-1106","cat":"five-ds","type":"role-play","persona":"Riya","source":"5 Ds / Distract voice","relearn":"A friendly 'I've been looking for you' is a perfect Distract.","hook":"You use Distract on a girl being followed in the market.","setup":"Walk up to her and say:","yourLine":[{"text":"\"There you are! I've been looking everywhere — come, let's go this way.\"","best":true},{"text":"Walk past quietly"}]},
  {"id":"st-1107","cat":"five-ds","type":"role-play","persona":"any","source":"5 Ds / Delegate voice","relearn":"Asking a specific person for a specific job gets a real response.","hook":"You use Delegate on a bus where a man won't stop hassling someone.","setup":"Turn to the conductor and say:","yourLine":[{"text":"\"Bhaiya, this man is troubling her — please stop the bus or move her up front.\"","best":true},{"text":"Mumble that someone should do something"}]},
  {"id":"st-1108","cat":"five-ds","type":"role-play","persona":"Veer","source":"5 Ds / Direct voice","relearn":"A calm, clear 'that's not okay' is a strong Direct move when it's safe.","hook":"You use Direct in a safe classroom on a friend harassing a girl.","setup":"Look at your friend and say:","yourLine":[{"text":"\"That's not okay, yaar. Leave her alone — for real.\"","best":true},{"text":"Look away and say nothing"}]},
  {"id":"st-1109","cat":"five-ds","type":"role-play","persona":"Riya","source":"5 Ds / Delay voice","relearn":"A gentle 'are you okay?' afterwards is the heart of Delay.","hook":"You use Delay after a girl was catcalled near school.","setup":"Walk over once it's calm and say:","yourLine":[{"text":"\"Hey — that was horrible and not your fault. Are you okay?\"","best":true},{"text":"Act like nothing happened"}]},
  {"id":"st-1110","cat":"five-ds","type":"role-play","persona":"any","source":"5 Ds / Document voice","relearn":"Offer the record to the target on their terms — never post it.","hook":"You used Document safely; now you offer it to the person harmed.","setup":"Hand over your phone and say:","yourLine":[{"text":"\"I recorded it from a safe spot. It's yours — use it however you want, or not.\"","best":true},{"text":"Post the clip 'to expose him'"}]},
  {"id":"st-1111","cat":"five-ds","type":"role-play","persona":"any","source":"5 Ds / Delegate voice","relearn":"Asking specific people by name turns bystanders into helpers.","hook":"You use Delegate at a station when a girl is being trailed.","setup":"Point and say to two adults:","yourLine":[{"text":"\"You in the blue, and you — please walk with her to the police booth?\"","best":true},{"text":"Hope a stranger steps up"}]},
  {"id":"st-1112","cat":"five-ds","type":"role-play","persona":"Riya","source":"5 Ds / Distract voice","relearn":"A dropped-bag distraction can break a harasser's focus safely.","hook":"You use Distract on a metro when a man crowds a girl.","setup":"Near them, say loudly:","yourLine":[{"text":"\"Oh no, my bag! Can you help me a sec?\" to pull attention and make room.","best":true},{"text":"Stare and do nothing"}]},
  {"id":"st-1113","cat":"five-ds","type":"role-play","persona":"Veer","source":"5 Ds / Direct voice","relearn":"Refusing to join, out loud, is a Direct move that shifts the group.","hook":"Your friends are 'rating' girls; it's safe to speak.","setup":"Tell the group:","yourLine":[{"text":"\"I'm out — this isn't funny, it's harassment. Knock it off.\"","best":true},{"text":"Smile and go along with it"}]},
  {"id":"st-1114","cat":"five-ds","type":"role-play","persona":"any","source":"5 Ds / Delay voice","relearn":"Naming that it wasn't their fault is the most powerful Delay line.","hook":"You use Delay with a boy who was groped and looks ashamed.","setup":"Sit beside him and say:","yourLine":[{"text":"\"That was not your fault. Freezing is normal. I'm here if you want.\"","best":true},{"text":"Tell him to just forget it"}]},
  {"id":"st-1115","cat":"five-ds","type":"role-play","persona":"any","source":"5 Ds / Delegate voice","relearn":"Calling for adult help is a brave, safe Delegate — not 'snitching'.","hook":"You use Delegate when a teacher could stop ongoing harassment.","setup":"Go to the teacher and say:","yourLine":[{"text":"\"Ma'am, she's being harassed by some boys — can you come now, please?\"","best":true},{"text":"Stay quiet so no one calls you a snitch"}]},
  {"id":"st-1116","cat":"five-ds","type":"match","persona":"any","source":"5 Ds","relearn":"Each of the five Ds is a distinct, safe way to help.","hook":"Match each D to what it does.","pairs":[{"left":"Distract","right":"Interrupt so they can get away"},{"left":"Delegate","right":"Get others or authority"},{"left":"Document","right":"Record safely, for the target"},{"left":"Delay","right":"Check in afterwards"},{"left":"Direct","right":"Calmly name it, when safe"}]},
  {"id":"st-1117","cat":"five-ds","type":"match","persona":"any","source":"5 Ds / matching","relearn":"Choose the D that fits the safety of the moment.","hook":"Match each moment to the best D.","pairs":[{"left":"Dangerous harasser","right":"Distract the target away"},{"left":"Need adult help","right":"Delegate to a teacher"},{"left":"Safe to record","right":"Document for the target"},{"left":"It's all over","right":"Delay — check in"},{"left":"Clearly safe to speak","right":"Direct — name it"}]},
  {"id":"st-1118","cat":"five-ds","type":"match","persona":"any","source":"5 Ds / voice","relearn":"The right words make each D work.","hook":"Match the D to a line that does it.","pairs":[{"left":"Distract","right":"\"There you are, let's go!\""},{"left":"Delegate","right":"\"Bhaiya, please help her now.\""},{"left":"Document","right":"\"I recorded it — it's yours.\""},{"left":"Delay","right":"\"Are you okay? Not your fault.\""},{"left":"Direct","right":"\"That's not okay. Stop.\""}]},
  {"id":"st-1119","cat":"five-ds","type":"match","persona":"any","source":"5 Ds / settings","relearn":"A safe D fits every place harassment happens.","hook":"Match the setting to a safe move.","pairs":[{"left":"Crowded bus","right":"Pull the bell, tell the driver"},{"left":"College corridor","right":"Fetch a teacher"},{"left":"Online group chat","right":"Say 'delete this'"},{"left":"After it's over","right":"Check in: 'you okay?'"},{"left":"Safe market","right":"Record from a distance"}]},
  {"id":"st-1120","cat":"five-ds","type":"match","persona":"any","source":"5 Ds / not-a-D","relearn":"The five Ds never include dominating or shaming.","hook":"Match each move to safe D or not-a-D.","pairs":[{"left":"Interrupt casually","right":"Distract (a D)"},{"left":"Fetch a guard","right":"Delegate (a D)"},{"left":"Shove the harasser","right":"Not a D — escalates"},{"left":"Post to shame him","right":"Not a D — misuse"},{"left":"Check in after","right":"Delay (a D)"}]},
  {"id":"st-1121","cat":"five-ds","type":"match","persona":"any","source":"5 Ds / outcome","relearn":"Each safe D leads to a kind, real outcome.","hook":"Match the D to what it gives the target.","pairs":[{"left":"Distract","right":"A chance to get away"},{"left":"Delegate","right":"Trained help on the scene"},{"left":"Document","right":"Proof they control"},{"left":"Delay","right":"Comfort and belief"},{"left":"Direct","right":"The behaviour named, safely"}]},
  {"id":"st-1122","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds in action","relearn":"Delegate means getting someone with authority; Distract means defusing the moment yourself.","hook":"Sort: is this a Delegate move or a Distract move?","items":[{"id":"a","text":"Asking a guard to step in"},{"id":"b","text":"Dropping your bag to break the moment"},{"id":"c","text":"Flagging down a staff member"},{"id":"d","text":"Asking the target a random question"},{"id":"e","text":"Telling the bus conductor"},{"id":"f","text":"Pretending you know the target"}],"bins":[{"id":"del","label":"Delegate","valence":"pos"},{"id":"dis","label":"Distract","valence":"pos"}],"key":{"a":"del","b":"dis","c":"del","d":"dis","e":"del","f":"dis"}},
  {"id":"st-1123","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds / safety","relearn":"Distraction and getting help are safe; shoving and threats escalate.","hook":"Sort: helps safely, or escalates the danger?","items":[{"id":"a","text":"Pretend to know the target"},{"id":"b","text":"Shove the harasser"},{"id":"c","text":"Alert a guard"},{"id":"d","text":"Yell threats"},{"id":"e","text":"Pull the bus bell for the driver"},{"id":"f","text":"Block his path"}],"bins":[{"id":"safe","label":"Helps safely","valence":"pos"},{"id":"esc","label":"Escalates","valence":"neg"}],"key":{"a":"safe","b":"esc","c":"safe","d":"esc","e":"safe","f":"esc"}},
  {"id":"st-1124","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds / Document","relearn":"Document is only-if-safe, for the target's use, never posted for clicks.","hook":"Sort: a right use of Document, or a misuse?","items":[{"id":"a","text":"Record safely, give clip to her"},{"id":"b","text":"Post it to shame him"},{"id":"c","text":"Note the time and place for her"},{"id":"d","text":"Livestream for laughs"},{"id":"e","text":"Hand proof to a guard to report"},{"id":"f","text":"Chase him to film closer"}],"bins":[{"id":"right","label":"Right use","valence":"pos"},{"id":"wrong","label":"Misuse","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"wrong","e":"right","f":"wrong"}},
  {"id":"st-1125","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds / danger","relearn":"For a dangerous harasser, choose Distract or Delegate, never Direct.","hook":"Sort: safe with a DANGEROUS harasser, or too risky?","items":[{"id":"a","text":"Distract the target away"},{"id":"b","text":"Confront him directly"},{"id":"c","text":"Call emergency 112"},{"id":"d","text":"Try to disarm him"},{"id":"e","text":"Get police from the booth"},{"id":"f","text":"Threaten him back"}],"bins":[{"id":"safe","label":"Safe with danger","valence":"pos"},{"id":"risky","label":"Too risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"}},
  {"id":"st-1126","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds / timing","relearn":"Some Ds fit the live moment; Delay fits afterwards.","hook":"Sort: a move for DURING, or for AFTER the moment?","items":[{"id":"a","text":"Distract to break it up"},{"id":"b","text":"Check in: 'you okay?'"},{"id":"c","text":"Delegate to a guard now"},{"id":"d","text":"Say 'it wasn't your fault'"},{"id":"e","text":"Direct: 'stop, that's not okay'"},{"id":"f","text":"Walk them home, talk it out"}],"bins":[{"id":"during","label":"During","valence":"tell"},{"id":"after","label":"After","valence":"pos"}],"key":{"a":"during","b":"after","c":"during","d":"after","e":"during","f":"after"}},
  {"id":"st-1127","cat":"five-ds","type":"sort","persona":"any","source":"5 Ds / which-D","relearn":"Name the D behind each safe move.","hook":"Sort each safe line under the D it is.","items":[{"id":"a","text":"\"Come sit with me!\""},{"id":"b","text":"\"Guard, please help her.\""},{"id":"c","text":"\"Here's the clip — it's yours.\""},{"id":"d","text":"\"Are you okay after?\""},{"id":"e","text":"\"That's not okay. Stop.\""},{"id":"f","text":"\"Officer, two men are trailing her.\""}],"bins":[{"id":"distract","label":"Distract","valence":"neutral"},{"id":"delegate","label":"Delegate","valence":"tell"},{"id":"other","label":"Document/Delay/Direct","valence":"pos"}],"key":{"a":"distract","b":"delegate","c":"other","d":"other","e":"other","f":"delegate"}},
  {"id":"st-1128","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds","relearn":"With five Ds, there's always a safe way to help.","hook":"Lensy: five moves means you're never stuck choosing between hero or nothing. Reassuring?","prompt":"What do you feel?","options":["Yes, always one","I can pick a safe D","Less stuck now"],"affirm":"Five Ds means there's always at least one safe move you can make."},
  {"id":"st-1129","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds / safety-first","relearn":"Your safety comes first — the bravest move is the safe one.","hook":"Lensy: the safe D is the brave choice, not the cowardly one. Sit with that.","prompt":"Which feels true?","options":["Safe is brave","I don't have to fight","Helping safely counts"],"affirm":"Choosing a safe D is courage — you help without becoming a second victim."},
  {"id":"st-1130","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds / Delay","relearn":"A check-in afterwards can matter as much as acting in the moment.","hook":"Lensy: even a quiet 'are you okay?' after is real help. Does that land?","prompt":"What do you think?","options":["Yes, it counts","Small things help","I could do that"],"affirm":"Delay — a kind check-in afterwards — is real, valued help."},
  {"id":"st-1131","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds / matching","relearn":"There's a D for every kind of moment, safe or after.","hook":"Lensy: which D feels most like you — the quiet Distract, or the firm Direct?","prompt":"Pick what fits you:","options":["Quiet Distract","Firm Direct","Steady Delegate"],"affirm":"Any D that fits you and the moment's safety is a good one to grow."},
  {"id":"st-1132","cat":"five-ds","type":"reflect","persona":"Riya","source":"5 Ds","relearn":"You can be both the one who acts and the one who's supported.","hook":"Lensy: imagine using one D this week. Which feels doable for you?","prompt":"Choose one:","options":["Distract","Delegate","Delay"],"affirm":"Picturing yourself using a D makes it easier to do it for real."},
  {"id":"st-1133","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds / Document","relearn":"Even when you can't speak up, you can quietly keep a record for someone.","hook":"Lensy: Document lets you help even when it's not safe to step in. How's that?","prompt":"What's your take?","options":["Good to know","I can still help","Quiet but real"],"affirm":"Document is a safe way to help even when stepping in isn't an option."},
  {"id":"st-1134","cat":"five-ds","type":"reflect","persona":"any","source":"5 Ds","relearn":"Knowing the five Ds turns 'I froze' into 'next time I have a move'.","hook":"Lensy: which D would you most like to be ready with next time?","prompt":"Pick one to keep ready:","options":["Distract","Delegate","Direct"],"affirm":"Having one D ready means freezing once doesn't decide who you are."},
  {"id":"st-1135","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Direct","relearn":"Helping doesn't mean fighting; the five Ds are mostly no-contact.","hook":"Strike the myth, write the truth.","myth":{"un":"Helping means fighting the harasser.","re":"Helping means using a safe D — most don't involve confronting anyone.","why":"Four of the five Ds (Distract, Delegate, Document, Delay) need no confrontation at all."}},
  {"id":"st-1136","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / safety-first","relearn":"Your safety comes first; you never have to confront danger.","hook":"Strike the myth, write the truth.","myth":{"un":"If you can't be brave enough to confront him, don't bother.","re":"You don't confront danger — you Distract, Delegate, or call for help.","why":"The safe move is the right move; you help without becoming a second victim."}},
  {"id":"st-1137","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Document","relearn":"Document is for the target, never for public posting.","hook":"Strike the myth, write the truth.","myth":{"un":"If you film harassment, post it to expose the creep.","re":"If you film it safely, give it to the target to use as they choose.","why":"Posting it can re-harm the target; Document keeps control with them."}},
  {"id":"st-1138","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Direct","relearn":"Direct is only the best move when the scene is clearly safe.","hook":"Strike the myth, write the truth.","myth":{"un":"A real upstander always confronts the harasser face to face.","re":"A smart upstander only goes Direct when it's safe — else Distract or Delegate.","why":"Confronting a dangerous harasser can make you a second target; safe Ds protect you both."}},
  {"id":"st-1139","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds","relearn":"There's always a D that fits — you're never stuck with 'nothing'.","hook":"Strike the myth, write the truth.","myth":{"un":"Either you're a hero or you do nothing.","re":"With five Ds, there's always a safe middle move you can make.","why":"Distract, Delegate, Document, Delay or Direct — one always fits the moment."}},
  {"id":"st-1140","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Delegate","relearn":"Getting adult or authority help is smart, not weak or 'snitching'.","hook":"Strike the myth, write the truth.","myth":{"un":"Calling a teacher or guard for help is just snitching.","re":"Delegating to an adult is the strong, safe move — that's what they're for.","why":"Bringing in authority gets the target real help and keeps everyone safer."}},
  {"id":"st-1141","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Delay","relearn":"Checking in afterwards is real help, not 'too late'.","hook":"Strike the myth, write the truth.","myth":{"un":"If you didn't act in the moment, it's too late to help.","re":"You can still help afterwards — a Delay check-in matters a lot.","why":"Freezing is normal; a kind 'are you okay?' later is genuine, valued support."}},
  {"id":"st-1142","cat":"five-ds","type":"strike-rewrite","persona":"any","source":"5 Ds / Distract","relearn":"Distract works because it sidesteps the fight, not because it's 'sneaky'.","hook":"Strike the myth, write the truth.","myth":{"un":"Pretending you know the target is a coward's trick.","re":"Distracting to give the target an exit is a clever, safe way to help.","why":"Distract ends harassment without a confrontation — that's its whole strength."}},
  {"id":"st-1143","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / Document","relearn":"Document is only-if-safe and for the target — never posting or chasing.","hook":"Spot the two moves that MISUSE Document (the red flags).","scene":[{"id":"a","text":"Record safely from a distance","trick":false},{"id":"b","text":"Post the clip to shame him","trick":true},{"id":"c","text":"Give the clip to the target","trick":false},{"id":"d","text":"Chase him to film up close","trick":true},{"id":"e","text":"Note the time and place for her","trick":false}],"why":"Posting and chasing both break Document's rules: it's only-if-safe and for the target."},
  {"id":"st-1144","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / danger","relearn":"With a dangerous harasser, Direct/confront is the wrong move.","hook":"Spot the two UNSAFE moves with a dangerous harasser (the red flags).","scene":[{"id":"a","text":"Distract the target away","trick":false},{"id":"b","text":"Walk up and confront him","trick":true},{"id":"c","text":"Call emergency 112","trick":false},{"id":"d","text":"Try to disarm him yourself","trick":true},{"id":"e","text":"Get police from the booth","trick":false}],"why":"Confronting and disarming a dangerous harasser can make you a second victim — Distract or Delegate."},
  {"id":"st-1145","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / not-a-D","relearn":"The five Ds never include dominating or threatening.","hook":"Spot the two moves that are NOT real Ds (the red flags).","scene":[{"id":"a","text":"Distract casually","trick":false},{"id":"b","text":"Dominate and threaten him","trick":true},{"id":"c","text":"Delegate to a guard","trick":false},{"id":"d","text":"Shove him out of the way","trick":true},{"id":"e","text":"Delay — check in after","trick":false}],"why":"Dominating and shoving aren't Ds — they escalate the danger instead of defusing it."},
  {"id":"st-1146","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / Delay","relearn":"A Delay check-in supports the target — it never blames them.","hook":"Spot the two BLAMING things to never say afterwards (the red flags).","scene":[{"id":"a","text":"\"Are you okay?\"","trick":false},{"id":"b","text":"\"Why were you out so late?\"","trick":true},{"id":"c","text":"\"That wasn't your fault.\"","trick":false},{"id":"d","text":"\"Maybe don't wear that.\"","trick":true},{"id":"e","text":"\"I'm here if you need me.\"","trick":false}],"why":"Blaming clothes or being out is victim-blaming; a real Delay only supports, never blames."},
  {"id":"st-1147","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / Direct","relearn":"Direct must stay calm and name the behaviour — not insult or threaten.","hook":"Spot the two lines that AREN'T a safe Direct move (the red flags).","scene":[{"id":"a","text":"\"That's not okay — stop.\"","trick":false},{"id":"b","text":"\"I'll thrash you, get lost!\"","trick":true},{"id":"c","text":"\"Leave them alone, please.\"","trick":false},{"id":"d","text":"\"You're a disgusting freak!\"","trick":true},{"id":"e","text":"\"This isn't a joke — quit it.\"","trick":false}],"why":"Threats and insults escalate; a safe Direct calmly names the behaviour, only when it's safe."},
  {"id":"st-1148","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / Delegate","relearn":"Delegate means asking specific people or authority for real help.","hook":"Spot the two NON-moves dressed up as helping (the red flags).","scene":[{"id":"a","text":"Tell the conductor directly","trick":false},{"id":"b","text":"Hope someone else acts","trick":true},{"id":"c","text":"Ask two adults by name","trick":false},{"id":"d","text":"Film for likes, not help","trick":true},{"id":"e","text":"Walk her to the police booth","trick":false}],"why":"Hoping someone acts and filming for likes aren't Delegate — they leave the target alone."},
  {"id":"st-1149","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / Distract","relearn":"Distract interrupts to free the target — it never confronts or shames.","hook":"Spot the two moves that are NOT Distract (the red flags).","scene":[{"id":"a","text":"\"There you are, come with me!\"","trick":false},{"id":"b","text":"Pick a fight with the harasser","trick":true},{"id":"c","text":"\"Sorry, can you help me a sec?\"","trick":false},{"id":"d","text":"Loudly shame him to the crowd","trick":true},{"id":"e","text":"Drop your bag to make room","trick":false}],"why":"Fighting and public shaming aren't Distract — they confront him instead of freeing the target."},
  {"id":"st-1150","cat":"five-ds","type":"spot","persona":"any","source":"5 Ds / safety-first","relearn":"Every safe D protects you while you help — risky moves don't.","hook":"Spot the two moves that risk YOUR safety (the red flags).","scene":[{"id":"a","text":"Call for help from a safe spot","trick":false},{"id":"b","text":"Grab the harasser's collar","trick":true},{"id":"c","text":"Distract the target toward you","trick":false},{"id":"d","text":"Chase him down the street","trick":true},{"id":"e","text":"Fetch the guard nearby","trick":false}],"why":"Grabbing and chasing put you in danger; safe Ds let you help without becoming a second victim."},
  {"id":"st-1170","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Riya","source":"rights","relearn":"It's harassment, named honestly, and it makes places feel unsafe.","hook":"\"Whistling at girls on the street is just guys being friendly.\"","myth":{"un":"Whistling and catcalling at strangers is friendly fun.","re":"It's harassment, named honestly, and it makes places feel unsafe.","why":"It's unwanted and aimed to unsettle, not to greet."}},
  {"id":"st-1171","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"no victim-blaming","relearn":"Being out at night never invites harm; the choice is the harasser's.","hook":"\"If a girl is out late, she's partly asking for trouble.\"","myth":{"un":"Being out late means a girl is partly asking for trouble.","re":"Being out at night never invites harm; the choice is the harasser's.","why":"Everyone has the right to use public space, any hour."}},
  {"id":"st-1172","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Veer","source":"accountability","relearn":"Comments about someone's body are harassment, not banter.","hook":"\"Commenting on a classmate's body is just locker-room talk.\"","myth":{"un":"Commenting on a classmate's body is harmless locker-room talk.","re":"Comments about someone's body are harassment, not banter.","why":"Unwanted body 'talk' targets and shames a real person."}},
  {"id":"st-1173","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"definition","relearn":"Repeating it after a no makes it harassment, not a joke.","hook":"\"It's only a joke, so it can't be harassment.\"","myth":{"un":"If it's meant as a joke it can't be harassment.","re":"Repeating it after a no makes it harassment, not a joke.","why":"What matters is the impact and the unwanted repetition."}},
  {"id":"st-1174","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Quiet harassment is still harassment; you can still say no.","hook":"\"If no one's shouting or hitting, it isn't really harassment.\"","myth":{"un":"Harassment only counts if it's loud or physical.","re":"Quiet harassment is still harassment; you can still say no.","why":"Staring, following and creepy messages all count."}},
  {"id":"st-1175","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Riya","source":"forms of GBV","relearn":"Unwanted touch dressed as 'just teasing' is harassment.","hook":"\"Pinching or poking someone you fancy is just playful teasing.\"","myth":{"un":"Touching someone you like is just playful teasing.","re":"Unwanted touch dressed as 'just teasing' is harassment.","why":"Touch needs a yes; 'liking' someone never grants it."}},
  {"id":"st-1176","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"online GBV","relearn":"Pressuring for private photos is harassment, not flirting.","hook":"\"Begging a girl for her photos online is just keen flirting.\"","myth":{"un":"Repeatedly asking a girl for private photos is keen flirting.","re":"Pressuring for private photos is harassment, not flirting.","why":"Pressure after a no is coercion, not interest."}},
  {"id":"st-1177","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Harassment can happen anywhere; place doesn't make it okay.","hook":"\"Harassment only happens in rough areas, not good schools.\"","myth":{"un":"Harassment only happens in rough areas, not nice schools.","re":"Harassment can happen anywhere; place doesn't make it okay.","why":"A polished setting hides the same wrong behaviour."}},
  {"id":"st-1178","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Veer","source":"accountability","relearn":"Trying to wear someone down is harassment, not persistence.","hook":"\"A real man keeps chasing a girl until she finally says yes.\"","myth":{"un":"A real man keeps chasing a girl till she says yes.","re":"Trying to wear someone down is harassment, not persistence.","why":"A no is an answer; pushing past it removes her choice."}},
  {"id":"st-1179","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Power doesn't licence harassment; everyone has the right to refuse.","hook":"\"A senior or a boss can comment on juniors however they like.\"","myth":{"un":"Someone senior can comment on juniors however they like.","re":"Power doesn't licence harassment; everyone has the right to refuse.","why":"Rank never cancels another person's right to safety."}},
  {"id":"st-1180","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Refusing isn't rude; protecting your boundary is your right.","hook":"\"Saying no to a creepy uncle's hug is just being rude.\"","myth":{"un":"Refusing an unwanted hug from an elder is just rude.","re":"Refusing isn't rude; protecting your boundary is your right.","why":"You can decline touch politely and still mean no."}},
  {"id":"st-1181","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Riya","source":"rights","relearn":"Your discomfort is reason enough; you don't owe an explanation.","hook":"\"You can only object if you can prove they 'meant' something bad.\"","myth":{"un":"You can only object if you can prove bad intent.","re":"Your discomfort is reason enough; you don't owe an explanation.","why":"Unwanted is unwanted, whatever they claim they meant."}},
  {"id":"st-1182","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"forms of GBV","relearn":"Spreading sexual rumours is harassment that really harms.","hook":"\"Sharing gossip about who's 'easy' is just normal school chatter.\"","myth":{"un":"Gossip about who is 'easy' is just normal chatter.","re":"Spreading sexual rumours is harassment that really harms.","why":"Such rumours shame and isolate a real classmate."}},
  {"id":"st-1183","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"online GBV","relearn":"Threatening to share photos is harassment and abuse.","hook":"\"Threatening to post someone's photos to scare them is just a threat.\"","myth":{"un":"Threatening to leak photos is just an empty threat.","re":"Threatening to share photos is harassment and abuse.","why":"The fear it creates is real and meant to control."}},
  {"id":"st-1184","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Counsellor","source":"rights / help","relearn":"Telling a trusted adult is brave and right, not 'snitching'.","hook":"\"Telling a teacher about harassment makes you a snitch.\"","myth":{"un":"Reporting harassment to a teacher makes you a snitch.","re":"Telling a trusted adult is brave and right, not 'snitching'.","why":"Asking for help stops harm; silence only shields it."}},
  {"id":"st-1185","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"no victim-blaming","relearn":"Freezing is a normal response; it never makes harm your fault.","hook":"\"If you froze and didn't shout, you let it happen.\"","myth":{"un":"Freezing instead of shouting means you let it happen.","re":"Freezing is a normal response; it never makes harm your fault.","why":"The body often freezes under threat; that's not consent."}},
  {"id":"st-1186","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Veer","source":"ally","relearn":"Joining in to fit in is still harassment you can refuse.","hook":"\"If your friends are teasing a girl, you have to join in.\"","myth":{"un":"If your friends tease a girl you must join in.","re":"Joining in to fit in is still harassment you can refuse.","why":"You can stand apart; being in a group is no excuse."}},
  {"id":"st-1187","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Boys and men can be harassed too; it's wrong whoever it targets.","hook":"\"Boys can't really be harassed, so it doesn't count for them.\"","myth":{"un":"Boys can't really be harassed, so it never counts.","re":"Boys and men can be harassed too; it's wrong whoever it targets.","why":"Anyone's safety and dignity deserve the same respect."}},
  {"id":"st-1188","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"definition","relearn":"A welcome compliment differs from unwanted, repeated attention.","hook":"\"Any compliment could be harassment, so all of it is banned.\"","myth":{"un":"Every compliment is harassment, so all of it is banned.","re":"A welcome compliment differs from unwanted, repeated attention.","why":"The line is welcomeness, not whether words were kind."}},
  {"id":"st-1189","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Marriage or dating never erases the right to say no.","hook":"\"Once you're dating someone, you can't refuse their advances.\"","myth":{"un":"Once you're dating, you can't refuse someone's advances.","re":"Marriage or dating never erases the right to say no.","why":"Consent is needed every time, in every relationship."}},
  {"id":"st-1190","cat":"gbv-and-rights","type":"strike-rewrite","persona":"Counsellor","source":"rights / help","relearn":"Reporting is your right; a good system protects the person harmed.","hook":"\"Reporting harassment will only get the victim in trouble.\"","myth":{"un":"Reporting harassment only gets the victim into trouble.","re":"Reporting is your right; a good system protects the person harmed.","why":"Help should centre and shield the person who was harmed."}},
  {"id":"st-1191","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"forms of GBV","relearn":"Following someone home is stalking, a serious harassment.","hook":"\"Walking behind a girl all the way home is just coincidence.\"","myth":{"un":"Walking behind a girl all the way home is coincidence.","re":"Following someone home is stalking, a serious harassment.","why":"Repeated, deliberate following is meant to frighten."}},
  {"id":"st-1192","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Disabled people have the same right to refuse unwanted touch.","hook":"\"It's fine to grab a disabled person to 'help' without asking.\"","myth":{"un":"You can grab a disabled person to 'help' without asking.","re":"Disabled people have the same right to refuse unwanted touch.","why":"Help still needs a yes; touch without it is a violation."}},
  {"id":"st-1193","cat":"gbv-and-rights","type":"strike-rewrite","persona":"any","source":"rights","relearn":"Everyone has the right to safety, respect and to refuse touch.","hook":"\"Rights about safety are for adults; kids just have to cope.\"","myth":{"un":"Safety rights are for adults; kids just have to cope.","re":"Everyone has the right to safety, respect and to refuse touch.","why":"Young people hold these rights fully, today, not later."}},
  {"id":"st-1194","cat":"gbv-and-rights","type":"sort","persona":"any","source":"rights","relearn":"A right protects you; harassing or shaming others is never a right.","hook":"Sort: a real right, or not a right?","items":[{"id":"a","text":"To walk to school feeling safe"},{"id":"b","text":"To refuse an unwanted hug"},{"id":"c","text":"To touch someone without asking"},{"id":"d","text":"To be believed when you report"},{"id":"e","text":"To shame a girl for her clothes"},{"id":"f","text":"To ask for help and get it"}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"no","label":"Not a right","valence":"neg"}],"key":{"a":"right","b":"right","c":"no","d":"right","e":"no","f":"right"}},
  {"id":"st-1195","cat":"gbv-and-rights","type":"sort","persona":"any","source":"definition","relearn":"Unwanted, repeated or following behaviour is harassment; welcome contact isn't.","hook":"Sort: harassment, or ordinary welcome contact?","items":[{"id":"a","text":"Catcalling a stranger on the road"},{"id":"b","text":"A friend waving hello back"},{"id":"c","text":"Following someone who looks uneasy"},{"id":"d","text":"Sending sexual messages after a no"},{"id":"e","text":"Two friends laughing together"},{"id":"f","text":"Sharing a seat both agreed to"}],"bins":[{"id":"harass","label":"Harassment","valence":"neg"},{"id":"ok","label":"Welcome / okay","valence":"pos"}],"key":{"a":"harass","b":"ok","c":"harass","d":"harass","e":"ok","f":"ok"}},
  {"id":"st-1196","cat":"gbv-and-rights","type":"sort","persona":"any","source":"forms of GBV","relearn":"Groping, sexual rumours, photo threats and unwanted messages are all GBV.","hook":"Sort: a form of harassment/GBV, or not?","items":[{"id":"a","text":"Groping someone in a crowd"},{"id":"b","text":"Threatening to leak private photos"},{"id":"c","text":"A study group sharing notes"},{"id":"d","text":"Spreading sexual rumours about a girl"},{"id":"e","text":"Unwanted sexual messages online"},{"id":"f","text":"A teammate cheering a goal"}],"bins":[{"id":"gbv","label":"Harassment / GBV","valence":"neg"},{"id":"no","label":"Not GBV","valence":"pos"}],"key":{"a":"gbv","b":"gbv","c":"no","d":"gbv","e":"gbv","f":"no"}},
  {"id":"st-1197","cat":"gbv-and-rights","type":"sort","persona":"Riya","source":"no victim-blaming","relearn":"Nothing the target wore or did invites harassment; the harasser chose it.","hook":"Sort: who is responsible for harassment?","items":[{"id":"a","text":"The person who chose to grope"},{"id":"b","text":"What the target was wearing"},{"id":"c","text":"The person who kept following"},{"id":"d","text":"The target being out late"},{"id":"e","text":"The one who sent the threats"},{"id":"f","text":"The target freezing in shock"}],"bins":[{"id":"har","label":"The harasser","valence":"neutral"},{"id":"tgt","label":"Not the target","valence":"neutral"}],"key":{"a":"har","b":"tgt","c":"har","d":"tgt","e":"har","f":"tgt"}},
  {"id":"st-1198","cat":"gbv-and-rights","type":"sort","persona":"any","source":"rights","relearn":"Saying no, leaving, and asking for help are all things you're allowed to do.","hook":"Sort: something you're allowed to do, or not your job?","items":[{"id":"a","text":"Say a clear 'stop'"},{"id":"b","text":"Make the harasser change"},{"id":"c","text":"Walk away to safety"},{"id":"d","text":"Carry shame for what happened"},{"id":"e","text":"Tell a trusted adult"},{"id":"f","text":"Fix the harasser's behaviour alone"}],"bins":[{"id":"yours","label":"Your right","valence":"pos"},{"id":"not","label":"Not on you","valence":"neg"}],"key":{"a":"yours","b":"not","c":"yours","d":"not","e":"yours","f":"not"}},
  {"id":"st-1199","cat":"gbv-and-rights","type":"sort","persona":"any","source":"online GBV","relearn":"Online harassment is real: threats, pressure and leaked photos are GBV too.","hook":"Sort: online harassment, or fine online behaviour?","items":[{"id":"a","text":"Demanding nudes after a no"},{"id":"b","text":"Sending a class meme to friends"},{"id":"c","text":"Threatening to expose someone"},{"id":"d","text":"Liking a friend's post"},{"id":"e","text":"Flooding someone with creepy DMs"},{"id":"f","text":"Sharing homework in a group chat"}],"bins":[{"id":"harm","label":"Online harassment","valence":"neg"},{"id":"fine","label":"Fine","valence":"pos"}],"key":{"a":"harm","b":"fine","c":"harm","d":"fine","e":"harm","f":"fine"}},
  {"id":"st-1200","cat":"gbv-and-rights","type":"sort","persona":"Veer","source":"accountability","relearn":"Harassment is a choice; 'nature' and 'just a joke' are excuses, not reasons.","hook":"Sort: a fact about harassment, or an excuse for it?","items":[{"id":"a","text":"It's the harasser's choice"},{"id":"b","text":"'Boys just can't help it'"},{"id":"c","text":"The target deserves respect"},{"id":"d","text":"'It was only a joke'"},{"id":"e","text":"A clear no must be respected"},{"id":"f","text":"'She was asking for it'"}],"bins":[{"id":"fact","label":"A fact","valence":"pos"},{"id":"excuse","label":"An excuse","valence":"neg"}],"key":{"a":"fact","b":"excuse","c":"fact","d":"excuse","e":"fact","f":"excuse"}},
  {"id":"st-1201","cat":"gbv-and-rights","type":"sort","persona":"any","source":"definition","relearn":"The line is welcomeness: unwanted and repeated is harassment; welcome contact isn't.","hook":"Sort: crosses the line, or stays welcome?","items":[{"id":"a","text":"Staring and commenting on a body"},{"id":"b","text":"A planned hug between friends"},{"id":"c","text":"Touching after being told no"},{"id":"d","text":"A high-five both wanted"},{"id":"e","text":"Cornering someone who wants to leave"},{"id":"f","text":"Chatting that both enjoy"}],"bins":[{"id":"cross","label":"Crosses the line","valence":"neg"},{"id":"ok","label":"Stays welcome","valence":"pos"}],"key":{"a":"cross","b":"ok","c":"cross","d":"ok","e":"cross","f":"ok"}},
  {"id":"st-1202","cat":"gbv-and-rights","type":"sort","persona":"any","source":"rights","relearn":"Everyone holds the same rights to safety and refusal, whoever they are.","hook":"Sort: who has the right to be safe and refuse touch?","items":[{"id":"a","text":"A girl on a crowded bus"},{"id":"b","text":"'Boys don't need this right'"},{"id":"c","text":"A disabled student"},{"id":"d","text":"'Late means you gave it up'"},{"id":"e","text":"A new kid no one knows"},{"id":"f","text":"'Only adults get these rights'"}],"bins":[{"id":"all","label":"Has this right","valence":"pos"},{"id":"myth","label":"Myth that they don't","valence":"neg"}],"key":{"a":"all","b":"myth","c":"all","d":"myth","e":"all","f":"myth"}},
  {"id":"st-1203","cat":"gbv-and-rights","type":"sort","persona":"Counsellor","source":"rights / help","relearn":"Reporting, being believed and getting support are your rights after harm.","hook":"Sort: a right you have after harassment, or a myth?","items":[{"id":"a","text":"To report and be taken seriously"},{"id":"b","text":"'Speaking up makes it your fault'"},{"id":"c","text":"To be believed, not blamed"},{"id":"d","text":"'You must just stay quiet'"},{"id":"e","text":"To get support and a check-in"},{"id":"f","text":"'Asking for help is shameful'"}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"right","b":"myth","c":"right","d":"myth","e":"right","f":"myth"}},
  {"id":"st-1204","cat":"gbv-and-rights","type":"match","persona":"any","source":"rights","relearn":"Each harassment myth has a clear, rights-based truth that answers it.","hook":"Match the myth to the truth that answers it.","pairs":[{"left":"\"It's a compliment\"","right":"It's unwanted harassment"},{"left":"\"She invited it\"","right":"Never the target's fault"},{"left":"\"Boys can't help it\"","right":"Harassment is a choice"},{"left":"\"Just put up with it\"","right":"Safety is a right"},{"left":"\"Only girls face it\"","right":"Anyone can be a target"}]},
  {"id":"st-1205","cat":"gbv-and-rights","type":"match","persona":"any","source":"forms of GBV","relearn":"Name each behaviour for what it is: a specific form of harassment.","hook":"Match the behaviour to what it's called.","pairs":[{"left":"Grabbing in a crowd","right":"Groping"},{"left":"Following someone home","right":"Stalking"},{"left":"Whistling at a stranger","right":"Catcalling"},{"left":"Demanding nudes online","right":"Online coercion"},{"left":"Spreading sexual rumours","right":"Character attack"}]},
  {"id":"st-1206","cat":"gbv-and-rights","type":"match","persona":"any","source":"rights / help","relearn":"Each right is backed by something concrete you can lean on.","hook":"Match the right to what backs it up.","pairs":[{"left":"Right to feel safe","right":"Laws against harassment"},{"left":"Right to refuse touch","right":"Consent"},{"left":"Right to get support","right":"Helplines like 181"},{"left":"Right to be believed","right":"A trusted adult who listens"},{"left":"Right to move freely","right":"Public space for all"}]},
  {"id":"st-1207","cat":"gbv-and-rights","type":"match","persona":"any","source":"definition","relearn":"Welcomeness is the line: the same act can be fine or harassment.","hook":"Match each act to whether it's welcome or harassment.","pairs":[{"left":"A hug both planned","right":"Welcome"},{"left":"Touch after a clear no","right":"Harassment"},{"left":"A wave to a friend","right":"Friendly"},{"left":"Following an uneasy stranger","right":"Stalking"},{"left":"A chat both enjoy","right":"Mutual"}]},
  {"id":"st-1208","cat":"gbv-and-rights","type":"match","persona":"Counsellor","source":"rights / help","relearn":"India's helplines connect harassment to real, named support.","hook":"Match the need to the helpline that fits.","pairs":[{"left":"A woman in distress","right":"Women Helpline 181"},{"left":"An emergency right now","right":"Emergency 112"},{"left":"A child needs support","right":"Childline 1098"},{"left":"Someone to believe you","right":"A trusted adult"},{"left":"Knowing it's not your fault","right":"A clear rights frame"}]},
  {"id":"st-1209","cat":"gbv-and-rights","type":"match","persona":"any","source":"no victim-blaming","relearn":"Responsibility for harassment sits with the harasser's choice, never the target.","hook":"Match each thing to where it truly belongs.","pairs":[{"left":"The choice to harass","right":"On the harasser"},{"left":"What the target wore","right":"Irrelevant to blame"},{"left":"Freezing in shock","right":"A normal response"},{"left":"The shame after harm","right":"Not the target's to carry"},{"left":"Stopping the harm","right":"Everyone's job"}]},
  {"id":"st-1210","cat":"gbv-and-rights","type":"match","persona":"Riya","source":"rights","relearn":"Turn each fear into the right that answers it.","hook":"Match the worry to the right that reassures it.","pairs":[{"left":"\"I can't say no\"","right":"You can refuse"},{"left":"\"No one will believe me\"","right":"You deserve belief"},{"left":"\"It's my fault\"","right":"It never is"},{"left":"\"I must cope alone\"","right":"Help exists for you"},{"left":"\"I have to stay quiet\"","right":"Reporting is your right"}]},
  {"id":"st-1211","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"rights","relearn":"Everyone has the right to move through public space feeling safe.","hook":"Lensy: a bus, a lane, a school gate — should they feel safe for everyone?","prompt":"What do you think?","options":["Yes, for everyone","Definitely","It's a basic right"],"affirm":"Safe public space is everyone's right, no exceptions."},
  {"id":"st-1212","cat":"gbv-and-rights","type":"reflect","persona":"Riya","source":"no victim-blaming","relearn":"Harassment is never the target's fault, whatever they wore or did.","hook":"Lensy: when someone is harassed, whose choice was the harassment?","prompt":"What do you think?","options":["The harasser's","Not the target's","Always the harasser's"],"affirm":"The harasser chose it; the target carries none of the blame."},
  {"id":"st-1213","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"rights","relearn":"You can say no to unwanted touch, and that no deserves respect.","hook":"Lensy: do you have the right to say no to touch you didn't want?","prompt":"What do you think?","options":["Always","Yes, every time","It's my body"],"affirm":"Your no is enough, every time — your body, your boundary."},
  {"id":"st-1214","cat":"gbv-and-rights","type":"reflect","persona":"Veer","source":"ally","relearn":"Anyone can be harassed; it's wrong whoever the target is.","hook":"Lensy: does it matter who's being harassed for it to be wrong?","prompt":"What do you think?","options":["No, wrong is wrong","Anyone counts","It's wrong regardless"],"affirm":"Harassment is wrong whoever it targets — girl, boy, anyone."},
  {"id":"st-1215","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"definition","relearn":"The line is welcomeness: unwanted, persistent behaviour is harassment.","hook":"Lensy: what makes contact harassment rather than friendly?","prompt":"What do you think?","options":["Whether it's wanted","If they said no","The impact on them"],"affirm":"Welcomeness is the line — unwanted and repeated crosses it."},
  {"id":"st-1216","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"rights / help","relearn":"Reporting harassment is your right and can stop the harm.","hook":"Lensy: knowing help exists, what does reporting do?","prompt":"What do you think?","options":["Stops harm","Protects others too","Breaks the silence"],"affirm":"Reporting is your right; it can stop harm and shield others."},
  {"id":"st-1217","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"no victim-blaming","relearn":"Freezing is a normal response and never makes the harm your fault.","hook":"Lensy: if someone froze instead of shouting, did they do wrong?","prompt":"What do you think?","options":["No, freezing is normal","Not at all","It's a body response"],"affirm":"Freezing is normal under threat; it's never your fault."},
  {"id":"st-1218","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"rights","relearn":"Harassment is a choice, not 'nature' — people can control their behaviour.","hook":"Lensy: 'boys can't help it' — true, or an excuse?","prompt":"What do you think?","options":["An excuse","People can choose","It insults boys too"],"affirm":"Everyone can control their behaviour; harassment is a choice."},
  {"id":"st-1219","cat":"gbv-and-rights","type":"reflect","persona":"Counsellor","source":"rights / help","relearn":"Believing someone and saying 'it's not your fault' is real support.","hook":"Lensy: what would you most want to hear if you were harmed?","prompt":"What do you think?","options":["'I believe you'","'It's not your fault'","'I'm here'"],"affirm":"Being believed and reassured is powerful, real support."},
  {"id":"st-1220","cat":"gbv-and-rights","type":"reflect","persona":"any","source":"rights","relearn":"When bystanders treat everyone's safety as their business, harassment shrinks.","hook":"Lensy: whose business is it when someone's being harassed nearby?","prompt":"What do you think?","options":["Everyone's","Mine too","All of ours"],"affirm":"Everyone's safety is everyone's business — that's the shift."},
  {"id":"st-1221","cat":"gbv-and-rights","type":"role-play","persona":"Riya","source":"rights","relearn":"Naming it as not okay is a real, valid response to harassment.","hook":"On the bus a man keeps 'accidentally' leaning on you. What do you say?","setup":"He won't stop pressing against you and you feel cornered.","yourLine":[{"text":"\"Please move back, you're too close.\"","best":true},{"text":"Say nothing and just shrink into the corner."}]},
  {"id":"st-1222","cat":"gbv-and-rights","type":"role-play","persona":"any","source":"rights","relearn":"You can refuse touch clearly; your no doesn't need an apology.","hook":"A relative insists on a hug you don't want at a function.","setup":"They reach out; you'd rather not be touched.","yourLine":[{"text":"\"I'd rather not hug — a wave is fine.\"","best":true},{"text":"Hug them anyway so no one feels awkward."}]},
  {"id":"st-1223","cat":"gbv-and-rights","type":"role-play","persona":"Riya","source":"rights / help","relearn":"Telling a trusted adult is the right move, not snitching.","hook":"A senior keeps sending you creepy messages. You tell whom?","setup":"The messages won't stop and they make you anxious.","yourLine":[{"text":"\"I'm telling a teacher I trust about this.\"","best":true},{"text":"Delete them and hope he just gives up."}]},
  {"id":"st-1224","cat":"gbv-and-rights","type":"role-play","persona":"Veer","source":"ally","relearn":"An ally refuses to join and names that it's not okay.","hook":"Your friends start catcalling a girl walking past. You say?","setup":"They look to you to join the 'fun'.","yourLine":[{"text":"\"Not cool — leave her alone, yeah?\"","best":true},{"text":"Laugh along so they don't turn on you."}]},
  {"id":"st-1225","cat":"gbv-and-rights","type":"role-play","persona":"any","source":"rights","relearn":"You're allowed to set a clear boundary about your own body.","hook":"Someone keeps touching your hair without asking. You respond?","setup":"It's happened a few times now and you dislike it.","yourLine":[{"text":"\"Please don't touch my hair, I don't like it.\"","best":true},{"text":"Pull away quietly and let it keep happening."}]},
  {"id":"st-1226","cat":"gbv-and-rights","type":"role-play","persona":"any","source":"no victim-blaming","relearn":"Naming the harasser's behaviour keeps the blame where it belongs.","hook":"A friend says a harassed classmate 'asked for it'. You answer?","setup":"They're blaming the girl for what was done to her.","yourLine":[{"text":"\"She didn't ask for anything — he chose to do it.\"","best":true},{"text":"Shrug; it's easier not to argue with them."}]},
  {"id":"st-1227","cat":"gbv-and-rights","type":"role-play","persona":"Counsellor","source":"rights / help","relearn":"Centring the person harmed and naming help is the supportive move.","hook":"A younger student tells you a teacher made them uneasy. You say?","setup":"They're scared and unsure if it 'counts'.","yourLine":[{"text":"\"That wasn't okay. Let's tell a trusted adult together.\"","best":true},{"text":"\"Maybe you misread it — just forget about it.\""}]},
  {"id":"st-1228","cat":"gbv-and-rights","type":"role-play","persona":"any","source":"rights","relearn":"You can refuse pressure for photos; no is a full answer online too.","hook":"Someone online keeps pressuring you for private photos.","setup":"They say 'if you liked me you would'.","yourLine":[{"text":"\"No. Asking again won't change my answer.\"","best":true},{"text":"Send one just to make them stop bothering you."}]},
  {"id":"st-1229","cat":"gbv-and-rights","type":"branch","persona":"Riya","source":"rights / help","relearn":"Naming harassment and telling an adult is your right and stops harm.","hook":"A man keeps following and commenting on the street. Safest move?","options":[{"text":"Step into a shop and ask staff for help","consequence":"You reach safety and bring others in.","best":true},{"text":"Turn and shout at him to back off","consequence":"Confronting a stranger alone can escalate."},{"text":"Say nothing and hope he stops","consequence":"Silence leaves you alone with the harm."}],"debrief":"Reach a safe place and tell someone."},
  {"id":"st-1230","cat":"gbv-and-rights","type":"branch","persona":"any","source":"rights","relearn":"You have the right to refuse and get help; you owe a harasser nothing.","hook":"A shopkeeper keeps making sexual jokes at you. Best?","options":[{"text":"Tell a trusted adult and don't go alone","consequence":"You get backup, not exposure.","best":true},{"text":"Laugh it off so it's no big deal","consequence":"Laughing along can read as okay."},{"text":"Argue it out with him there","consequence":"Arguing alone can leave you exposed."}],"debrief":"Refusing and getting help are your rights."},
  {"id":"st-1231","cat":"gbv-and-rights","type":"branch","persona":"any","source":"rights / help","relearn":"Reporting online harassment is your right; keep proof and tell an adult.","hook":"Someone threatens to share your photos unless you obey. Best?","options":[{"text":"Don't comply; keep the messages, tell an adult","consequence":"You keep proof and get help.","best":true},{"text":"Do what they ask so they delete it","consequence":"Giving in rarely ends the threat."},{"text":"Block and tell no one","consequence":"Blocking alone leaves the threat on you."}],"debrief":"Threats are abuse — keep proof, bring an adult in."},
  {"id":"st-1232","cat":"gbv-and-rights","type":"branch","persona":"Veer","source":"ally","relearn":"You can refuse to join harassment even when it's your own friends doing it.","hook":"Your group gangs up on a quieter boy with 'gay' jokes. You?","options":[{"text":"Refuse to join and change the subject","consequence":"You break the harmful pull.","best":true},{"text":"Join in a little so you fit in","consequence":"Joining makes you part of the harm."},{"text":"Stay silent and let it run","consequence":"Silence tells them cruelty is fine."}],"debrief":"Refusing to join shifts the group's tone."},
  {"id":"st-1233","cat":"gbv-and-rights","type":"branch","persona":"any","source":"rights","relearn":"Your discomfort is enough reason to leave; no justifying needed.","hook":"A cousin keeps cornering you for 'private chats' you dislike. Best?","options":[{"text":"Leave the room and tell a parent you trust","consequence":"You get out, not alone with it.","best":true},{"text":"Stay to avoid seeming rude","consequence":"Politeness leaves you cornered."},{"text":"Hint vaguely and hope they notice","consequence":"Vague hints get ignored."}],"debrief":"Your discomfort is reason enough — leave and tell."},
  {"id":"st-1234","cat":"gbv-and-rights","type":"branch","persona":"any","source":"no victim-blaming","relearn":"Support centres the person harmed; blame stays with the harasser.","hook":"A classmate is harassed and others whisper it's her fault. You?","options":[{"text":"Tell her it wasn't her fault; sit with her","consequence":"She feels supported, not blamed.","best":true},{"text":"Join the whispers to learn more","consequence":"Gossip adds to the harm and isolates her."},{"text":"Avoid her so it isn't awkward","consequence":"Avoiding her leaves her alone."}],"debrief":"Centre the person harmed — 'it's not your fault'."},
  {"id":"st-1235","cat":"gbv-and-rights","type":"branch","persona":"Counsellor","source":"rights / help","relearn":"Serious harm should reach a trusted adult, not just be kept secret.","hook":"A friend says she was groped but begs you to tell no one. Best?","options":[{"text":"Believe her; gently help her reach a trusted adult","consequence":"She's believed and gets help.","best":true},{"text":"Promise to keep it secret forever","consequence":"Secrecy can leave harm unaddressed."},{"text":"Tell the class so they're warned","consequence":"Broadcasting strips her dignity."}],"debrief":"Believe her, on her terms, route harm to help."},
  {"id":"st-1236","cat":"gbv-and-rights","type":"branch","persona":"any","source":"rights","relearn":"Everyone has the right to refuse; you can help without confronting danger.","hook":"On a train a girl looks trapped beside a leering man. Safe move?","options":[{"text":"Stand near and ask 'is this seat free for you?'","consequence":"You give her an out, no escalation.","best":true},{"text":"Grab the man and pull him away","consequence":"Confronting risks escalation."},{"text":"Assume she'll sort it herself","consequence":"Looking away leaves her alone."}],"debrief":"A safe, public move helps without confronting danger."},
  {"id":"st-1237","cat":"gbv-and-rights","type":"spot","persona":"any","source":"no victim-blaming","relearn":"Harassment is never the target's fault; blame belongs to the harasser.","hook":"Spot the two victim-blaming lines (the red flags) people say.","scene":[{"id":"a","text":"\"It wasn't your fault.\"","trick":false},{"id":"b","text":"\"Why were you out so late, though?\"","trick":true},{"id":"c","text":"\"You have the right to feel safe.\"","trick":false},{"id":"d","text":"\"Maybe your clothes gave him ideas.\"","trick":true},{"id":"e","text":"\"I believe you.\"","trick":false}],"why":"Both red flags blame the target for what the harasser chose to do."},
  {"id":"st-1238","cat":"gbv-and-rights","type":"spot","persona":"any","source":"definition","relearn":"Unwanted, repeated or following behaviour is harassment; welcome contact isn't.","hook":"Spot the two lines that are actually harassment.","scene":[{"id":"a","text":"A friend waves back happily","trick":false},{"id":"b","text":"He follows her despite her quick pace","trick":true},{"id":"c","text":"They share a planned hug","trick":false},{"id":"d","text":"He keeps commenting on her body after a no","trick":true},{"id":"e","text":"Two classmates laugh at a joke","trick":false}],"why":"Following after discomfort and commenting after a no are both harassment."},
  {"id":"st-1239","cat":"gbv-and-rights","type":"spot","persona":"Veer","source":"accountability","relearn":"Harassment is a choice; 'nature' and 'jokes' are excuses, not reasons.","hook":"Spot the two excuses for harassment (the red flags).","scene":[{"id":"a","text":"\"He chose to do it.\"","trick":false},{"id":"b","text":"\"Boys just can't help it.\"","trick":true},{"id":"c","text":"\"A no has to be respected.\"","trick":false},{"id":"d","text":"\"It was only a joke, relax.\"","trick":true},{"id":"e","text":"\"Everyone deserves respect.\"","trick":false}],"why":"'Can't help it' and 'only a joke' excuse a choice the harasser made."},
  {"id":"st-1240","cat":"gbv-and-rights","type":"spot","persona":"any","source":"rights","relearn":"Everyone has the right to safety and to refuse touch; myths deny it.","hook":"Spot the two myths that deny someone's rights.","scene":[{"id":"a","text":"\"You can say no to unwanted touch.\"","trick":false},{"id":"b","text":"\"Boys can't really be harassed.\"","trick":true},{"id":"c","text":"\"Reporting is your right.\"","trick":false},{"id":"d","text":"\"Late out means you gave up your rights.\"","trick":true},{"id":"e","text":"\"Everyone deserves to feel safe.\"","trick":false}],"why":"Both myths wrongly strip someone of rights they actually hold."},
  {"id":"st-1241","cat":"gbv-and-rights","type":"spot","persona":"any","source":"online GBV","relearn":"Online threats, pressure and leaks are harassment; ordinary chat isn't.","hook":"Spot the two online behaviours that are harassment.","scene":[{"id":"a","text":"Sharing a class meme in the group","trick":false},{"id":"b","text":"Threatening to leak her photos","trick":true},{"id":"c","text":"Liking a friend's holiday post","trick":false},{"id":"d","text":"Demanding nudes after she said no","trick":true},{"id":"e","text":"Asking a doubt in the study chat","trick":false}],"why":"Photo threats and pressure after a no are both online harassment."},
  {"id":"st-1242","cat":"gbv-and-rights","type":"spot","persona":"any","source":"forms of GBV","relearn":"Groping, stalking and sexual rumours are all forms of GBV.","hook":"Spot the two scenes that show harassment/GBV.","scene":[{"id":"a","text":"Friends queue calmly for tickets","trick":false},{"id":"b","text":"A hand gropes her in the crowd","trick":true},{"id":"c","text":"A teammate passes the ball","trick":false},{"id":"d","text":"Boys spread sexual rumours about her","trick":true},{"id":"e","text":"Two students revise together","trick":false}],"why":"Groping and spreading sexual rumours are both clear harassment."},
  {"id":"st-1243","cat":"gbv-and-rights","type":"spot","persona":"Counsellor","source":"rights / help","relearn":"Support believes, reassures and routes to help; blame and silence don't.","hook":"Spot the two unhelpful, harmful responses (the red flags).","scene":[{"id":"a","text":"\"I believe you, it wasn't your fault.\"","trick":false},{"id":"b","text":"\"Just keep quiet so there's no drama.\"","trick":true},{"id":"c","text":"\"Let's tell a trusted adult together.\"","trick":false},{"id":"d","text":"\"Are you sure you didn't lead him on?\"","trick":true},{"id":"e","text":"\"I'm here whenever you want to talk.\"","trick":false}],"why":"Silencing and doubting both add to the harm instead of supporting her."},
  {"id":"st-1244","cat":"gbv-and-rights","type":"spot","persona":"any","source":"rights","relearn":"Whose job each thing is: stopping harm is shared; shame is never the target's.","hook":"Spot the two things wrongly put on the target.","scene":[{"id":"a","text":"The harasser owns his choice","trick":false},{"id":"b","text":"The target must carry the shame","trick":true},{"id":"c","text":"Bystanders can help safely","trick":false},{"id":"d","text":"The target alone must fix him","trick":true},{"id":"e","text":"Everyone can report harm","trick":false}],"why":"Carrying shame and fixing the harasser are wrongly dumped on the target."},
  {"id":"st-1260","cat":"safety-first","type":"branch","hook":"On a packed bus, a man keeps pressing against a girl edging away.","options":[{"text":"Say 'bhaiya, give her space' and ask others to shift","consequence":"Calm words and the crowd make him stop, no fight.","outcome":"safe","best":true},{"text":"Grab his collar and shove him","consequence":"Shoving can become a brawl; use your voice."}],"debrief":"In a crowd, your voice plus other riders beats fists.","relearn":"Use your voice and the people around you, not a shove.","persona":"any","source":"safety-first"},
  {"id":"st-1261","cat":"safety-first","type":"branch","hook":"A man on the platform films girls. The train arrives in 30 seconds.","options":[{"text":"Wave down the RPF guard and point him out","consequence":"The guard has the authority and backup you don't.","outcome":"delegate","best":true},{"text":"Snatch his phone and run","consequence":"Grabbing his phone risks a chase; flag the guard."}],"debrief":"On a platform there's almost always staff to delegate to.","relearn":"Get the guard who can act, not the phone.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1262","cat":"safety-first","type":"branch","hook":"In an auto, the driver keeps making comments and won't stop.","options":[{"text":"Ask him to halt at the next busy shop, get out, book another","consequence":"A crowded spot and a new ride get you out safely.","outcome":"safe","best":true},{"text":"Argue with him while he keeps driving","consequence":"Arguing in a moving auto traps you; get out."}],"debrief":"Reach a public spot; don't argue with the one driving.","relearn":"Exit at a busy place; don't argue with a moving driver.","persona":"any","source":"safety-first"},
  {"id":"st-1263","cat":"safety-first","type":"branch","hook":"Three older boys corner a classmate near the empty stairwell.","options":[{"text":"Don't go in alone; run and bring a teacher","consequence":"A teacher and numbers change the scene safely.","outcome":"delegate","best":true},{"text":"Walk in alone to take them all on","consequence":"One against three is danger; bring a teacher."}],"debrief":"Outnumbered means delegate, never confront alone.","relearn":"When outnumbered, bring an adult, don't go in alone.","persona":"Riya","source":"safety-first / delegate"},
  {"id":"st-1264","cat":"safety-first","type":"branch","hook":"A man following a girl looks drunk and angry, swaying as he shouts.","options":[{"text":"Step into a shop with her, ask the owner to call 112","consequence":"A safe doorway and help keep you both out of reach.","outcome":"safe","best":true},{"text":"Block his path and tell him off","consequence":"Confronting an aggressive drunk man is danger."}],"debrief":"For someone unpredictable, distance and 112 beat confrontation.","relearn":"With an aggressive person, get safe and call 112.","persona":"any","source":"safety-first / ERSS"},
  {"id":"st-1265","cat":"safety-first","type":"branch","hook":"You want to help but you're the only one around and unsure.","options":[{"text":"Do one small safe act: stand near her","consequence":"Even your presence can make a harasser back off.","outcome":"upstander","best":true},{"text":"Decide you can't fix it all, so do nothing","consequence":"A small safe act beats nothing; stand near her."}],"debrief":"You don't need a grand plan; one safe step is real help.","relearn":"Any small, safe action beats freezing and doing nothing.","persona":"any","source":"safety-first"},
  {"id":"st-1266","cat":"safety-first","type":"branch","hook":"In the metro a man won't stop inching toward a girl.","options":[{"text":"Press the passenger help button / alert the attendant","consequence":"The metro's built-in help reaches staff fast.","outcome":"delegate","best":true},{"text":"Threaten to beat him at the next stop","consequence":"Threats can escalate; use the help button."}],"debrief":"Use the system's safety tools before any threat.","relearn":"Use the help button for staff; don't make threats.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1267","cat":"safety-first","type":"branch","hook":"A harasser sees you noticing and steps toward you, fists clenched.","options":[{"text":"Back toward people and call for the guard","consequence":"Moving to a crowd and a guard keep you from harm.","outcome":"safe","best":true},{"text":"Stand your ground and dare him","consequence":"Daring an angry person is danger; move to people."}],"debrief":"If the danger turns on you, get safe, don't win.","relearn":"If it turns on you, move to people and call a guard.","persona":"any","source":"safety-first"},
  {"id":"st-1268","cat":"safety-first","type":"branch","hook":"You filmed harassment safely. The harasser has now run off.","options":[{"text":"Give the clip to the girl to decide what to do","consequence":"It's her evidence and her choice; you respect her lead.","outcome":"support","best":true},{"text":"Post it online to expose him","consequence":"Posting can expose her too; hand her the clip."}],"debrief":"Document is only-if-safe and goes to the person, never a feed.","relearn":"Give the footage to the target; never post it online.","persona":"Veer","source":"safety-first / document"},
  {"id":"st-1269","cat":"safety-first","type":"branch","hook":"On a lonely lane at night, a man trails a girl ahead of you.","options":[{"text":"Catch up so she isn't alone, walk to the lit road","consequence":"Company and a busy road remove his chance.","outcome":"safe","best":true},{"text":"Sprint ahead to confront him in the dark","consequence":"A dark lane is the worst place to confront."}],"debrief":"Move toward light and company; don't fight in an isolated spot.","relearn":"Walk together to a busy, lit place; don't confront in the dark.","persona":"any","source":"safety-first"},
  {"id":"st-1270","cat":"safety-first","type":"branch","hook":"In the lift, a man keeps 'accidentally' brushing a girl.","options":[{"text":"Step between them and get out at the next floor","consequence":"A block plus an early exit ends it, no clash.","outcome":"safe","best":true},{"text":"Start shouting and swinging in the lift","consequence":"A fight in a sealed lift traps you; block and exit."}],"debrief":"In a tight, closed space, make distance and exit early.","relearn":"In a lift, block and exit early; don't fight in a sealed box.","persona":"any","source":"safety-first"},
  {"id":"st-1271","cat":"safety-first","type":"branch","hook":"At a festival, a girl signals she's groped but you can't see who.","options":[{"text":"Move her to you and find the police booth","consequence":"Pulling her out and the booth handle it safely.","outcome":"delegate","best":true},{"text":"Start grabbing strangers you suspect","consequence":"Grabbing random people is risky; use the booth."}],"debrief":"Can't ID the harasser? Center the target, get official help.","relearn":"Move the target to safety and reach the police booth.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1272","cat":"safety-first","type":"branch","hook":"A man in the ATM queue leers and steps close to a girl.","options":[{"text":"Ask the door guard to make him wait outside","consequence":"The ATM guard can enforce space calmly.","outcome":"delegate","best":true},{"text":"Push him out of the booth yourself","consequence":"Pushing can spark a scuffle; the guard handles it."}],"debrief":"Wherever there's a guard on duty, that's your first safe move.","relearn":"Ask the on-duty guard to act; don't push him yourself.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1273","cat":"safety-first","type":"branch","hook":"You stepped in, but now the harasser's two friends show up.","options":[{"text":"Disengage, move her away, and call 112","consequence":"Outnumbered, you retreat to safety and get help.","outcome":"safe","best":true},{"text":"Keep arguing now it's three against you","consequence":"Three against one is danger; disengage, call 112."}],"debrief":"When odds turn against you, step back and call for help.","relearn":"If they outnumber you, disengage and call 112.","persona":"any","source":"safety-first / ERSS"},
  {"id":"st-1274","cat":"safety-first","type":"branch","hook":"On the bus a girl is harassed and the conductor is right there.","options":[{"text":"Tell the conductor: 'this man is troubling her, please stop'","consequence":"A specific ask gets a real, safe response.","outcome":"delegate","best":true},{"text":"Just hope the conductor notices himself","consequence":"Hoping rarely works; ask the conductor directly."}],"debrief":"Delegate with a specific, direct ask to the person in charge.","relearn":"Ask the person in charge directly; don't just hope.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1275","cat":"safety-first","type":"branch","hook":"A creepy uncle keeps cornering your cousin at a family wedding.","options":[{"text":"Stay beside her and bring a trusted older relative","consequence":"Your presence plus a trusted adult shifts it safely.","outcome":"safe","best":true},{"text":"Pretend you didn't see because he's 'family'","consequence":"Family is no excuse; stay near, bring an adult."}],"debrief":"Harassment by a relative still gets a safe response.","relearn":"Stay near and bring a trusted adult; family is no excuse.","persona":"any","source":"safety-first"},
  {"id":"st-1276","cat":"safety-first","type":"branch","hook":"You froze once, then see the same man bother her again.","options":[{"text":"This time sit beside her and call the warden over","consequence":"A second chance used well; one safe act is progress.","outcome":"upstander","best":true},{"text":"Decide you froze once so you always will","consequence":"Freezing once doesn't define you; act next time."}],"debrief":"Freezing once is normal; next time, choose a small safe move.","relearn":"After freezing once, you can choose a safe action next time.","persona":"Riya","source":"safety-first"},
  {"id":"st-1277","cat":"safety-first","type":"branch","hook":"A girl is being followed but you're not sure it's harassment.","options":[{"text":"Ask quietly 'is he bothering you? want to walk with me?'","consequence":"A gentle check lets her tell you and gets her support.","outcome":"support","best":true},{"text":"Confront the man before checking with her","consequence":"Confronting first can backfire; check with her."}],"debrief":"When unsure, a quiet check-in guides a safe next step.","relearn":"Quietly check with the person first; don't confront blind.","persona":"any","source":"safety-first"},
  {"id":"st-1278","cat":"safety-first","type":"branch","hook":"In the shared cab, a co-passenger keeps touching the girl.","options":[{"text":"Ask the driver to stop somewhere public so she can move","consequence":"A public stop gives her a safe way out.","outcome":"safe","best":true},{"text":"Lunge across the seats to hit him","consequence":"A fight in a moving cab is dangerous."}],"debrief":"In a moving vehicle, engineer a safe public stop.","relearn":"Get a public stop so she can move; don't fight in a cab.","persona":"any","source":"safety-first"},
  {"id":"st-1279","cat":"safety-first","type":"branch","hook":"A stranger online threatens to leak a classmate's photos.","options":[{"text":"Don't reply or pay; save proof, tell a trusted adult","consequence":"Not engaging plus reporting takes its power away.","outcome":"safe","best":true},{"text":"Message him back to threaten him","consequence":"Threatening a blackmailer can escalate."}],"debrief":"Online threats: don't engage, save proof, report.","relearn":"Don't reply or pay; save proof and tell a trusted adult.","persona":"any","source":"safety-first"},
  {"id":"st-1280","cat":"safety-first","type":"branch","hook":"At coaching, a senior blocks the door when a girl leaves.","options":[{"text":"Walk out as a group and tell the teacher","consequence":"Leaving together and informing staff removes his chance.","outcome":"delegate","best":true},{"text":"Square up to the senior alone","consequence":"Squaring up alone is risky; leave as a group."}],"debrief":"Numbers plus staff beat a solo standoff.","relearn":"Leave as a group and tell staff; don't square up alone.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1281","cat":"safety-first","type":"branch","hook":"A man on a bike circles back to comment at the school gate.","options":[{"text":"Note the bike number safely and tell the gate guard","consequence":"Safe documenting plus the guard, no chase.","outcome":"document","best":true},{"text":"Chase the bike on foot","consequence":"Chasing a bike is dangerous; note it, tell the guard."}],"debrief":"Document safely from a distance and hand it over; never chase.","relearn":"Note details from safety and tell the guard; don't chase.","persona":"any","source":"safety-first / document"},
  {"id":"st-1282","cat":"safety-first","type":"branch","hook":"Your own friend starts groping a girl as a 'joke' on the bus.","options":[{"text":"Tell your friend firmly to stop, move between them","consequence":"Refusing to join and blocking him ends it safely.","outcome":"upstander","best":true},{"text":"Laugh along so you don't seem uncool","consequence":"Laughing makes you part of it; tell him to stop."}],"debrief":"You can stand up even when the harasser is your friend.","relearn":"Refuse to join and tell your friend to stop; don't laugh along.","persona":"Veer","source":"safety-first"},
  {"id":"st-1283","cat":"safety-first","type":"branch","hook":"A drunk man at the bus stop grabs at a girl waiting alone.","options":[{"text":"Stand with her, wave others over, call 112","consequence":"Company plus help protect her from someone unpredictable.","outcome":"safe","best":true},{"text":"Try to pull him away by yourself","consequence":"Grappling a drunk man is danger; get people, call 112."}],"debrief":"For an intoxicated, grabbing person, get numbers and call 112.","relearn":"Gather people and call 112; don't grapple a drunk man.","persona":"any","source":"safety-first / ERSS"},
  {"id":"st-1284","cat":"safety-first","type":"branch","hook":"You want proof, but the harasser is staring straight at you.","options":[{"text":"Don't record now; get the girl away to safety","consequence":"Her safety comes before footage.","outcome":"safe","best":true},{"text":"Film him in his face to provoke him","consequence":"Filming to provoke invites danger; get her safe."}],"debrief":"Document is only-if-safe; if filming would provoke, skip it.","relearn":"Skip filming if it's risky; get the person to safety first.","persona":"any","source":"safety-first / document"},
  {"id":"st-1285","cat":"safety-first","type":"branch","hook":"A girl on the train looks frozen as a man leans over her seat.","options":[{"text":"Sit beside her and ask 'is this seat free?'","consequence":"A casual interruption breaks his focus, gives her an ally.","outcome":"safe","best":true},{"text":"Yell across the coach to fight him","consequence":"Yelling a challenge can escalate."}],"debrief":"A calm distraction interrupts the harasser without a fight.","relearn":"Use a casual distraction; don't yell a challenge.","persona":"any","source":"safety-first / distract"},
  {"id":"st-1286","cat":"safety-first","type":"branch","hook":"Boys pass around a girl's photo, laughing, near the canteen.","options":[{"text":"Refuse to look or share, say 'not funny', tell a teacher","consequence":"Not joining plus reporting shuts the spread down.","outcome":"upstander","best":true},{"text":"Take a copy to 'see the fuss'","consequence":"Taking a copy spreads it further; refuse and report."}],"debrief":"Don't join the spread; refuse, name it wrong, and report.","relearn":"Don't share or look; refuse and tell a teacher.","persona":"any","source":"safety-first"},
  {"id":"st-1287","cat":"safety-first","type":"branch","hook":"A harasser suddenly seems to reach for something in his bag.","options":[{"text":"Pull back, get away, and call 112 now","consequence":"You don't gamble on what he's reaching for.","outcome":"safe","best":true},{"text":"Step closer to see what he's grabbing","consequence":"Stepping into possible danger is wrong; retreat, call 112."}],"debrief":"If a scene suddenly feels dangerous, retreat and call 112.","relearn":"If it feels suddenly dangerous, get away and call 112.","persona":"any","source":"safety-first / ERSS"},
  {"id":"st-1288","cat":"safety-first","type":"branch","hook":"In the library a man keeps sitting too close to the same girl.","options":[{"text":"Quietly tell the librarian to move seats or watch","consequence":"Staff can handle a repeat pattern calmly.","outcome":"delegate","best":true},{"text":"Confront him loudly in the silent library","consequence":"A loud confrontation can backfire; tell the librarian."}],"debrief":"For a repeating pattern, looping in staff is the safe move.","relearn":"Tell staff about a repeat pattern; don't confront loudly.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1289","cat":"safety-first","type":"branch","hook":"You're small and the harasser is big; you still want to help.","options":[{"text":"Don't match his size; alert the nearby shopkeeper","consequence":"You bring in help instead of a fight you can't win.","outcome":"delegate","best":true},{"text":"Fight him to prove size doesn't matter","consequence":"A fight you'd lose is danger; alert the shopkeeper."}],"debrief":"Being outmatched means delegate; helping isn't about strength.","relearn":"When outmatched, alert someone who can step in; don't fight.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1290","cat":"safety-first","type":"branch","hook":"A man pushes a lift on a lone girl who clearly doesn't want it.","options":[{"text":"Stand with her and say 'she's with us, we have a ride'","consequence":"Joining her and a firm line ends the pressure.","outcome":"safe","best":true},{"text":"Ignore it since 'he's only offering'","consequence":"Unwanted pressure isn't harmless; stand with her."}],"debrief":"Persistent unwanted 'help' is pressure; back the person safely.","relearn":"Stand with her and give a firm no; don't dismiss pressure.","persona":"any","source":"safety-first"},
  {"id":"st-1291","cat":"safety-first","type":"sort","hook":"Sort each move: a safe way to help, or a risky one?","items":[{"id":"a","text":"Casually distracting so she can step away"},{"id":"b","text":"Punching the harasser"},{"id":"c","text":"Calling 112 or getting a guard"},{"id":"d","text":"Threatening to 'finish' him later"},{"id":"e","text":"Standing close so she isn't alone"},{"id":"f","text":"Chasing him down a dark lane"}],"bins":[{"id":"safe","label":"Safe move","valence":"pos"},{"id":"risky","label":"Risky move","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Distraction, help and presence are safe; hitting, threats and chasing are risky.","persona":"any","source":"safety-first"},
  {"id":"st-1292","cat":"safety-first","type":"sort","hook":"Sort: does this put safety first, or ignore it?","items":[{"id":"a","text":"Asking 'can I help safely?' first"},{"id":"b","text":"Rushing in without looking"},{"id":"c","text":"Moving the target toward a crowd"},{"id":"d","text":"Going in alone against a group"},{"id":"e","text":"Checking where the exit and guard are"},{"id":"f","text":"Cornering the harasser yourself"}],"bins":[{"id":"safe","label":"Safety first","valence":"pos"},{"id":"no","label":"Ignores safety","valence":"neg"}],"key":{"a":"safe","b":"no","c":"safe","d":"no","e":"safe","f":"no"},"relearn":"Safety-first means assessing, moving to people, checking exits, not impulse or solo risk.","persona":"any","source":"safety-first"},
  {"id":"st-1293","cat":"safety-first","type":"sort","hook":"Sort by how dangerous the harasser is right now.","items":[{"id":"a","text":"Aggressive and drunk: keep distance"},{"id":"b","text":"Calm, teacher right there: speak up"},{"id":"c","text":"Swinging fists: step back, get help"},{"id":"d","text":"One comment, staff nearby: name it"},{"id":"e","text":"Reaching into a bag: retreat"},{"id":"f","text":"Quiet, guard at the door: alert guard"}],"bins":[{"id":"danger","label":"Dangerous: get help","valence":"neg"},{"id":"okay","label":"Clearly safe: speak up","valence":"pos"}],"key":{"a":"danger","b":"okay","c":"danger","d":"okay","e":"danger","f":"okay"},"relearn":"Read the danger first: get help when risky, speak up only when clearly safe.","persona":"any","source":"safety-first"},
  {"id":"st-1294","cat":"safety-first","type":"sort","hook":"Sort: 'help without becoming a second victim', or not?","items":[{"id":"a","text":"Safe distance while you call help"},{"id":"b","text":"Jumping into a fight"},{"id":"c","text":"Bringing others so you're not alone"},{"id":"d","text":"Standing between two angry men"},{"id":"e","text":"Getting the target to safety first"},{"id":"f","text":"Grabbing a weapon to match him"}],"bins":[{"id":"yes","label":"Stays safe","valence":"pos"},{"id":"no","label":"Second victim","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"Distance, numbers and safe spots let you help; jumping in or arming up don't.","persona":"any","source":"safety-first"},
  {"id":"st-1295","cat":"safety-first","type":"sort","hook":"Sort: speak up safely, careful (assess), or never?","items":[{"id":"a","text":"Say 'not okay' with a teacher there"},{"id":"b","text":"Walk in alone against three boys"},{"id":"c","text":"He's aggressive: call 112 instead"},{"id":"d","text":"Hit the harasser"},{"id":"e","text":"Ask the bus 'can someone help her?'"},{"id":"f","text":"Chase him into a dark alley"}],"bins":[{"id":"speak","label":"Speak up (safe)","valence":"tell"},{"id":"careful","label":"Careful: assess","valence":"uhoh"},{"id":"never","label":"Never (danger)","valence":"neg"}],"key":{"a":"speak","b":"never","c":"careful","d":"never","e":"speak","f":"never"},"relearn":"Speak up when clearly safe; assess when unsure; never confront or chase into danger.","persona":"any","source":"safety-first"},
  {"id":"st-1296","cat":"safety-first","type":"sort","hook":"Sort each first question: helpful mindset or not?","items":[{"id":"a","text":"'Can I help safely here?'"},{"id":"b","text":"'How do I look the bravest?'"},{"id":"c","text":"'Who nearby can help me?'"},{"id":"d","text":"'How do I win this fight?'"},{"id":"e","text":"'What's the smallest safe thing?'"},{"id":"f","text":"'How do I scare him most?'"}],"bins":[{"id":"good","label":"Safe mindset","valence":"pos"},{"id":"bad","label":"Risky mindset","valence":"neg"}],"key":{"a":"good","b":"bad","c":"good","d":"bad","e":"good","f":"bad"},"relearn":"Safe questions ask how to help safely and who can help, not how to win.","persona":"any","source":"safety-first"},
  {"id":"st-1297","cat":"safety-first","type":"sort","hook":"Sort: keeps YOU safe while helping, or risks you?","items":[{"id":"a","text":"Staying near people and lights"},{"id":"b","text":"Following him into an empty lot"},{"id":"c","text":"Phone ready to call 112"},{"id":"d","text":"Letting him provoke you to swing"},{"id":"e","text":"Knowing where the guard is"},{"id":"f","text":"Cornering yourself with him in a lift"}],"bins":[{"id":"safe","label":"Keeps you safe","valence":"pos"},{"id":"unsafe","label":"Puts you at risk","valence":"neg"}],"key":{"a":"safe","b":"unsafe","c":"safe","d":"unsafe","e":"safe","f":"unsafe"},"relearn":"Stay near people, keep an exit and phone ready; don't get cornered or provoked.","persona":"any","source":"safety-first"},
  {"id":"st-1298","cat":"safety-first","type":"sort","hook":"Sort each into 'do now' (safe) or 'don't' (risky).","items":[{"id":"a","text":"Get the target to a busy place"},{"id":"b","text":"Snatch and smash his phone"},{"id":"c","text":"Quietly note the bus number"},{"id":"d","text":"Chase a fleeing harasser through traffic"},{"id":"e","text":"Ask a shopkeeper to call for help"},{"id":"f","text":"Block the exit and trap him"}],"bins":[{"id":"do","label":"Do now (safe)","valence":"pos"},{"id":"dont","label":"Don't (risky)","valence":"neg"}],"key":{"a":"do","b":"dont","c":"do","d":"dont","e":"do","f":"dont"},"relearn":"Move the target to safety, note details, get help; don't snatch, chase, or trap.","persona":"any","source":"safety-first"},
  {"id":"st-1299","cat":"safety-first","type":"reflect","hook":"Lensy: the bravest move isn't always the loudest. What feels true?","prompt":"What do you think?","options":["The safe move is brave too","Quiet help still counts","Brave can be calm"],"affirm":"Quiet, safe help is real bravery; you needn't be loud to be brave.","relearn":"The bravest move is often the safe, quiet one.","persona":"any","source":"safety-first"},
  {"id":"st-1300","cat":"safety-first","type":"reflect","hook":"Lensy: knowing you can get others to help, is it less scary?","prompt":"How does it feel?","options":["Less scary","I'm not alone in it","I could do that"],"affirm":"You never face it alone; getting others is a strong, safe choice.","relearn":"You can always bring others in; you don't face it alone.","persona":"any","source":"safety-first"},
  {"id":"st-1301","cat":"safety-first","type":"reflect","hook":"Lensy: 'put your own safety first' isn't selfish here. Right?","prompt":"What do you think?","options":["Yes, it makes sense","Safe me helps more","It's not selfish"],"affirm":"Staying safe is what lets you keep helping; it isn't selfish.","relearn":"Keeping yourself safe is what makes helping possible.","persona":"any","source":"safety-first"},
  {"id":"st-1302","cat":"safety-first","type":"reflect","hook":"Lensy: even just standing near someone can help. Felt that?","prompt":"What do you think?","options":["Presence helps","I'd feel safer too","Small things matter"],"affirm":"Just being near someone can make a harasser back off; presence is power.","relearn":"Even your presence is a small, safe action that helps.","persona":"any","source":"safety-first"},
  {"id":"st-1303","cat":"safety-first","type":"reflect","hook":"Lensy: freezing once doesn't decide who you are. Agree?","prompt":"How do you see it?","options":["I can choose next time","Freezing is normal","One moment isn't me"],"affirm":"Freezing is normal; next time you can choose one safe move.","relearn":"Freezing once is normal; you can choose a safe action next time.","persona":"Riya","source":"safety-first"},
  {"id":"st-1304","cat":"safety-first","type":"reflect","hook":"Lensy: it's not 'be a hero or do nothing'. What do you feel?","prompt":"What do you think?","options":["There's a safe middle","I have real options","Relieved, honestly"],"affirm":"There's always a safe option between hero and nothing; you're never stuck.","relearn":"Safe options free you from 'be a hero or do nothing'.","persona":"any","source":"safety-first"},
  {"id":"st-1305","cat":"safety-first","type":"reflect","hook":"Lensy: checking 'is this safe?' first, wise or weak?","prompt":"What do you think?","options":["Wise, definitely","Smart, not weak","That's the plan"],"affirm":"Pausing to check safety is wisdom, not weakness; it's how you help well.","relearn":"Asking 'can I help safely?' first is wise, not weak.","persona":"any","source":"safety-first"},
  {"id":"st-1306","cat":"safety-first","type":"reflect","hook":"Lensy: getting a guard isn't 'tattling', it's smart. Land?","prompt":"How does that sit?","options":["It's smart","Not tattling at all","I'd do it"],"affirm":"Bringing in help is the strong, safe move, never just tattling.","relearn":"Getting a guard or adult is a smart, safe move, not tattling.","persona":"any","source":"safety-first"},
  {"id":"st-1307","cat":"safety-first","type":"reflect","hook":"Lensy: your safety and the target's both matter. Right?","prompt":"What do you think?","options":["Both matter","Yes, together","Neither alone"],"affirm":"You can protect the person and yourself at once; both matter.","relearn":"You help best when you keep both the target and yourself safe.","persona":"any","source":"safety-first"},
  {"id":"st-1308","cat":"safety-first","type":"reflect","hook":"Lensy: would a plan ready before a scary moment help?","prompt":"What do you think?","options":["Yes, a plan helps","I'd feel readier","Good idea"],"affirm":"Knowing your safe moves ahead makes you readier and calmer.","relearn":"Knowing your safe moves in advance helps you act calmly.","persona":"any","source":"safety-first"},
  {"id":"st-1309","cat":"safety-first","type":"strike-rewrite","hook":"\"If you really want to help, you have to fight the harasser.\"","myth":{"un":"Real help means physically fighting the harasser.","re":"The safest help is usually distraction or getting others.","why":"Fighting can put you in danger and isn't needed to help."},"relearn":"You don't have to fight; safe moves help more.","persona":"any","source":"safety-first"},
  {"id":"st-1310","cat":"safety-first","type":"strike-rewrite","hook":"\"Calling for help means you're a coward.\"","myth":{"un":"Asking for help shows you're weak or scared.","re":"Getting others or calling 112 is a strong, smart choice.","why":"Bringing in help keeps everyone safer than going alone."},"relearn":"Calling for help is strength, not cowardice.","persona":"any","source":"safety-first"},
  {"id":"st-1311","cat":"safety-first","type":"strike-rewrite","hook":"\"A small safe action is useless; only big moves matter.\"","myth":{"un":"Tiny safe acts don't really make a difference.","re":"Even standing near or a quiet distraction can stop harm.","why":"Small safe acts shift the scene and free others to help."},"relearn":"Any small, safe action is better than nothing.","persona":"any","source":"safety-first"},
  {"id":"st-1312","cat":"safety-first","type":"strike-rewrite","hook":"\"If you don't catch the harasser, you've failed the target.\"","myth":{"un":"Helping means catching or punishing the harasser.","re":"Helping means supporting the target and reporting safely.","why":"Centring the person harmed matters more than chasing anyone."},"relearn":"Support the target and report; you needn't catch anyone.","persona":"any","source":"safety-first"},
  {"id":"st-1313","cat":"safety-first","type":"strike-rewrite","hook":"\"Stepping back when it's dangerous means you gave up.\"","myth":{"un":"Backing off from danger means you abandoned the target.","re":"Stepping back to call for help is the safe, responsible move.","why":"You can't help anyone if you become a second victim."},"relearn":"Stepping back to call for help isn't giving up.","persona":"any","source":"safety-first"},
  {"id":"st-1314","cat":"safety-first","type":"strike-rewrite","hook":"\"You should chase a harasser who runs, or he wins.\"","myth":{"un":"If you don't chase the harasser, he 'gets away with it'.","re":"Skip the chase; support the target and report it.","why":"Chasing risks your safety and leaves the target alone."},"relearn":"Don't chase a harasser; support the target and report.","persona":"Veer","source":"safety-first"},
  {"id":"st-1315","cat":"safety-first","type":"strike-rewrite","hook":"\"Putting yourself in harm's way proves you care.\"","myth":{"un":"Risking your own safety is how you show you care.","re":"Helping safely, from a distance or with others, truly helps.","why":"Getting hurt yourself helps no one and stops you helping."},"relearn":"You don't prove care by risking harm; safe help is real help.","persona":"any","source":"safety-first"},
  {"id":"st-1316","cat":"safety-first","type":"role-play","hook":"A man crowds a girl on the bus. Say the safe line that gets her out.","setup":"Give her an easy exit without sparking a fight.","yourLine":[{"text":"There you are! Come sit with me, I saved you a seat.","best":true},{"text":"Oi, what do you think you're doing, you creep?"},{"text":"...you stay quiet and watch."}],"relearn":"A casual distraction gives the target a safe way out.","persona":"any","source":"safety-first / distract"},
  {"id":"st-1317","cat":"safety-first","type":"role-play","hook":"You need the conductor's help. What do you say?","setup":"A vague 'do something' won't work; be specific and direct.","yourLine":[{"text":"Conductor sir, this man is troubling her, please stop and help.","best":true},{"text":"Um, someone should maybe do something?"},{"text":"...you hope he notices on his own."}],"relearn":"Delegate with a clear, specific ask to the person in charge.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1318","cat":"safety-first","type":"role-play","hook":"It's dangerous and a friend wants to charge in. Talk them down.","setup":"Steer your friend away from a risky confrontation.","yourLine":[{"text":"Don't go in alone, let's get the guard and call 112 together.","best":true},{"text":"Yeah, go for it, hit him first!"},{"text":"...you shrug and let them run in."}],"relearn":"Steer toward getting help together, not a solo confrontation.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1319","cat":"safety-first","type":"role-play","hook":"A lone girl is pressured for a lift she doesn't want. Back her.","setup":"Walk over to stand with her and shut the pressure down calmly.","yourLine":[{"text":"She's with us, we've already got a ride, thanks.","best":true},{"text":"Get lost before I make you, understand?"},{"text":"...you look away and keep walking."}],"relearn":"Stand with the person and give a firm, calm no.","persona":"any","source":"safety-first"},
  {"id":"st-1320","cat":"safety-first","type":"role-play","hook":"Your friend gropes a girl 'as a joke'. Say the line that stops him.","setup":"Refuse to join and tell your own friend to stop, firmly.","yourLine":[{"text":"Stop it, that's not a joke, leave her alone, now.","best":true},{"text":"Haha, chill, it's just a bit of fun, right?"},{"text":"...you laugh nervously and say nothing."}],"relearn":"Refuse to join and tell your friend to stop, plainly.","persona":"Veer","source":"safety-first"},
  {"id":"st-1321","cat":"safety-first","type":"role-play","hook":"You can't see the harasser but the girl needs out. What do you say?","setup":"Give her a safe exit and check in without confronting anyone.","yourLine":[{"text":"Come stand here with me, let's get you to the police booth.","best":true},{"text":"Point him out right now so I can grab him!"},{"text":"...you stare around but say nothing to her."}],"relearn":"Center the target: offer a safe exit and route to help.","persona":"any","source":"safety-first"},
  {"id":"st-1322","cat":"safety-first","type":"role-play","hook":"A shopkeeper is your nearest helper. Ask for the right help.","setup":"Step into the shop and ask the owner to call for help.","yourLine":[{"text":"Uncle, please call 112, a man is harassing her outside.","best":true},{"text":"Uncle, lend me a stick so I can go hit him."},{"text":"...you stand in the doorway unsure."}],"relearn":"Ask a bystander to call for help, not to arm you for a fight.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1323","cat":"safety-first","type":"role-play","hook":"You froze last time. This time, say one calm, safe line beside her.","setup":"Sit beside her and signal the warden, no confrontation.","yourLine":[{"text":"Mind if I sit here? I'll call the warden over to help.","best":true},{"text":"I'll beat him up myself this time, watch."},{"text":"...you freeze again and say nothing."}],"relearn":"One calm line beside the person, plus alerting staff, is enough.","persona":"Riya","source":"safety-first"},
  {"id":"st-1324","cat":"safety-first","type":"match","hook":"Match each situation to the safest first move.","pairs":[{"left":"Harasser is drunk and aggressive","right":"Keep distance and call 112"},{"left":"A guard stands right at the door","right":"Quietly alert the guard"},{"left":"You're outnumbered by his friends","right":"Disengage and get help"},{"left":"He's calm and a teacher is near","right":"Calmly name it as wrong"},{"left":"He films from across the platform","right":"Note details, tell staff"}],"relearn":"Match the move to the danger: get help when risky, speak up when safe.","persona":"any","source":"safety-first"},
  {"id":"st-1325","cat":"safety-first","type":"match","hook":"Match each safe action to why it keeps you out of harm.","pairs":[{"left":"Standing near the target","right":"Presence makes a harasser back off"},{"left":"Calling 112","right":"Brings trained help fast"},{"left":"Moving to a busy spot","right":"Witnesses make harm less likely"},{"left":"Getting a guard","right":"Authority handles it, not you"},{"left":"Stepping back if it escalates","right":"You avoid being a second victim"}],"relearn":"Presence, calling help, crowds, authority and retreat all protect you.","persona":"any","source":"safety-first"},
  {"id":"st-1326","cat":"safety-first","type":"match","hook":"Match each risky impulse to its safer swap.","pairs":[{"left":"Chase the harasser who fled","right":"Support the target and report"},{"left":"Punch him to scare him","right":"Distract so she can step away"},{"left":"Confront him alone in the dark","right":"Walk together to a lit road"},{"left":"Snatch and smash his phone","right":"Flag the guard who can act"},{"left":"Trap him in a closed lift","right":"Block and exit at the next floor"}],"relearn":"Swap each risky impulse for support, distract, light, delegate, exit.","persona":"any","source":"safety-first"},
  {"id":"st-1327","cat":"safety-first","type":"match","hook":"Match the place to the helper you'd delegate to there.","pairs":[{"left":"On a city bus","right":"The conductor"},{"left":"On a train platform","right":"The RPF guard"},{"left":"At the school gate","right":"The gate guard"},{"left":"In the library","right":"The librarian"},{"left":"On a street with no staff","right":"Call 112 or a shopkeeper"}],"relearn":"Wherever you are, there's usually someone to delegate to, find them.","persona":"any","source":"safety-first / delegate"},
  {"id":"st-1328","cat":"safety-first","type":"match","hook":"Match each question to where it leads you.","pairs":[{"left":"'Can I help safely?'","right":"Leads to a safe move"},{"left":"'Who nearby can help?'","right":"Leads to delegating"},{"left":"'How do I look brave?'","right":"Leads to needless risk"},{"left":"'How do I win this fight?'","right":"Leads to escalation"},{"left":"'What's the smallest safe act?'","right":"Leads to doing something safe"}],"relearn":"Safe questions ask how to help safely and who can help.","persona":"any","source":"safety-first"},
  {"id":"st-1329","cat":"safety-first","type":"match","hook":"Match each escalation to the safe response.","pairs":[{"left":"He clenches his fists at you","right":"Back to people, call a guard"},{"left":"His friends arrive to back him","right":"Disengage and call 112"},{"left":"He reaches into his bag","right":"Retreat and call for help"},{"left":"He starts shouting threats","right":"Step away, bring help over"},{"left":"He blocks the only exit","right":"Call out loudly to the crowd"}],"relearn":"As danger rises, your moves shift to distance and help.","persona":"any","source":"safety-first"},
  {"id":"st-1330","cat":"safety-first","type":"match","hook":"Match each safe move to a one-line description.","pairs":[{"left":"Distract","right":"Interrupt casually so she can step away"},{"left":"Delegate","right":"Get a guard, adult, or call help"},{"left":"Document","right":"Only if safe, give it to the target"},{"left":"Delay","right":"Check in after: 'are you okay?'"},{"left":"Direct","right":"When safe, calmly name it as wrong"}],"relearn":"Distract, Delegate, Document, Delay, Direct, each a safe move.","persona":"any","source":"safety-first / five-ds"},
  {"id":"st-1331","cat":"safety-first","type":"match","hook":"Match each safety-first idea to its meaning.","pairs":[{"left":"'Can I help safely?'","right":"The first question before action"},{"left":"Help without harm to you","right":"Don't become a second victim"},{"left":"A small safe act","right":"Better than doing nothing"},{"left":"Bring others in","right":"Numbers make helping safer"},{"left":"Step back if it escalates","right":"Disengage and call for help"}],"relearn":"Ask if you can help safely, stay unharmed, act small, bring others.","persona":"any","source":"safety-first"},
  {"id":"st-1332","cat":"safety-first","type":"spot","hook":"Spot the two RISKY moves a 'helper' might make here.","scene":[{"id":"a","text":"She asks the gate guard to step in","trick":false},{"id":"b","text":"He charges in alone to fight a bigger man","trick":true},{"id":"c","text":"She moves the target toward busy shops","trick":false},{"id":"d","text":"He chases the harasser into a dark lane","trick":true},{"id":"e","text":"She keeps her phone ready to call 112","trick":false}],"why":"Charging in alone and chasing into a dark lane put you in danger.","relearn":"Catch the risky moves, fighting alone and chasing.","persona":"any","source":"safety-first"},
  {"id":"st-1333","cat":"safety-first","type":"spot","hook":"Spot the two UNSAFE choices when the harasser looks dangerous.","scene":[{"id":"a","text":"Keep a safe distance and call 112","trick":false},{"id":"b","text":"Step up and shove him back","trick":true},{"id":"c","text":"Get the target to a crowd","trick":false},{"id":"d","text":"Block his only way out","trick":true},{"id":"e","text":"Wave others over","trick":false}],"why":"Shoving a dangerous man and trapping him invite the harm to avoid.","relearn":"Catch the unsafe moves, shoving and trapping.","persona":"any","source":"safety-first"},
  {"id":"st-1334","cat":"safety-first","type":"spot","hook":"Spot the two lines that ignore your own safety.","scene":[{"id":"a","text":"'Let me get the conductor'","trick":false},{"id":"b","text":"'I'll take all three of them myself'","trick":true},{"id":"c","text":"'Stand with me so you're not alone'","trick":false},{"id":"d","text":"'I'll follow him home to confront him'","trick":true},{"id":"e","text":"'Let's move to where there are people'","trick":false}],"why":"Taking on three alone and following him home throw away your safety.","relearn":"Catch the lines that ignore your safety.","persona":"any","source":"safety-first"},
  {"id":"st-1335","cat":"safety-first","type":"spot","hook":"Spot the two moves that turn a helper into a second victim.","scene":[{"id":"a","text":"Calling for help from a safe distance","trick":false},{"id":"b","text":"Jumping into the middle of the brawl","trick":true},{"id":"c","text":"Getting the target to safety first","trick":false},{"id":"d","text":"Grabbing a weapon to match him","trick":true},{"id":"e","text":"Bringing others so you're not alone","trick":false}],"why":"Joining the brawl and arming yourself make you the next one hurt.","relearn":"Catch the moves that make you a second victim.","persona":"any","source":"safety-first"},
  {"id":"st-1336","cat":"safety-first","type":"spot","hook":"Spot the two unsafe answers to 'what's my first move?'","scene":[{"id":"a","text":"Ask 'can I help safely here?'","trick":false},{"id":"b","text":"Rush in on impulse","trick":true},{"id":"c","text":"Check where the nearest guard is","trick":false},{"id":"d","text":"Go in alone against the group","trick":true},{"id":"e","text":"Pick the smallest safe action","trick":false}],"why":"Rushing in blind and taking on a group alone skip the safety check.","relearn":"Catch the unsafe first moves, rushing in and fighting a group.","persona":"any","source":"safety-first"},
  {"id":"st-1337","cat":"safety-first","type":"spot","hook":"Spot the two risky reactions when a harasser films girls.","scene":[{"id":"a","text":"Note his description, tell the guard","trick":false},{"id":"b","text":"Snatch his phone and bolt","trick":true},{"id":"c","text":"Stand near so they're not isolated","trick":false},{"id":"d","text":"Start a fistfight for the phone","trick":true},{"id":"e","text":"Keep a safe distance while help comes","trick":false}],"why":"Snatching the phone and starting a fistfight are the risky reactions.","relearn":"Catch the risky reactions, snatching and fighting.","persona":"any","source":"safety-first / document"},
  {"id":"st-1338","cat":"safety-first","type":"spot","hook":"Spot the two moves that escalate danger instead of cooling it.","scene":[{"id":"a","text":"Stepping back when it turns dangerous","trick":false},{"id":"b","text":"Daring the angry man to 'try something'","trick":true},{"id":"c","text":"Calling 112 as you move away","trick":false},{"id":"d","text":"Throwing the first punch to look tough","trick":true},{"id":"e","text":"Moving the target toward the crowd","trick":false}],"why":"Daring him and throwing a punch pour fuel on the danger.","relearn":"Catch the moves that escalate, daring him and punching.","persona":"any","source":"safety-first"},
  {"id":"st-1339","cat":"safety-first","type":"spot","hook":"Spot the two lines that drop the target to chase the harasser.","scene":[{"id":"a","text":"'Are you okay? Let's get you safe'","trick":false},{"id":"b","text":"'Wait here, I'm going to chase him'","trick":true},{"id":"c","text":"'I'll stay right beside you'","trick":false},{"id":"d","text":"'Forget her, let's go fight him'","trick":true},{"id":"e","text":"'Want me to call someone for help?'","trick":false}],"why":"Chasing him and 'forget her, fight him' abandon the target for revenge.","relearn":"Catch the lines that abandon the target for the harasser.","persona":"any","source":"safety-first"},
  {"id":"st-1350","cat":"spot-harassment","type":"spot","persona":"any","source":"transport (India)","relearn":"Repeated unwanted contact in shared transport is harassment.","hook":"In an auto-share. Spot the two red flags.","scene":[{"id":"a","text":"A man slides his hand onto a girl's leg and she pulls away","trick":true},{"id":"b","text":"The auto is full at rush hour","trick":false},{"id":"c","text":"He keeps shifting closer each time she edges off","trick":true},{"id":"d","text":"Traffic is slow today","trick":false},{"id":"e","text":"Two strangers split the fare and chat about the route","trick":false}],"why":"Unwanted touch and closing in after she moves away are harassment, not 'the squeeze'."},
  {"id":"st-1351","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Standing too close and shadowing someone who moves away is harassment.","hook":"At the bus stop. Spot the two red flags.","scene":[{"id":"a","text":"A man stands too close and stares at a girl who steps back","trick":true},{"id":"b","text":"People are waiting for the 9 a.m. bus","trick":false},{"id":"c","text":"He mirrors her steps to stay right beside her","trick":true},{"id":"d","text":"A vendor is selling tea nearby","trick":false},{"id":"e","text":"Two classmates wave and stand together","trick":false}],"why":"Crowding and shadowing someone who keeps stepping back is harassment."},
  {"id":"st-1352","cat":"spot-harassment","type":"spot","persona":"any","source":"peer harassment","relearn":"Commenting on bodies and blocking someone's path is harassment.","hook":"Outside the coaching class. Spot the two red flags.","scene":[{"id":"a","text":"Older boys rate girls' looks out loud as they pass","trick":true},{"id":"b","text":"Students are leaving the evening batch","trick":false},{"id":"c","text":"They block the gate so a girl can't walk through","trick":true},{"id":"d","text":"Auto drivers wait for riders","trick":false},{"id":"e","text":"Two friends compare notes about a test","trick":false}],"why":"Rating bodies out loud and blocking the way are harassment, not 'banter'."},
  {"id":"st-1353","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Pressuring someone on camera and sexual messages are harassment.","hook":"On a project video call. Spot the two red flags.","scene":[{"id":"a","text":"A boy keeps asking a girl to turn on her camera 'to see her'","trick":true},{"id":"b","text":"The call is about the science model","trick":false},{"id":"c","text":"He sends a private message saying she 'looks hot today'","trick":true},{"id":"d","text":"Members share the slides","trick":false},{"id":"e","text":"Someone asks who writes the intro","trick":false}],"why":"Pressuring to be seen and sexual messages are harassment, not 'the project'."},
  {"id":"st-1354","cat":"spot-harassment","type":"spot","persona":"any","source":"transport","relearn":"Repeated unwanted touch and body comments are harassment.","hook":"In the school van. Spot the two red flags.","scene":[{"id":"a","text":"An older student keeps 'accidentally' brushing a junior who shifts away","trick":true},{"id":"b","text":"The van picks up six students","trick":false},{"id":"c","text":"He whispers comments about her body","trick":true},{"id":"d","text":"The route passes the market","trick":false},{"id":"e","text":"Two kids share earphones","trick":false}],"why":"Repeated 'accidental' touch and body comments are harassment."},
  {"id":"st-1355","cat":"spot-harassment","type":"spot","persona":"any","source":"peer harassment","relearn":"Following someone seat to seat and rating their looks is harassment.","hook":"In the library. Spot the two red flags.","scene":[{"id":"a","text":"A boy keeps moving to sit beside a girl who keeps relocating","trick":true},{"id":"b","text":"It's a quiet study hour","trick":false},{"id":"c","text":"He slides her a note rating her appearance","trick":true},{"id":"d","text":"Students are revising for exams","trick":false},{"id":"e","text":"A pair quietly shares a textbook","trick":false}],"why":"Following her seat to seat and rating her looks are harassment, not 'studying'."},
  {"id":"st-1356","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Demanding photos with threats and sexual spam online are harassment.","hook":"On a gaming chat. Spot the two red flags.","scene":[{"id":"a","text":"A player demands a girl send a photo or he'll kick her","trick":true},{"id":"b","text":"The squad is planning the next match","trick":false},{"id":"c","text":"He spams sexual messages when she says no","trick":true},{"id":"d","text":"Someone shares a new map tip","trick":false},{"id":"e","text":"Two players agree to team up","trick":false}],"why":"Threatening to punish a 'no' and spamming sexual messages are harassment."},
  {"id":"st-1357","cat":"spot-harassment","type":"spot","persona":"any","source":"family / consent","relearn":"Unwanted pulling-in and body comments are harassment, even from family.","hook":"At a wedding function. Spot the two red flags.","scene":[{"id":"a","text":"A relative keeps pulling a teen close after she pulls back","trick":true},{"id":"b","text":"The hall is set for the sangeet","trick":false},{"id":"c","text":"He comments on her 'grown up' figure","trick":true},{"id":"d","text":"Guests dance in a circle","trick":false},{"id":"e","text":"Cousins pose for a selfie","trick":false}],"why":"Pulling someone in past their 'no' and body comments are harassment."},
  {"id":"st-1358","cat":"spot-harassment","type":"spot","persona":"any","source":"transport / online GBV","relearn":"Secretly filming someone's body on transport is harassment.","hook":"In the metro coach. Spot the two red flags.","scene":[{"id":"a","text":"A man films a sleeping girl's body on his phone","trick":true},{"id":"b","text":"The coach is air-conditioned","trick":false},{"id":"c","text":"He moves closer to get a better angle","trick":true},{"id":"d","text":"An announcement names the next station","trick":false},{"id":"e","text":"Two commuters read on their phones","trick":false}],"why":"Secretly filming someone and closing in for an angle are harassment."},
  {"id":"st-1359","cat":"spot-harassment","type":"spot","persona":"any","source":"street harassment","relearn":"Following someone on foot or bike is harassment, not 'just passing'.","hook":"After tuition, on the lane home. Spot the two red flags.","scene":[{"id":"a","text":"Two men on a bike slow down to trail a girl walking","trick":true},{"id":"b","text":"Shops are closing for the evening","trick":false},{"id":"c","text":"They call out and circle back when she speeds up","trick":true},{"id":"d","text":"A dog sleeps near a shutter","trick":false},{"id":"e","text":"Neighbours chat at a doorway","trick":false}],"why":"Trailing and circling back on someone walking is following, which is harassment."},
  {"id":"st-1360","cat":"spot-harassment","type":"spot","persona":"any","source":"peer harassment","relearn":"Grabbing at someone and ignoring their 'stop' is harassment.","hook":"In the canteen. Spot the two red flags.","scene":[{"id":"a","text":"A boy keeps grabbing a girl's dupatta as she walks past","trick":true},{"id":"b","text":"Lunch is being served","trick":false},{"id":"c","text":"He laughs 'it's just timepass' when she tells him to stop","trick":true},{"id":"d","text":"Friends share a plate of samosas","trick":false},{"id":"e","text":"Two students queue for water","trick":false}],"why":"Grabbing clothing and calling a 'no' timepass are harassment, not a joke."},
  {"id":"st-1361","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Unwanted explicit images and dodging blocks online are harassment.","hook":"On a social app. Spot the two red flags.","scene":[{"id":"a","text":"A stranger sends an unwanted explicit picture in a girl's DMs","trick":true},{"id":"b","text":"She posted a photo of her art","trick":false},{"id":"c","text":"He keeps making new accounts after she blocks him","trick":true},{"id":"d","text":"A friend liked her post","trick":false},{"id":"e","text":"Someone asks where she bought her paints","trick":false}],"why":"Sending explicit images and re-contacting after a block are harassment."},
  {"id":"st-1362","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Photographing and rating someone's body without consent is harassment.","hook":"At the playground. Spot the two red flags.","scene":[{"id":"a","text":"Older boys snap a girl's photo without asking and zoom in","trick":true},{"id":"b","text":"Kids are playing cricket","trick":false},{"id":"c","text":"They shout marks out of ten about her body","trick":true},{"id":"d","text":"A vendor sells golgappa nearby","trick":false},{"id":"e","text":"Two girls take turns on the swing","trick":false}],"why":"Photographing without consent and shouting body ratings are harassment."},
  {"id":"st-1363","cat":"spot-harassment","type":"spot","persona":"Veer","source":"self-accountability","relearn":"Forwarding private photos and sharing a number to harass is harassment.","hook":"Veer checks his own group chat. Spot the two red flags.","scene":[{"id":"a","text":"Friends forward a girl's private photo 'for a laugh'","trick":true},{"id":"b","text":"The chat plans a football match","trick":false},{"id":"c","text":"Someone adds her number 'to rate her'","trick":true},{"id":"d","text":"A meme about exams is shared","trick":false},{"id":"e","text":"Friends decide who brings the ball","trick":false}],"why":"Forwarding private photos and circulating a number to rate her are harassment."},
  {"id":"st-1364","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Blocking someone's exit and pressing for details is harassment.","hook":"In the lift of a building. Spot the two red flags.","scene":[{"id":"a","text":"A man stands blocking the door so a girl can't leave","trick":true},{"id":"b","text":"The lift goes to the fourth floor","trick":false},{"id":"c","text":"He keeps asking which flat she lives in","trick":true},{"id":"d","text":"A delivery box sits in the corner","trick":false},{"id":"e","text":"Two neighbours nod hello","trick":false}],"why":"Blocking the exit and pressing for her address are harassment."},
  {"id":"st-1365","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Pressing against people in a crowd and following them is harassment.","hook":"At the temple fair. Spot the two red flags.","scene":[{"id":"a","text":"A man presses against girls in the crowd and grins","trick":true},{"id":"b","text":"Bells are ringing at the shrine","trick":false},{"id":"c","text":"He follows one who pulls away into the next stall","trick":true},{"id":"d","text":"Families buy prasad and bangles","trick":false},{"id":"e","text":"Two friends share a plate of chaat","trick":false}],"why":"Using a crowd to press against people and following are harassment, not 'the rush'."},
  {"id":"st-1366","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Sexual comments and threats to locate someone online are harassment.","hook":"On a comment thread. Spot the two red flags.","scene":[{"id":"a","text":"Strangers post sexual comments under a girl's dance video","trick":true},{"id":"b","text":"She shared a clip of a class performance","trick":false},{"id":"c","text":"One threatens to find her school and 'visit'","trick":true},{"id":"d","text":"A friend leaves a clapping emoji","trick":false},{"id":"e","text":"Someone asks the name of the song","trick":false}],"why":"Sexual comments and a threat to track her down are harassment."},
  {"id":"st-1367","cat":"spot-harassment","type":"spot","persona":"any","source":"peer harassment","relearn":"Lurking by and filming around private spaces is harassment.","hook":"Outside the girls' washroom. Spot the two red flags.","scene":[{"id":"a","text":"A boy loiters and counts who goes in and out","trick":true},{"id":"b","text":"The corridor leads to the labs","trick":false},{"id":"c","text":"He tries to film under the door gap","trick":true},{"id":"d","text":"A teacher walks to the staff room","trick":false},{"id":"e","text":"Two students wait their turn at the tap","trick":false}],"why":"Lurking to track and trying to film are serious harassment."},
  {"id":"st-1368","cat":"spot-harassment","type":"spot","persona":"any","source":"transport","relearn":"Repeated 'accidental' brushing and crowding are harassment, not coincidence.","hook":"On the train platform. Spot the two red flags.","scene":[{"id":"a","text":"A man keeps brushing past a girl and apologising each time","trick":true},{"id":"b","text":"The 6 p.m. local is announced","trick":false},{"id":"c","text":"He boards the same door she does and crowds her","trick":true},{"id":"d","text":"Coolies carry luggage past","trick":false},{"id":"e","text":"Two travellers check the timetable board","trick":false}],"why":"Repeated 'accidental' brushing and crowding her boarding are harassment."},
  {"id":"st-1369","cat":"spot-harassment","type":"spot","persona":"any","source":"transport","relearn":"Singing crude songs at someone and filming them is harassment.","hook":"At the bus's back seat. Spot the two red flags.","scene":[{"id":"a","text":"Boys sing crude songs aimed at a girl two seats ahead","trick":true},{"id":"b","text":"The bus is heading to the depot","trick":false},{"id":"c","text":"They lean over to film her reaction","trick":true},{"id":"d","text":"The conductor calls out a stop","trick":false},{"id":"e","text":"Two passengers nap by the window","trick":false}],"why":"Crude targeted songs and filming her are harassment, not 'just music'."},
  {"id":"st-1370","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Persisting after 'stop' and exposing an address is harassment.","hook":"In a study WhatsApp group. Spot the two red flags.","scene":[{"id":"a","text":"A boy keeps sending heart messages after she says stop","trick":true},{"id":"b","text":"The group shares the exam date sheet","trick":false},{"id":"c","text":"He posts where she lives 'so others can drop by'","trick":true},{"id":"d","text":"Someone uploads last year's paper","trick":false},{"id":"e","text":"Members plan a revision call","trick":false}],"why":"Persisting after 'stop' and broadcasting her address are harassment."},
  {"id":"st-1371","cat":"spot-harassment","type":"spot","persona":"any","source":"power / consent","relearn":"Unwanted touch and body remarks are harassment, even from a coach.","hook":"At the sports ground. Spot the two red flags.","scene":[{"id":"a","text":"A coach 'fixes' a girl's posture by touching her after she steps away","trick":true},{"id":"b","text":"Players warm up for practice","trick":false},{"id":"c","text":"He keeps making remarks about her body","trick":true},{"id":"d","text":"Cones are set out for drills","trick":false},{"id":"e","text":"Teammates pass the ball","trick":false}],"why":"Touch after she pulls away and body remarks are harassment."},
  {"id":"st-1372","cat":"spot-harassment","type":"spot","persona":"any","source":"street harassment","relearn":"Catcalling and blocking someone's path is harassment.","hook":"On the way to the well. Spot the two red flags.","scene":[{"id":"a","text":"Men outside a shop call out and whistle at passing girls","trick":true},{"id":"b","text":"The lane is dusty in summer","trick":false},{"id":"c","text":"One steps into a girl's path to make her stop","trick":true},{"id":"d","text":"A cycle leans on the wall","trick":false},{"id":"e","text":"Two women carry pots and talk","trick":false}],"why":"Whistling at and blocking passers-by is 'eve-teasing', which is harassment."},
  {"id":"st-1373","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Pressuring for details and unwanted explicit photos are harassment.","hook":"On a dating-style app a teen is on. Spot the two red flags.","scene":[{"id":"a","text":"A match keeps pressuring for her private number after she says no","trick":true},{"id":"b","text":"They first chatted about music","trick":false},{"id":"c","text":"He sends an explicit photo she never asked for","trick":true},{"id":"d","text":"She mentioned she likes hiking","trick":false},{"id":"e","text":"He asks what bands she follows","trick":false}],"why":"Pressuring past a 'no' and sending explicit photos are harassment."},
  {"id":"st-1374","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Crowding into someone's space and unwanted touch is harassment.","hook":"In the cinema hall. Spot the two red flags.","scene":[{"id":"a","text":"A man moves to the empty seat beside a girl and leans over","trick":true},{"id":"b","text":"The film is about to start","trick":false},{"id":"c","text":"He puts his hand on her armrest near her and won't move it back","trick":true},{"id":"d","text":"Popcorn is being sold in the aisle","trick":false},{"id":"e","text":"Two friends share a tub of nachos","trick":false}],"why":"Seat-switching to crowd her and lingering touch are harassment."},
  {"id":"st-1375","cat":"spot-harassment","type":"spot","persona":"Riya","source":"peer harassment","relearn":"Unwanted touching and conditioning a 'stop' on obedience is harassment.","hook":"Riya watches the corridor. Spot the two red flags she can name.","scene":[{"id":"a","text":"A boy keeps flicking a girl's hair as she tries to walk on","trick":true},{"id":"b","text":"The corridor is busy between classes","trick":false},{"id":"c","text":"He says 'I'll stop when you smile for me'","trick":true},{"id":"d","text":"Lockers line the wall","trick":false},{"id":"e","text":"Two students compare timetables","trick":false}],"why":"Unwanted touching and 'I'll stop if you obey me' are harassment, not flirting."},
  {"id":"st-1376","cat":"spot-harassment","type":"spot","persona":"any","source":"public space","relearn":"Grinding against and grabbing someone who moves away is harassment.","hook":"At a festival concert. Spot the two red flags.","scene":[{"id":"a","text":"A man grinds against a girl in the crowd who keeps moving away","trick":true},{"id":"b","text":"Lights flash on the stage","trick":false},{"id":"c","text":"He grabs her wrist when she tries to leave","trick":true},{"id":"d","text":"People sing along to the song","trick":false},{"id":"e","text":"Two friends jump to the beat together","trick":false}],"why":"Pressing against someone and grabbing to stop them leaving are harassment."},
  {"id":"st-1377","cat":"spot-harassment","type":"spot","persona":"any","source":"power / safeguarding","relearn":"Personal comments and secrecy from an adult are harassment red flags.","hook":"On a teacher's DM. Spot the two red flags.","scene":[{"id":"a","text":"A tutor messages a student late at night about her 'pretty smile'","trick":true},{"id":"b","text":"He shares the homework deadline","trick":false},{"id":"c","text":"He asks her to keep their chats secret","trick":true},{"id":"d","text":"He posts a reading link for the class","trick":false},{"id":"e","text":"He answers a doubt about a sum","trick":false}],"why":"Late-night looks-comments and 'keep it secret' from an adult are red flags."},
  {"id":"st-1378","cat":"spot-harassment","type":"spot","persona":"any","source":"transport","relearn":"Deliberate falling-into someone and twisting their 'no' is harassment.","hook":"In the school bus aisle. Spot the two red flags.","scene":[{"id":"a","text":"A senior keeps 'falling' into a junior at every brake on purpose","trick":true},{"id":"b","text":"The bus stops at several gates","trick":false},{"id":"c","text":"He laughs and says she 'likes it really'","trick":true},{"id":"d","text":"Bags are stacked on the racks","trick":false},{"id":"e","text":"Two kids swap snacks across the aisle","trick":false}],"why":"Engineered 'falls' and 'she likes it really' are harassment, not the brakes."},
  {"id":"st-1379","cat":"spot-harassment","type":"spot","persona":"any","source":"street harassment","relearn":"Seeking an address and lying in wait is stalking and harassment.","hook":"At the coaching reception. Spot the two red flags.","scene":[{"id":"a","text":"A man asks the desk for a girl student's home address","trick":true},{"id":"b","text":"Parents are paying fees","trick":false},{"id":"c","text":"He waits by her scooter after she said no","trick":true},{"id":"d","text":"A notice lists the timetable","trick":false},{"id":"e","text":"Students collect ID cards","trick":false}],"why":"Fishing for her address and lying in wait are stalking, which is harassment."},
  {"id":"st-1380","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Demanding someone undress on stream and saving screenshots is harassment.","hook":"On a livestream comment box. Spot the two red flags.","scene":[{"id":"a","text":"Viewers demand a teen streamer 'show more' of herself","trick":true},{"id":"b","text":"She is streaming a drawing tutorial","trick":false},{"id":"c","text":"One says he saved screenshots 'for later'","trick":true},{"id":"d","text":"A viewer asks about her pen tablet","trick":false},{"id":"e","text":"Someone says good morning","trick":false}],"why":"Demanding she expose herself and 'saved screenshots' are harassment."},
  {"id":"st-1381","cat":"spot-harassment","type":"spot","persona":"any","source":"transport","relearn":"Trapping someone and ignoring their 'move' is harassment.","hook":"In the crowded general compartment. Spot the two red flags.","scene":[{"id":"a","text":"A man traps a girl against the wall, blocking the door","trick":true},{"id":"b","text":"The train is packed at peak hour","trick":false},{"id":"c","text":"He presses in further each time she asks him to move","trick":true},{"id":"d","text":"Vendors sell water down the aisle","trick":false},{"id":"e","text":"Passengers guard their bags","trick":false}],"why":"Trapping her and pressing in after a clear 'move' are harassment."},
  {"id":"st-1382","cat":"spot-harassment","type":"spot","persona":"any","source":"street harassment","relearn":"Repeated body comments and isolating demands are harassment.","hook":"At the neighbourhood shop. Spot the two red flags.","scene":[{"id":"a","text":"A man comments on a schoolgirl's body every time she buys milk","trick":true},{"id":"b","text":"The shop sells bread and eggs","trick":false},{"id":"c","text":"He tells her to 'come alone next time'","trick":true},{"id":"d","text":"A fan whirs over the counter","trick":false},{"id":"e","text":"Two customers wait for change","trick":false}],"why":"Daily body comments and 'come alone' are harassment, not friendliness."},
  {"id":"st-1383","cat":"spot-harassment","type":"spot","persona":"any","source":"online GBV","relearn":"Sexual sounds and messages aimed at someone are harassment.","hook":"In the group video class. Spot the two red flags.","scene":[{"id":"a","text":"A boy keeps unmuting to make kissing sounds at a girl","trick":true},{"id":"b","text":"The teacher shares the screen","trick":false},{"id":"c","text":"He private-messages a sexual remark about her","trick":true},{"id":"d","text":"A student raises a hand to ask a doubt","trick":false},{"id":"e","text":"Classmates type notes in the chat","trick":false}],"why":"Targeted kissing sounds and sexual messages are harassment, not 'clowning'."},
  {"id":"st-1384","cat":"spot-harassment","type":"spot","persona":"any","source":"definition","relearn":"Welcome, one-off, respected interaction isn't harassment; unwanted persistence is.","hook":"Among these mixed moments, spot the two that ARE harassment.","scene":[{"id":"a","text":"Messaging on after a clear 'please stop'","trick":true},{"id":"b","text":"Asking a classmate once, then accepting a no","trick":false},{"id":"c","text":"Whistling and rating a stranger's body","trick":true},{"id":"d","text":"A handshake and 'nice match' after a game","trick":false},{"id":"e","text":"Waving hello to a friend","trick":false}],"why":"The two flags are the unwanted, sexualising acts; the rest are welcome."},
  {"id":"st-1385","cat":"spot-harassment","type":"spot","persona":"Veer","source":"self-accountability","relearn":"Self-checking means catching persistence past 'no' and body comments.","hook":"Veer rereads his own chats. Spot the two red flags in his behaviour.","scene":[{"id":"a","text":"He kept messaging her after she said no","trick":true},{"id":"b","text":"He asked her to join the quiz team, then accepted her no","trick":false},{"id":"c","text":"He commented on her body 'as a compliment'","trick":true},{"id":"d","text":"He thanked her for help with a sum","trick":false},{"id":"e","text":"He wished her happy birthday","trick":false}],"why":"Persisting past a 'no' and body 'compliments' are harassment."},
  {"id":"st-1386","cat":"spot-harassment","type":"spot","persona":"any","source":"reading the scene","relearn":"Backing away and seeking an exit can signal someone needs help.","hook":"Spot the two body-language cues that someone needs help.","scene":[{"id":"a","text":"A girl edges away and clutches her bag as a man talks at her","trick":true},{"id":"b","text":"She waits calmly for her friend","trick":false},{"id":"c","text":"She keeps scanning for a way out","trick":true},{"id":"d","text":"She reads a notice on the wall","trick":false},{"id":"e","text":"She chats with a classmate","trick":false}],"why":"Edging away, gripping her bag and seeking an exit can signal she needs help."},
  {"id":"st-1387","cat":"spot-harassment","type":"sort","persona":"any","source":"definition","relearn":"The test is whether it's wanted, not where or who.","hook":"Sort each line: harassment, or a welcome interaction?","items":[{"id":"a","text":"Sexual DMs that keep coming after 'no'"},{"id":"b","text":"A friend asking if you want to walk home together"},{"id":"c","text":"Catcalling a stranger on the road"},{"id":"d","text":"Saying 'great game' and a fist-bump"},{"id":"e","text":"Grabbing someone's hand who pulls away"},{"id":"f","text":"Wishing a classmate happy birthday"}],"bins":[{"id":"harass","label":"Harassment","valence":"neg"},{"id":"welcome","label":"Welcome","valence":"pos"}],"key":{"a":"harass","b":"welcome","c":"harass","d":"welcome","e":"harass","f":"welcome"}},
  {"id":"st-1388","cat":"spot-harassment","type":"sort","persona":"any","source":"awareness","relearn":"Harassment is about behaviour, so it can happen anywhere, any time.","hook":"Sort: can harassment happen here?","items":[{"id":"a","text":"On the bus or metro"},{"id":"b","text":"In a school corridor"},{"id":"c","text":"In private DMs and group chats"},{"id":"d","text":"At a family function"},{"id":"e","text":"Only in 'unsafe' parts of town"},{"id":"f","text":"Only after dark"}],"bins":[{"id":"yes","label":"Yes, here too","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"yes","b":"yes","c":"yes","d":"yes","e":"myth","f":"myth"}},
  {"id":"st-1389","cat":"spot-harassment","type":"sort","persona":"any","source":"reading the scene","relearn":"Following, touch-after-a-no and secret filming are red flags.","hook":"Sort each move: a red flag, or just ordinary?","items":[{"id":"a","text":"Following someone who sped up to leave"},{"id":"b","text":"Walking the same way, then turning off"},{"id":"c","text":"Touching after they moved your hand"},{"id":"d","text":"Sitting near a free window seat"},{"id":"e","text":"Filming a stranger's body on the sly"},{"id":"f","text":"A group selfie everyone posed for"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"ok","label":"Ordinary","valence":"pos"}],"key":{"a":"flag","b":"ok","c":"flag","d":"ok","e":"flag","f":"ok"}},
  {"id":"st-1390","cat":"spot-harassment","type":"sort","persona":"any","source":"online GBV","relearn":"Unwanted sexual content, block-dodging and image threats are harassment online.","hook":"Sort: online harassment, or normal online chat?","items":[{"id":"a","text":"Unwanted explicit images in your DMs"},{"id":"b","text":"A friend tagging you in a meme"},{"id":"c","text":"New accounts to reach you after a block"},{"id":"d","text":"A classmate asking for the homework"},{"id":"e","text":"Threats to share private photos"},{"id":"f","text":"A like on the art you posted"}],"bins":[{"id":"harass","label":"Harassment","valence":"neg"},{"id":"normal","label":"Normal","valence":"pos"}],"key":{"a":"harass","b":"normal","c":"harass","d":"normal","e":"harass","f":"normal"}},
  {"id":"st-1391","cat":"spot-harassment","type":"sort","persona":"any","source":"awareness","relearn":"Harassment wears many settings; naming the place helps you read it.","hook":"Sort by where it happens: street, transport, online, or school?","items":[{"id":"a","text":"Whistling and following on the road"},{"id":"b","text":"Brushing against someone on a packed bus"},{"id":"c","text":"Sexual messages in a DM"},{"id":"d","text":"Cornering someone in the corridor"},{"id":"e","text":"Catcalling from a shop front"},{"id":"f","text":"Pressing against someone in the metro"}],"bins":[{"id":"street","label":"Street","valence":"neutral"},{"id":"transport","label":"Transport","valence":"neutral"},{"id":"online","label":"Online","valence":"neutral"},{"id":"school","label":"School","valence":"neutral"}],"key":{"a":"street","b":"transport","c":"online","d":"school","e":"street","f":"transport"}},
  {"id":"st-1392","cat":"spot-harassment","type":"sort","persona":"any","source":"reading consent","relearn":"Stepping back, a clear 'stop' and a barrier signal it isn't wanted.","hook":"Sort: an 'unwanted' sign, or a welcome one?","items":[{"id":"a","text":"She keeps stepping back and looking away"},{"id":"b","text":"They both laugh and lean in to chat"},{"id":"c","text":"He moved her hand; she put it back"},{"id":"d","text":"She says 'stop' and he keeps going"},{"id":"e","text":"Two friends high-five and grin"},{"id":"f","text":"She moves her bag between them"}],"bins":[{"id":"unwanted","label":"Unwanted","valence":"neg"},{"id":"welcome","label":"Welcome","valence":"pos"}],"key":{"a":"unwanted","b":"welcome","c":"unwanted","d":"unwanted","e":"welcome","f":"unwanted"}},
  {"id":"st-1393","cat":"spot-harassment","type":"sort","persona":"Veer","source":"self-accountability","relearn":"Sharing private photos, rating bodies and circulating numbers are red flags.","hook":"Veer sorts: a red flag to call out, or a normal moment?","items":[{"id":"a","text":"Mates forwarding a girl's private photo"},{"id":"b","text":"Mates planning a cricket match"},{"id":"c","text":"Rating a passing girl out of ten"},{"id":"d","text":"Asking a classmate to join the project"},{"id":"e","text":"Sharing her number to message her"},{"id":"f","text":"Wishing a teammate good luck"}],"bins":[{"id":"flag","label":"Call it out","valence":"tell"},{"id":"ok","label":"Just normal","valence":"pos"}],"key":{"a":"flag","b":"ok","c":"flag","d":"ok","e":"flag","f":"ok"}},
  {"id":"st-1394","cat":"spot-harassment","type":"sort","persona":"any","source":"peer harassment","relearn":"'It's just a joke' doesn't make unwanted, sexualising acts harmless.","hook":"Sort: harassment, even dressed up as 'a joke'?","items":[{"id":"a","text":"Grabbing a dupatta, calling it 'timepass'"},{"id":"b","text":"A pun about the homework"},{"id":"c","text":"Body 'compliments' a stranger didn't ask for"},{"id":"d","text":"A friend's funny story everyone enjoys"},{"id":"e","text":"Kissing sounds aimed at a classmate"},{"id":"f","text":"A meme shared in the class group"}],"bins":[{"id":"harass","label":"Still harassment","valence":"neg"},{"id":"joke","label":"Actually a joke","valence":"pos"}],"key":{"a":"harass","b":"joke","c":"harass","d":"joke","e":"harass","f":"joke"}},
  {"id":"st-1395","cat":"spot-harassment","type":"sort","persona":"any","source":"reading the scene","relearn":"Backing away, seeking an exit and freezing can mean someone needs a check-in.","hook":"Sort: which lines should make you check on someone?","items":[{"id":"a","text":"She backs away and grips her bag"},{"id":"b","text":"She's calmly reading a book"},{"id":"c","text":"She keeps scanning for an exit"},{"id":"d","text":"She's laughing with a friend"},{"id":"e","text":"She freezes and goes quiet as a man crowds her"},{"id":"f","text":"She's choosing a snack at the stall"}],"bins":[{"id":"check","label":"Check on her","valence":"uhoh"},{"id":"fine","label":"Looks fine","valence":"pos"}],"key":{"a":"check","b":"fine","c":"check","d":"fine","e":"check","f":"fine"}},
  {"id":"st-1396","cat":"spot-harassment","type":"reflect","persona":"any","source":"awareness","relearn":"Reading a scene turns vague unease into something you can name.","hook":"Lensy: once you can read a scene, harassment stops hiding as 'normal'. Feel that?","prompt":"What do you think?","options":["Yes","It's clearer now","I can read it"],"affirm":"Reading the scene is a skill, and you're building it."},
  {"id":"st-1397","cat":"spot-harassment","type":"reflect","persona":"any","source":"awareness","relearn":"A gentle label can hide that harassment is harassment.","hook":"Lensy: 'eve-teasing' is a soft word for something that isn't soft. Sit with that.","prompt":"Be honest.","options":["True","Hadn't thought of it","It matters"],"affirm":"Naming it honestly is how you stop excusing it."},
  {"id":"st-1398","cat":"spot-harassment","type":"reflect","persona":"any","source":"definition","relearn":"What makes it harassment is that it's unwanted, not where it happens.","hook":"Lensy: the place doesn't decide it; the welcome does. Make sense?","prompt":"Your take?","options":["Yes","Makes sense","Wanted vs unwanted"],"affirm":"You've got the real test: is it welcome, or not?"},
  {"id":"st-1399","cat":"spot-harassment","type":"reflect","persona":"Veer","source":"self-accountability","relearn":"Reading harassment includes an honest look at your own behaviour.","hook":"Lensy: spotting it also means checking your own moves honestly. Ready to?","prompt":"Honestly?","options":["Yes","I'll check myself","Fair"],"affirm":"Checking yourself is brave, and it's how allies grow."},
  {"id":"st-1400","cat":"spot-harassment","type":"reflect","persona":"any","source":"reading the scene","relearn":"Body language can quietly signal that someone needs help.","hook":"Lensy: a tense face and backing away can be a quiet call for help. Noticed that?","prompt":"Have you?","options":["Yes","Maybe","I'll watch for it"],"affirm":"Tuning in to body language is real upstander skill."},
  {"id":"st-1401","cat":"spot-harassment","type":"reflect","persona":"any","source":"peer harassment","relearn":"'It's just a joke' is a common cover for unwanted behaviour.","hook":"Lensy: 'just a joke' is often where harassment hides. Recognise that?","prompt":"What do you think?","options":["Yes","Often true","It's a cover"],"affirm":"Seeing past the 'joke' is exactly the eye this game builds."},
  {"id":"st-1402","cat":"spot-harassment","type":"reflect","persona":"any","source":"awareness","relearn":"Anyone can face harassment; it's wrong whoever the target is.","hook":"Lensy: harassment isn't only aimed at girls; anyone can be a target. Agree?","prompt":"Your view?","options":["Agree","Yes","Anyone can be"],"affirm":"Reading it for everyone makes you a fairer upstander."},
  {"id":"st-1403","cat":"spot-harassment","type":"reflect","persona":"any","source":"online GBV","relearn":"The 'is it welcome?' test reads harassment online and offline alike.","hook":"Lensy: online and offline, the same test holds, wanted or not. See it?","prompt":"Think so?","options":["Yes","Same test","It travels"],"affirm":"One clear test works on the road and in the DMs."},
  {"id":"st-1404","cat":"spot-harassment","type":"reflect","persona":"Riya","source":"reading the scene","relearn":"An uneasy gut feeling is a real signal worth taking seriously.","hook":"Riya: when something feels off, your gut is data, not drama. Trust it?","prompt":"Do you?","options":["Yes","Learning to","I'll trust it"],"affirm":"That uneasy feeling is worth listening to."},
  {"id":"st-1405","cat":"spot-harassment","type":"role-play","persona":"any","source":"naming voice","relearn":"Naming it plainly tells her it's real and not her fault.","hook":"A friend isn't sure if what she saw 'counts' as harassment. Help her name it.","setup":"She describes a man following her. Say:","yourLine":[{"text":"\"That's following, and following is harassment, you're not overreacting.\"","best":true},{"text":"\"Maybe you imagined it.\""}]},
  {"id":"st-1406","cat":"spot-harassment","type":"role-play","persona":"any","source":"naming voice","relearn":"A real compliment is welcome; an unwanted one isn't.","hook":"Someone says 'it was just a compliment'. Name it without blaming the target.","setup":"Respond to the 'compliment' line. Say:","yourLine":[{"text":"\"Comments she didn't want aren't compliments, that's harassment.\"","best":true},{"text":"\"She should take it nicely.\""}]},
  {"id":"st-1407","cat":"spot-harassment","type":"role-play","persona":"any","source":"naming voice","relearn":"A clear 'stop' that's ignored makes it harassment, joke or not.","hook":"A junior asks if a 'joke' grab is harassment. Tell them the truth gently.","setup":"Answer the junior. Say:","yourLine":[{"text":"\"If she said stop and he didn't, the 'joke' is harassment.\"","best":true},{"text":"\"It's fine if it's funny.\""}]},
  {"id":"st-1408","cat":"spot-harassment","type":"role-play","persona":"Veer","source":"ally naming","relearn":"Naming it as an ally shifts the group's tone.","hook":"Veer hears mates rate a girl. Name it instead of laughing along.","setup":"Say it to your friends. Say:","yourLine":[{"text":"\"Rating her body isn't banter, it's harassment, let's drop it.\"","best":true},{"text":"\"Good one.\""}]},
  {"id":"st-1409","cat":"spot-harassment","type":"role-play","persona":"any","source":"online naming","relearn":"A screen doesn't make harassment 'not count'.","hook":"A classmate posts screenshots saying 'this isn't harassment, it's online'. Reply.","setup":"Reply in the chat. Say:","yourLine":[{"text":"\"Unwanted sexual messages are harassment, on or offline.\"","best":true},{"text":"\"It's just the internet.\""}]},
  {"id":"st-1410","cat":"spot-harassment","type":"role-play","persona":"Riya","source":"anti-blame voice","relearn":"Clothes never invite harassment; the choice is the harasser's.","hook":"Riya wonders aloud, 'maybe my clothes caused it'. Set the record straight, kindly.","setup":"Reassure Riya. Say:","yourLine":[{"text":"\"Nothing you wore caused it, harassment is on the person who did it.\"","best":true},{"text":"\"Maybe dress differently next time.\""}]},
  {"id":"st-1411","cat":"spot-harassment","type":"role-play","persona":"any","source":"anti-blame voice","relearn":"Freezing is a normal response and never reduces the harm.","hook":"A friend says 'I froze, so it can't have been that bad'. Reframe it.","setup":"Respond to your friend. Say:","yourLine":[{"text":"\"Freezing is normal, it doesn't make what happened any less real.\"","best":true},{"text":"\"You should've reacted.\""}]},
  {"id":"st-1412","cat":"spot-harassment","type":"role-play","persona":"any","source":"myth-naming","relearn":"'Boys can't help it' is an excuse, not a fact.","hook":"Someone insists 'he can't help it, boys are like that'. Name the myth.","setup":"Answer the excuse. Say:","yourLine":[{"text":"\"Harassment is a choice, not 'just how boys are'.\"","best":true},{"text":"\"I guess that's true.\""}]},
  {"id":"st-1413","cat":"spot-harassment","type":"match","persona":"any","source":"awareness","relearn":"Harassment shows up in many settings; the test is the same in each.","hook":"Match each scene to where the harassment is happening.","pairs":[{"left":"Brushing against someone on a packed metro","right":"On transport"},{"left":"Whistling and following on the road","right":"On the street"},{"left":"Unwanted explicit images in a DM","right":"Online"},{"left":"Cornering someone by the lockers","right":"At school"},{"left":"Pulling a teen close at a wedding","right":"In the family"}]},
  {"id":"st-1414","cat":"spot-harassment","type":"match","persona":"any","source":"definition","relearn":"Each red flag is unwanted and ignores a boundary.","hook":"Match the red flag to why it crosses the line.","pairs":[{"left":"Following after someone speeds up","right":"Ignores their wish to get away"},{"left":"Touching after a hand is moved","right":"Ignores a clear 'no'"},{"left":"Secretly filming a stranger","right":"Takes from them without consent"},{"left":"Rating a body aloud","right":"Treats a person as a thing"},{"left":"Messaging on after 'stop'","right":"Overrides their boundary"}]},
  {"id":"st-1415","cat":"spot-harassment","type":"match","persona":"any","source":"myth-naming","relearn":"Every excuse has a calm truth that names the behaviour for what it is.","hook":"Match the line a harasser uses to the truth that answers it.","pairs":[{"left":"\"It was just a compliment.\"","right":"Unwanted comments aren't compliments"},{"left":"\"It's just a joke.\"","right":"A 'joke' past 'stop' is harassment"},{"left":"\"Boys can't help it.\"","right":"Harassment is a choice"},{"left":"\"She invited it.\"","right":"Nothing anyone wears invites it"},{"left":"\"It's just the internet.\"","right":"Online harassment still counts"}]},
  {"id":"st-1416","cat":"spot-harassment","type":"match","persona":"any","source":"definition","relearn":"The line is welcomeness: wanted and respected, or unwanted and ignored.","hook":"Match each behaviour to whether it's welcome or unwanted.","pairs":[{"left":"A friend asks once to study and accepts your no","right":"Welcome"},{"left":"Repeated DMs after 'please stop'","right":"Unwanted"},{"left":"A high-five after a match","right":"Welcome and friendly"},{"left":"Comments on a stranger's body","right":"Unwanted and harassing"},{"left":"Waving hello across the room","right":"Welcome and ordinary"}]},
  {"id":"st-1417","cat":"spot-harassment","type":"match","persona":"any","source":"online GBV","relearn":"Spot the online red flag, then respond calmly and safely.","hook":"Match the online red flag to a safer response.","pairs":[{"left":"Unwanted explicit image","right":"Don't reply; block and save proof"},{"left":"Threat to share photos","right":"Tell a trusted adult, not alone"},{"left":"New accounts after a block","right":"Block again and report them"},{"left":"Pressure to send a photo","right":"Say no and stop replying"},{"left":"Sexual comments on a post","right":"Limit comments and report"}]},
  {"id":"st-1418","cat":"spot-harassment","type":"match","persona":"any","source":"reading the scene","relearn":"Reading these cues helps you notice when someone quietly needs help.","hook":"Match the body-language cue to what it might be telling you.","pairs":[{"left":"Edging away and gripping a bag","right":"She may feel unsafe"},{"left":"Scanning around for a way out","right":"She may want to leave"},{"left":"Freezing and going quiet","right":"She may be overwhelmed"},{"left":"Glancing at others for help","right":"She may want someone to step in"},{"left":"Forcing a tight, fixed smile","right":"She may be uncomfortable"}]},
  {"id":"st-1419","cat":"spot-harassment","type":"match","persona":"Veer","source":"self-accountability","relearn":"Calling each 'joke' what it is helps an ally stop joining in.","hook":"Veer matches a mate's 'joke' to why it's actually a red flag.","pairs":[{"left":"Forwarding a private photo","right":"It shares her body without consent"},{"left":"Rating a girl out of ten","right":"It reduces her to a score"},{"left":"Sharing her number to message her","right":"It exposes her to be harassed"},{"left":"Kissing sounds in class","right":"It targets and humiliates her"},{"left":"Grabbing her dupatta","right":"It's unwanted touch, not timepass"}]},
  {"id":"st-1420","cat":"spot-harassment","type":"match","persona":"any","source":"awareness","relearn":"Knowing the common red flags per setting sharpens how you read each one.","hook":"Match each setting to the kind of harassment to watch for there.","pairs":[{"left":"Crowded bus or train","right":"Pressing and 'accidental' touch"},{"left":"Quiet lane after class","right":"Following and catcalling"},{"left":"Group chat or DMs","right":"Sexual messages and image threats"},{"left":"School corridor","right":"Cornering and blocking the way"},{"left":"Family function","right":"Unwanted pulling-in and body comments"}]},
  {"id":"st-1421","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"transport / definition","relearn":"Targeted, repeated touch in a crowd is still harassment.","hook":"\"If it's crowded, a bit of touching is unavoidable, not harassment.\"","myth":{"un":"In a crowd, some touching is unavoidable, so it can't be harassment.","re":"Repeated, targeted touch after someone moves away is harassment, crowd or not.","why":"A crowd doesn't excuse touch aimed at one person who keeps pulling back."}},
  {"id":"st-1422","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"awareness","relearn":"Harassment can happen anywhere, not just 'unsafe' places.","hook":"\"It only counts as harassment if it's in a dark, unsafe place.\"","myth":{"un":"Harassment only really happens in dark, unsafe places.","re":"Harassment happens anywhere, on buses, in school, at home and online.","why":"It's the unwanted behaviour that defines it, not the location."}},
  {"id":"st-1423","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"online GBV","relearn":"Online sexual messages and image threats are harassment.","hook":"\"Online messages aren't real harassment, just words on a screen.\"","myth":{"un":"Online stuff isn't real harassment, it's only words on a screen.","re":"Unwanted sexual messages and image threats online are real harassment.","why":"Harm through a screen still frightens and follows a person."}},
  {"id":"st-1424","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"awareness","relearn":"Anyone can be harassed; it's wrong whoever the target is.","hook":"\"Boys get harassed too, so girls shouldn't make a fuss about it.\"","myth":{"un":"Boys face it too, so girls are making a fuss over nothing.","re":"Anyone can be harassed, and it's wrong for every target, no comparing.","why":"One person's harm doesn't cancel another's, it's wrong either way."}},
  {"id":"st-1425","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"anti-blame","relearn":"Freezing is normal and never reduces the harm.","hook":"\"If she didn't shout or fight back, it wasn't really harassment.\"","myth":{"un":"If she didn't shout or fight, it can't have been real harassment.","re":"Freezing is a normal response; it never makes the harm less real.","why":"People often freeze under stress, and that isn't consent."}},
  {"id":"st-1426","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"reading the scene","relearn":"Read behaviour, not looks, to spot harassment.","hook":"\"You can tell harassers apart, they look like creeps.\"","myth":{"un":"Harassers look obvious, you can spot a 'creep' by their face.","re":"Harassment is about behaviour, not looks, anyone can do it or be safe.","why":"Reading actions, not appearances, is how you actually spot it."}},
  {"id":"st-1427","cat":"spot-harassment","type":"strike-rewrite","persona":"Veer","source":"self-accountability","relearn":"Rating bodies aloud is harassment, not 'banter'.","hook":"\"Rating people's bodies is just normal lad banter, not harassment.\"","myth":{"un":"Rating people's bodies is just normal banter among mates.","re":"Rating a stranger's body aloud is harassment, not harmless banter.","why":"It treats a person as a thing and is unwanted by the target."}},
  {"id":"st-1428","cat":"spot-harassment","type":"strike-rewrite","persona":"any","source":"definition","relearn":"An unwanted, persistent 'compliment' can be harassment.","hook":"\"A compliment can't be harassment, it's a nice thing to say.\"","myth":{"un":"A compliment is always nice, so it can't be harassment.","re":"If it's unwanted and persistent, even a 'compliment' is harassment.","why":"What matters is whether it's welcome, not how it's dressed up."}},
  {"id":"st-1429","cat":"spot-harassment","type":"branch","persona":"any","source":"reading the scene","relearn":"Read welcomeness, not the crowd, to spot harassment.","hook":"Unsure if what you see on the bus is harassment. What reads it?","options":[{"text":"Check if the contact is unwanted and repeated","consequence":"Welcomeness tells you it's harassment, not the crowd.","outcome":"safe","best":true},{"text":"Decide it's fine, the bus is crowded","consequence":"A crowd doesn't make targeted, repeated touch okay."}],"debrief":"Read whether it's wanted; unwanted, repeated contact is harassment."},
  {"id":"st-1430","cat":"spot-harassment","type":"branch","persona":"any","source":"awareness","relearn":"Naming 'eve-teasing' as harassment is the first step.","hook":"A friend says 'it's just eve-teasing, ignore it'. The clearer read?","options":[{"text":"Name it: comments and following are harassment","consequence":"Naming it true is the first step to acting safely.","outcome":"safe","best":true},{"text":"Agree and laugh it off","consequence":"Calling it 'harmless' lets the harassment carry on."}],"debrief":"'Eve-teasing' is a soft name for harassment; naming it true is step one."},
  {"id":"st-1431","cat":"spot-harassment","type":"branch","persona":"any","source":"safety-first","relearn":"Spot secret filming, then get help, don't confront alone.","hook":"You spot someone secretly filming a stranger on the platform. Then?","options":[{"text":"Recognise it's harassment; tell station staff","consequence":"You get help safely without confronting them.","outcome":"safe","best":true},{"text":"Grab his phone and shout at him","consequence":"Confronting alone can escalate; get staff instead."}],"debrief":"Secret filming is harassment; the safe move is to alert staff."},
  {"id":"st-1432","cat":"spot-harassment","type":"branch","persona":"any","source":"online GBV","relearn":"Read image threats as harassment, then tell a trusted adult.","hook":"A classmate gets threats to share her photos. You've read it as harassment. Now?","options":[{"text":"Tell her: save proof, block, tell a trusted adult","consequence":"Spotting it leads to safe help, not facing it alone.","outcome":"safe","best":true},{"text":"Tell her to delete her account","consequence":"Disappearing won't stop them; proof and an adult can."}],"debrief":"Image threats are harassment; next is proof, block and a trusted adult."},
  {"id":"st-1433","cat":"spot-harassment","type":"branch","persona":"Veer","source":"ally","relearn":"You can refuse to join, even when the harassers are your friends.","hook":"Veer realises his own mates are the harassers. What does an ally do?","options":[{"text":"Refuse to join, say it's not okay, back off if it heats up","consequence":"You shift the tone safely without becoming a target.","outcome":"safe","best":true},{"text":"Join in so they don't turn on you","consequence":"Joining adds to the harm; you can refuse instead."}],"debrief":"An ally can refuse to join even when it's their own friends."},
  {"id":"st-1434","cat":"spot-harassment","type":"branch","persona":"any","source":"safety-first","relearn":"Read the freeze, then distract gently, your safety comes first.","hook":"A girl is frozen as a man crowds her. You've read the cue. The safe first move?","options":[{"text":"Walk over: 'There you are! Come, we're late'","consequence":"A friendly distraction helps her leave, no confronting.","outcome":"safe","best":true},{"text":"March up and fight the man","consequence":"Confronting is risky; a calm distraction is safer."}],"debrief":"Reading the freeze, a gentle distraction safely gives her an exit."},
  {"id":"st-1435","cat":"spot-harassment","type":"branch","persona":"any","source":"naming voice","relearn":"Help someone read it: was it unwanted and ignored?","hook":"A junior asks, 'was that harassment, or am I overthinking?' You respond?","options":[{"text":"Help her test it: was it unwanted and ignored?","consequence":"She gets a clear way to read it and trust herself.","outcome":"safe","best":true},{"text":"Tell her she's probably overthinking it","consequence":"Dismissing her teaches her to doubt real warnings."}],"debrief":"Help her use the welcomeness test instead of doubting herself."},
  {"id":"st-1436","cat":"spot-harassment","type":"branch","persona":"Veer","source":"self-accountability","relearn":"Spotting harassment includes an honest read of your own comments.","hook":"You're unsure if your own comment crossed a line. The honest move?","options":[{"text":"Check if it was unwanted; if so, stop and apologise","consequence":"Honest self-reading avoids harassing without meaning to.","outcome":"safe","best":true},{"text":"Decide it's fine, you 'meant it nicely'","consequence":"Intent isn't the test; whether it was welcome is."}],"debrief":"Reading harassment includes honestly checking your own behaviour."},
];

